46	Code2WavRunner::Code2WavRunner(std::string const& engineDir, cudaStream_t stream)
47	{
48	    bool const configValid = validateAndFillConfig(engineDir);
49	    ELLM_CHECK(configValid, "Failed to validate and fill config");
50	
51	    mRuntime = std::unique_ptr<nvinfer1::IRuntime>(nvinfer1::createInferRuntime(gLogger));
52	    ELLM_CHECK(mRuntime, "Failed to create TensorRT runtime");
53	
54	    std::string const code2wavEnginePath = engineDir + "/code2wav.engine";
55	    ELLM_CHECK(std::filesystem::exists(code2wavEnginePath), "Code2Wav engine not found at " + code2wavEnginePath);
56	
57	    try
58	    {
59	        mCode2WavEngine = deserializeCudaEngineFromFile(*mRuntime, code2wavEnginePath);
60	
61	        mCode2WavContext = std::unique_ptr<nvinfer1::IExecutionContext>(mCode2WavEngine->createExecutionContext());
62	        ELLM_CHECK(mCode2WavContext, "Failed to create Code2Wav execution context");
63	
64	        bool const profileSet = mCode2WavContext->setOptimizationProfileAsync(0, stream);
65	        ELLM_CHECK(profileSet, "Failed to set optimization profile");
66	
67	        setNonBlockingAuxStreams(mCode2WavContext.get(), mCode2WavEngine.get(), mAuxStreams);
68	
69	        CUDA_CHECK(cudaStreamSynchronize(stream));
70	    }
71	    catch (std::exception const& e)
72	    {
73	        LOG_ERROR("Failed to load Code2Wav engine: %s", e.what());
74	        throw;
75	    }
76	
77	    bool const bufferAllocated = allocateBuffer();
78	    ELLM_CHECK(bufferAllocated, "Failed to allocate buffers");
79	
80	    LOG_INFO("Code2Wav runner initialized successfully");
81	}
