83	bool Code2WavRunner::validateAndFillConfig(std::string const& engineDir)
84	{
85	    std::string const configPath = engineDir + "/config.json";
86	    std::ifstream configFileStream(configPath);
87	    if (!configFileStream.is_open())
88	    {
89	        LOG_ERROR("Failed to open config file: %s", configPath.c_str());
90	        return false;
91	    }
92	
93	    Json jsonConfig;
94	    try
95	    {
96	        jsonConfig = Json::parse(configFileStream);
97	        configFileStream.close();
98	    }
99	    catch (Json::parse_error const& e)
100	    {
101	        LOG_ERROR("Failed to parse config file: %s", e.what());
102	        return false;
103	    }
104	
105	    Json const& cfg = jsonConfig.contains("code2wav_config") ? jsonConfig["code2wav_config"] : jsonConfig;
106	
107	    if (!cfg.contains("num_quantizers"))
108	    {
109	        LOG_ERROR("num_quantizers not found in config.json");
110	        return false;
111	    }
112	    mConfig.numQuantizers = cfg["num_quantizers"].get<int32_t>();
113	
114	    mConfig.codebookSize = cfg.value("codebook_size", mConfig.codebookSize);
115	    mConfig.hiddenSize = cfg.value("hidden_size", mConfig.hiddenSize);
116	    mConfig.decoderDim = cfg.value("decoder_dim", mConfig.decoderDim);
117	
118	    int64_t rate = 1;
119	    if (cfg.contains("upsample_rates"))
120	    {
121	        for (auto const& r : cfg["upsample_rates"])
122	        {
123	            rate *= r.get<int64_t>();
124	        }
125	    }
126	    if (cfg.contains("upsampling_ratios"))
127	    {
128	        for (auto const& r : cfg["upsampling_ratios"])
129	        {
130	            rate *= r.get<int64_t>();
131	        }
132	    }
133	    if (rate > 1)
134	    {
135	        mConfig.upsampleRate = math::cast<int32_t>(rate);
136	    }
137	    else
138	    {
139	        LOG_ERROR("Failed to calculate upsample_rate from config");
140	        return false;
141	    }
142	
143	    if (jsonConfig.contains("builder_config"))
144	    {
145	        auto const& builderConfig = jsonConfig["builder_config"];
146	        mConfig.chunkSize = builderConfig.value("opt_code_len", mConfig.chunkSize);
147	    }
148	
149	    LOG_INFO("Code2Wav config: numQuantizers=%d, codebookSize=%d, upsampleRate=%d, chunkSize=%d", mConfig.numQuantizers,
150	        mConfig.codebookSize, mConfig.upsampleRate, mConfig.chunkSize);
151	
152	    return true;
153	}
