155	bool Code2WavRunner::allocateBuffer()
156	{
157	    if (!mCode2WavEngine || !mCode2WavContext)
158	    {
159	        LOG_ERROR("Cannot allocate buffers - engine not loaded");
160	        return false;
161	    }
162	
163	    nvinfer1::Dims const codesShapeMax
164	        = mCode2WavEngine->getProfileShape(binding_names::kCode2WavCodes, 0, nvinfer1::OptProfileSelector::kMAX);
165	
166	    int64_t const maxSeqLen = codesShapeMax.d[2];
167	    int64_t const maxWaveformLen = maxSeqLen * mConfig.upsampleRate;
168	
169	    // Detect engine's actual waveform output dtype (FP16 for Qwen3-Omni code2wav,
170	    // FP32 for Qwen3-TTS tokenizer_decoder). Allocating the wrong dtype reinterprets bytes
171	    // and produces garbled audio.
172	    mWaveformDtype = mCode2WavEngine->getTensorDataType(binding_names::kCode2WavWaveform);
173	    LOG_INFO("Code2Wav waveform output dtype: %s",
174	        mWaveformDtype == nvinfer1::DataType::kHALF        ? "FP16"
175	            : mWaveformDtype == nvinfer1::DataType::kFLOAT ? "FP32"
176	                                                           : "UNKNOWN");
177	
178	    mInputCodesDevice
179	        = rt::Tensor({1, mConfig.numQuantizers, maxSeqLen}, rt::DeviceType::kGPU, nvinfer1::DataType::kINT64);
180	    mOutputWaveform = rt::Tensor({1, 1, maxWaveformLen}, rt::DeviceType::kGPU, mWaveformDtype);
181	    mInputCodesHost
182	        = rt::Tensor({1, mConfig.numQuantizers, maxSeqLen}, rt::DeviceType::kCPU, nvinfer1::DataType::kINT64);
183	
184	    bool setTensorAddressStatus = true;
185	    setTensorAddressStatus
186	        &= mCode2WavContext->setTensorAddress(binding_names::kCode2WavCodes, mInputCodesDevice.rawPointer());
187	    setTensorAddressStatus
188	        &= mCode2WavContext->setTensorAddress(binding_names::kCode2WavWaveform, mOutputWaveform.rawPointer());
189	    if (!setTensorAddressStatus)
190	    {
191	        LOG_ERROR("Failed to set tensor addresses");
192	        return false;
193	    }
194	
195	    LOG_INFO("Buffers allocated: maxSeqLen=%ld, maxWaveformLen=%ld", maxSeqLen, maxWaveformLen);
196	    return true;
197	}
