199	bool Code2WavRunner::infer(cudaStream_t stream)
200	{
201	    TIME_STAGE(metrics::StageNames::kCODE2WAV, stream);
202	
203	    nvinfer1::Dims const codeDims = mInputCodesDevice.getTRTDims();
204	    if (!mCode2WavContext->setInputShape(binding_names::kCode2WavCodes, codeDims))
205	    {
206	        LOG_ERROR("Failed to set input shape");
207	        return false;
208	    }
209	
210	    if (!mCode2WavContext->enqueueV3(stream))
211	    {
212	        LOG_ERROR("Inference failed");
213	        return false;
214	    }
215	
216	    return true;
217	}
