219	bool Code2WavRunner::prepareCodes(std::vector<std::vector<int32_t>> const& codes, cudaStream_t stream)
220	{
221	    if (codes.empty() || codes[0].empty())
222	    {
223	        LOG_ERROR("Empty codes provided");
224	        return false;
225	    }
226	
227	    int64_t const numLayers = math::cast<int64_t>(codes.size());
228	    int64_t const seqLen = math::cast<int64_t>(codes[0].size());
229	
230	    if (numLayers != mConfig.numQuantizers)
231	    {
232	        LOG_ERROR("Expected %d quantizer layers, got %ld", mConfig.numQuantizers, numLayers);
233	        return false;
234	    }
235	
236	    for (size_t i = 1; i < codes.size(); ++i)
237	    {
238	        if (math::cast<int64_t>(codes[i].size()) != seqLen)
239	        {
240	            LOG_ERROR("Inconsistent code lengths: layer 0 has %ld, layer %zu has %zu", seqLen, i, codes[i].size());
241	            return false;
242	        }
243	    }
244	
245	    if (!mInputCodesDevice.reshape({1, numLayers, seqLen}))
246	    {
247	        LOG_ERROR("Failed to reshape input codes tensor");
248	        return false;
249	    }
250	
251	    int64_t* const hostData = static_cast<int64_t*>(mInputCodesHost.rawPointer());
252	    for (int64_t layer = 0; layer < numLayers; ++layer)
253	    {
254	        for (int64_t t = 0; t < seqLen; ++t)
255	        {
256	            hostData[layer * seqLen + t] = math::cast<int64_t>(codes[layer][t]);
257	        }
258	    }
259	
260	    size_t const copySize = math::cast<size_t>(numLayers * seqLen) * sizeof(int64_t);
261	    CUDA_CHECK(cudaMemcpyAsync(mInputCodesDevice.rawPointer(), hostData, copySize, cudaMemcpyHostToDevice, stream));
262	
263	    return true;
264	}
