266	bool Code2WavRunner::runChunkedInference(
267	    std::vector<std::vector<int32_t>> const& codes, rt::Tensor& outputWaveform, cudaStream_t stream)
268	{
269	    int64_t const totalLen = math::cast<int64_t>(codes[0].size());
270	    int64_t const chunkSize = mConfig.chunkSize;
271	    int64_t const contextSize = mConfig.leftContextSize;
272	
273	    std::vector<rt::Tensor> waveformChunks;
274	    std::vector<std::vector<int32_t>> chunkCodes(mConfig.numQuantizers);
275	    int64_t startIdx = 0;
276	    int32_t chunkIdx = 0;
277	
278	    while (startIdx < totalLen)
279	    {
280	        int64_t const endIdx = std::min(startIdx + chunkSize, totalLen);
281	        int64_t const actualContextSize = (startIdx >= contextSize) ? contextSize : startIdx;
282	        int64_t const actualChunkLen = (endIdx - startIdx) + actualContextSize;
283	
284	        // Extract chunk with context
285	        for (int32_t layer = 0; layer < mConfig.numQuantizers; ++layer)
286	        {
287	            chunkCodes[layer].assign(
288	                codes[layer].begin() + (startIdx - actualContextSize), codes[layer].begin() + endIdx);
289	        }
290	
291	        if (!prepareCodes(chunkCodes, stream))
292	        {
293	            return false;
294	        }
295	
296	        if (!infer(stream))
297	        {
298	            return false;
299	        }
300	
301	        // Get actual output length from engine (shorter than frames * upsampleRate
302	        // due to CausalConvNet padding loss in Code2Wav)
303	        nvinfer1::Dims const outDims = mCode2WavContext->getTensorShape(binding_names::kCode2WavWaveform);
304	        int64_t const actualOutputLen = outDims.d[outDims.nbDims - 1];
305	
306	        // Trim context from the beginning (matches PyTorch: wav[..., context * upsample :])
307	        int64_t const contextSamples = actualContextSize * mConfig.upsampleRate;
308	        int64_t const validLen = actualOutputLen - contextSamples;
309	
310	        LOG_DEBUG("Chunk %d: codes_len=%ld, context=%ld, actual_output=%ld, context_samples=%ld, valid_len=%ld",
311	            chunkIdx, actualChunkLen, actualContextSize, actualOutputLen, contextSamples, validLen);
312	
313	        rt::Tensor chunkWaveform({1, 1, validLen}, rt::DeviceType::kGPU, mWaveformDtype);
314	        CUDA_CHECK(cudaMemcpyAsync(chunkWaveform.rawPointer(),
315	            static_cast<char*>(mOutputWaveform.rawPointer()) + contextSamples * rt::utils::getTypeSize(mWaveformDtype),
316	            math::cast<size_t>(validLen) * rt::utils::getTypeSize(mWaveformDtype), cudaMemcpyDeviceToDevice, stream));
317	
318	        waveformChunks.push_back(std::move(chunkWaveform));
319	        startIdx = endIdx;
320	        ++chunkIdx;
321	    }
322	
323	    LOG_INFO("Processed %d chunks", chunkIdx);
324	
325	    int64_t totalSamples = 0;
326	    for (auto const& chunk : waveformChunks)
327	    {
328	        totalSamples += chunk.getShape()[2];
329	    }
330	
331	    outputWaveform = rt::Tensor({1, 1, totalSamples}, rt::DeviceType::kGPU, mWaveformDtype);
332	
333	    int64_t offset = 0;
334	    for (auto const& chunk : waveformChunks)
335	    {
336	        int64_t const chunkLen = chunk.getShape()[2];
337	        CUDA_CHECK(cudaMemcpyAsync(
338	            static_cast<char*>(outputWaveform.rawPointer()) + offset * rt::utils::getTypeSize(mWaveformDtype),
339	            chunk.rawPointer(), math::cast<size_t>(chunkLen) * rt::utils::getTypeSize(mWaveformDtype),
340	            cudaMemcpyDeviceToDevice, stream));
341	        offset += chunkLen;
342	    }
343	
344	    CUDA_CHECK(cudaStreamSynchronize(stream));
345	    return true;
346	}
347	
348	bool Code2WavRunner::generateWaveform(
349	    std::vector<std::vector<int32_t>> const& codes, rt::audioUtils::AudioData& outputAudio, cudaStream_t stream)
350	{
351	    if (codes.empty() || codes[0].empty())
352	    {
353	        LOG_ERROR("Empty codes provided");
354	        return false;
355	    }
356	
357	    int64_t const seqLen = math::cast<int64_t>(codes[0].size());
358	    // Query engine's actual max profile (not mInputCodesDevice.getShape() which is mutated by prepareCodes).
359	    nvinfer1::Dims const codesShapeMax
360	        = mCode2WavEngine->getProfileShape(binding_names::kCode2WavCodes, 0, nvinfer1::OptProfileSelector::kMAX);
361	    int64_t const maxCodeLen = codesShapeMax.d[2];
362	    int64_t waveformLen = 0;
363	
364	    // Use direct inference if sequence fits in engine's max capacity
365	    if (seqLen <= maxCodeLen)
366	    {
367	        LOG_DEBUG("Direct inference: seqLen=%ld", seqLen);
368	
369	        if (!prepareCodes(codes, stream))
370	        {
371	            return false;
372	        }
373	
374	        if (!infer(stream))
375	        {
376	            return false;
377	        }
378	
379	        // Get actual output shape from the engine. Code2Wav output can be shorter than
380	        // seqLen * upsampleRate because the model trims samples at the boundaries.
381	        nvinfer1::Dims const outDims = mCode2WavContext->getTensorShape(binding_names::kCode2WavWaveform);
382	        int64_t const engineWaveformLen = outDims.d[outDims.nbDims - 1];
383	        int64_t const expectedWaveformLen = seqLen * mConfig.upsampleRate;
384	        // Some vocoder ONNX (e.g. Qwen3-TTS tokenizer_decoder) always return the max-profile output
385	        // length even though only the first `seqLen * upsampleRate` samples are valid audio.
386	        // Trim to the expected length so downstream consumers don't pick up stale buffer content.
387	        waveformLen = std::min(engineWaveformLen, expectedWaveformLen);
388	
389	        outputAudio.waveform
390	            = std::make_shared<rt::Tensor>(rt::Tensor({1, waveformLen}, rt::DeviceType::kCPU, mWaveformDtype));
391	        CUDA_CHECK(cudaMemcpyAsync(outputAudio.waveform->rawPointer(), mOutputWaveform.rawPointer(),
392	            math::cast<size_t>(waveformLen) * rt::utils::getTypeSize(mWaveformDtype), cudaMemcpyDeviceToHost, stream));
393	    }
394	    else
395	    {
396	        // Chunked inference for sequences exceeding engine's max capacity
397	        LOG_INFO("Using chunked inference for long sequence (len=%ld, max=%ld)", seqLen, maxCodeLen);
398	        rt::Tensor finalWaveform;
399	        if (!runChunkedInference(codes, finalWaveform, stream))
400	        {
401	            return false;
402	        }
403	
404	        auto const& finalShape = finalWaveform.getShape();
405	        waveformLen = finalShape[finalShape.getNumDims() - 1];
406	
407	        outputAudio.waveform
408	            = std::make_shared<rt::Tensor>(rt::Tensor({1, waveformLen}, rt::DeviceType::kCPU, mWaveformDtype));
409	        CUDA_CHECK(cudaMemcpyAsync(outputAudio.waveform->rawPointer(), finalWaveform.rawPointer(),
410	            math::cast<size_t>(waveformLen) * rt::utils::getTypeSize(mWaveformDtype), cudaMemcpyDeviceToHost, stream));
411	    }
412	
413	    CUDA_CHECK(cudaStreamSynchronize(stream));
414	
415	    outputAudio.sampleRate = mConfig.sampleRate;
416	    outputAudio.numChannels = 1;
417	    outputAudio.hasWaveform = true;
418	
419	    return true;
420	}
421	
