69	Qwen3OmniAudioRunner::Qwen3OmniAudioRunner(std::string const& engineDir, cudaStream_t stream)
70	    : MultimodalRunner()
71	{
72	    bool const configValid = validateAndFillConfig(engineDir);
73	    ELLM_CHECK(configValid, "Failed to validate and fill config");
74	
75	    mRuntime = std::unique_ptr<nvinfer1::IRuntime>(nvinfer1::createInferRuntime(gLogger));
76	
77	    // Initialize audio encoder (engineDir is already the audio subdirectory)
78	    std::string audioEnginePath = engineDir + "/audio_encoder.engine";
79	    if (std::filesystem::exists(audioEnginePath))
80	    {
81	        LOG_INFO("Loading audio encoder from %s", audioEnginePath.c_str());
82	        try
83	        {
84	            mAudioEngine = deserializeCudaEngineFromFile(*mRuntime, audioEnginePath);
85	
86	            mAudioContext = std::unique_ptr<nvinfer1::IExecutionContext>(mAudioEngine->createExecutionContext());
87	            ELLM_CHECK(mAudioContext, "Failed to create audio encoder context");
88	
89	            bool const profileSet = mAudioContext->setOptimizationProfileAsync(0, stream);
90	            ELLM_CHECK(profileSet, "Failed to set optimization profile for audio encoder");
91	
92	            setNonBlockingAuxStreams(mAudioContext.get(), mAudioEngine.get(), mAuxStreams);
93	        }
94	        catch (std::exception const& e)
95	        {
96	            LOG_ERROR("Failed to load audio encoder: %s", e.what());
97	            throw;
98	        }
99	    }
100	    else
101	    {
102	        throw std::runtime_error("Audio encoder not found at " + audioEnginePath);
103	    }
104	
105	    bool const bufferAllocated = allocateBuffer(stream);
106	    ELLM_CHECK(bufferAllocated, "Failed to allocate buffers");
107	
108	    // Best-effort init of the online GPU fbank. Failure is non-fatal: the
109	    // runner falls back to the CPU MelExtractor (mFeMel, already bound by
110	    // validateAndFillConfig above) for PCM→mel. initFbankResources issues H2D
111	    // copies via CUDA_CHECK, which throws on failure (e.g. device OOM), so
112	    // catch here to keep construction non-fatal.
113	    try
114	    {
115	        mFbankReady = initFbankResources(stream);
116	        if (!mFbankReady)
117	        {
118	            // initFbankResources already logged the specific reason; add the consequence.
119	            LOG_WARNING("Online GPU fbank unavailable; using CPU MelExtractor for PCM→mel.");
120	        }
121	    }
122	    catch (std::exception const& e)
123	    {
124	        mFbankReady = false;
125	        LOG_WARNING("Online GPU fbank init failed (%s); using CPU MelExtractor for PCM→mel.", e.what());
126	    }
127	
128	    LOG_INFO("Qwen3OmniAudioRunner initialized successfully");
129	}
