131	bool Qwen3OmniAudioRunner::validateAndFillConfig(std::string const& engineDir)
132	{
133	    // Read config.json
134	    std::string configPath = engineDir + "/config.json";
135	    std::ifstream configFileStream(configPath);
136	    if (!configFileStream.is_open())
137	    {
138	        LOG_ERROR("Failed to open config file: %s", configPath.c_str());
139	        return false;
140	    }
141	
142	    Json jsonConfig;
143	    try
144	    {
145	        jsonConfig = Json::parse(configFileStream);
146	        configFileStream.close();
147	    }
148	    catch (Json::parse_error const& e)
149	    {
150	        LOG_ERROR("Failed to parse config file: %s", e.what());
151	        return false;
152	    }
153	
154	    // Parse audio configuration
155	    if (jsonConfig.contains("audio_config"))
156	    {
157	        auto audioConfig = jsonConfig["audio_config"];
158	        mConfig.melBins = audioConfig.value("num_mel_bins", 128);
159	        mConfig.audioFeatureDim = audioConfig.value("output_dim", 2560);
160	        mConfig.nWindow = audioConfig.value("n_window", 50);
161	        mConfig.nWindowInfer = audioConfig.value("n_window_infer", 200);
162	    }
163	    else
164	    {
165	        LOG_WARNING("audio_config not found in config.json, using default values");
166	    }
167	
168	    // Parse audio special token IDs from top-level config (may differ between Qwen3-Omni and Qwen3-ASR)
169	    if (jsonConfig.contains("audio_token_id"))
170	    {
171	        mConfig.audioTokenId = jsonConfig["audio_token_id"].get<int32_t>();
172	    }
173	    LOG_DEBUG("Audio token IDs: audio_pad=%d", mConfig.audioTokenId);
174	
175	    // Parse rope_theta for MRope initialization (from text_config or top-level)
176	    if (jsonConfig.contains("text_config") && jsonConfig["text_config"].contains("rope_theta"))
177	    {
178	        mConfig.mropeTheta = jsonConfig["text_config"]["rope_theta"].get<float>();
179	    }
180	    else if (jsonConfig.contains("rope_theta"))
181	    {
182	        mConfig.mropeTheta = jsonConfig["rope_theta"].get<float>();
183	    }
184	
185	    // Pick mel feature-extractor family from the audio engine's top-level
186	    // ``model_type`` (export.py writes ``qwen3_asr_thinker`` /
187	    // ``qwen3_omni_audio_encoder`` here). Runner owns mel extraction;
188	    // callers hand off raw PCM.
189	    std::string const audioModelType = jsonConfig.value("model_type", "");
190	    if (audioModelType == "qwen3_asr_thinker" || audioModelType == "qwen3_omni_audio_encoder")
191	    {
192	        mFeMel = rt::audio::makeWhisperExtractor();
193	    }
194	    else
195	    {
196	        LOG_ERROR(
197	            "Unsupported audio model_type %s for Qwen3OmniAudioRunner (expected qwen3_asr_thinker / "
198	            "qwen3_omni_audio_encoder)",
199	            audioModelType.c_str());
200	        return false;
201	    }
202	
203	    return true;
204	}
