206	bool Qwen3OmniAudioRunner::allocateBuffer([[maybe_unused]] cudaStream_t stream)
207	{
208	    if (!mAudioEngine || !mAudioContext)
209	    {
210	        LOG_ERROR("Cannot allocate buffers - audio encoder not loaded");
211	        return false;
212	    }
213	
214	    // Get max shapes from optimization profile using tensor names directly
215	    nvinfer1::Dims paddedFeaturesShapeMax
216	        = mAudioEngine->getProfileShape(binding_names::kAudioPaddedFeatures, 0, nvinfer1::OptProfileSelector::kMAX);
217	    nvinfer1::Dims paddedMaskIndicesShapeMax
218	        = mAudioEngine->getProfileShape(binding_names::kAudioPaddedMaskIndices, 0, nvinfer1::OptProfileSelector::kMAX);
219	
220	    // Extract dimensions
221	    int64_t const melBins = mConfig.melBins;
222	    int64_t const audioFeatureDim = mConfig.audioFeatureDim;       // Use config value, not output shape
223	    int64_t const maxAudioTokens = paddedMaskIndicesShapeMax.d[0]; // Max attention elements = max audio tokens
224	
225	    // Allocate tensors
226	    int64_t const maxNumChunks = paddedFeaturesShapeMax.d[0];
227	    int64_t const maxChunkLen = paddedFeaturesShapeMax.d[2];
228	    mPaddedFeature = rt::Tensor({maxNumChunks, melBins, maxChunkLen}, rt::DeviceType::kGPU, nvinfer1::DataType::kHALF);
229	
230	    int64_t const maxLenAfterCNN = (maxChunkLen - 1) / 2 + 1;
231	    mPaddedMaskAfterCNN = rt::Tensor({maxNumChunks, maxLenAfterCNN}, rt::DeviceType::kGPU, nvinfer1::DataType::kINT64);
232	
233	    int64_t const maxValidElements = paddedMaskIndicesShapeMax.d[0];
234	    mPaddedMaskIndices = rt::Tensor({maxValidElements, 2}, rt::DeviceType::kGPU, nvinfer1::DataType::kINT64);
235	
236	    mAudioEmbedding = rt::Tensor({maxAudioTokens, audioFeatureDim}, rt::DeviceType::kGPU, nvinfer1::DataType::kHALF);
237	
238	    int64_t maxSeqlensHostCapacity = 0;
239	    mHasCuSeqlens = isEngineInput(*mAudioEngine, binding_names::kCuSeqlens);
240	    if (mHasCuSeqlens)
241	    {
242	        nvinfer1::Dims const cuSeqlensShapeMax
243	            = mAudioEngine->getProfileShape(binding_names::kCuSeqlens, 0, nvinfer1::OptProfileSelector::kMAX);
244	        int64_t const maxCuSeqlens = cuSeqlensShapeMax.d[0];
245	        maxSeqlensHostCapacity = std::max(maxSeqlensHostCapacity, maxCuSeqlens);
246	        mCuSeqlens = rt::Tensor(
247	            {maxCuSeqlens}, rt::DeviceType::kGPU, nvinfer1::DataType::kINT32, "Qwen3OmniAudioRunner::mCuSeqlens");
248	        if (!mAudioContext->setTensorAddress(binding_names::kCuSeqlens, mCuSeqlens.rawPointer()))
249	        {
250	            LOG_ERROR("Failed to set cu_seqlens input address");
251	            return false;
252	        }
253	    }
254	
255	    mHasKvLengths = isEngineInput(*mAudioEngine, binding_names::kKvLengths);
256	    if (mHasKvLengths)
257	    {
258	        nvinfer1::Dims const kvLengthsShapeMax
259	            = mAudioEngine->getProfileShape(binding_names::kKvLengths, 0, nvinfer1::OptProfileSelector::kMAX);
260	        int64_t const maxKvLengths = kvLengthsShapeMax.d[0];
261	        maxSeqlensHostCapacity = std::max(maxSeqlensHostCapacity, maxKvLengths);
262	        mKvLengths = rt::Tensor(
263	            {maxKvLengths}, rt::DeviceType::kGPU, nvinfer1::DataType::kINT32, "Qwen3OmniAudioRunner::mKvLengths");
264	        if (!mAudioContext->setTensorAddress(binding_names::kKvLengths, mKvLengths.rawPointer()))
265	        {
266	            LOG_ERROR("Failed to set kv_lengths input address");
267	            return false;
268	        }
269	    }
270	
271	    if (maxSeqlensHostCapacity > 0)
272	    {
273	        mCuSeqlensHost = rt::Tensor({maxSeqlensHostCapacity}, rt::DeviceType::kCPU, nvinfer1::DataType::kINT32,
274	            "Qwen3OmniAudioRunner::mCuSeqlensHost");
275	    }
276	
277	    return true;
278	}
