280	bool Qwen3OmniAudioRunner::preprocess(rt::LLMGenerationRequest const& request,
281	    std::vector<std::vector<int32_t>>& batchedInputIds, tokenizer::Tokenizer const* tokenizer,
282	    rt::OptionalOutputTensor mropeCosSinOut, cudaStream_t stream, [[maybe_unused]] bool imageOnly)
283	{
284	    if (!mropeCosSinOut.has_value())
285	    {
286	        LOG_ERROR("mropeCosSinOut is required (this runner is MRope-only).");
287	        return false;
288	    }
289	
290	    std::vector<int64_t> audioTokenLengths;
291	
292	    // Step 1: Process audio inputs to get embeddings and token lengths
293	    for (auto const& req : request.requests)
294	    {
295	        if (!req.audioBuffers.empty())
296	        {
297	            if (!preprocessAudio(req.audioBuffers, audioTokenLengths, stream))
298	            {
299	                LOG_ERROR("Audio preprocessing failed");
300	                return false;
301	            }
302	        }
303	        else
304	        {
305	            // No audio in this request, add 0 length
306	            audioTokenLengths.push_back(0);
307	        }
308	    }
309	
310	    // Step 2: Tokenize and replace audio tokens (similar to QwenViTRunner::textPreprocess)
311	    textPreprocess(request, batchedInputIds, audioTokenLengths, tokenizer);
312	
313	    // Step 3: Initialize sequential MRope cache if applicable.
314	    // For audio+text only (no vision), all 3 MRope dimensions (T, H, W) use identical sequential positions.
315	    // When a vision runner is also present, QwenViTRunner::preprocess will overwrite the MRope cache
316	    // with vision-aware position IDs, so this initialization is harmlessly overwritten.
317	    int64_t const activeBatchSize = static_cast<int64_t>(request.requests.size());
318	    if (!initializeSequentialMRopeCache(activeBatchSize, mropeCosSinOut.value().get(), stream))
319	    {
320	        LOG_ERROR("Failed to initialize sequential MRope cache for audio input.");
321	        return false;
322	    }
323	
324	    return true;
325	}
