327	void Qwen3OmniAudioRunner::textPreprocess(rt::LLMGenerationRequest const& request,
328	    std::vector<std::vector<int32_t>>& batchInputIds, std::vector<int64_t> const& audioTokenLengths,
329	    tokenizer::Tokenizer const* tokenizer)
330	{
331	    ELLM_CHECK(audioTokenLengths.size() == request.requests.size(),
332	        "audioTokenLengths.size() != request.requests.size(), " + std::to_string(audioTokenLengths.size())
333	            + " != " + std::to_string(request.requests.size()));
334	
335	    for (size_t i = 0; i < request.requests.size(); ++i)
336	    {
337	        std::vector<int32_t> ids;
338	
339	        // Check if already tokenized (incremental mode)
340	        if (i < batchInputIds.size() && !batchInputIds[i].empty())
341	        {
342	            // Already tokenized by another runner, use existing tokens
343	            ids = batchInputIds[i];
344	        }
345	        else
346	        {
347	            // First runner to process, tokenize the request
348	            ids = tokenizer->encode(request.formattedRequests[i].formattedCompleteRequest);
349	        }
350	
351	        // Insert audio tokens if present
352	        if (audioTokenLengths[i] > 0)
353	        {
354	            std::vector<int32_t> newIds;
355	            for (size_t j = 0; j < ids.size(); ++j)
356	            {
357	                if (ids[j] == mConfig.audioTokenId)
358	                {
359	                    // Expand the <|audio_pad|> placeholder to N×<|audio_pad|> in place. The <|audio_start|>/
360	                    // <|audio_end|> markers come from the (unified) chat template, so we do NOT re-add them here.
361	                    int64_t numAudioTokens = audioTokenLengths[i];
362	                    for (int64_t k = 0; k < numAudioTokens; ++k)
363	                    {
364	                        newIds.push_back(mConfig.audioTokenId);
365	                    }
366	                }
367	                else
368	                {
369	                    newIds.push_back(ids[j]);
370	                }
371	            }
372	
373	            // Update batchInputIds
374	            if (i < batchInputIds.size())
375	            {
376	                batchInputIds[i] = std::move(newIds);
377	            }
378	            else
379	            {
380	                batchInputIds.emplace_back(std::move(newIds));
381	            }
382	        }
383	        else
384	        {
385	            // No audio in this request, keep original tokens
386	            if (i < batchInputIds.size())
387	            {
388	                batchInputIds[i] = std::move(ids);
389	            }
390	            else
391	            {
392	                batchInputIds.emplace_back(std::move(ids));
393	            }
394	        }
395	    }
396	}
