401	// The GPU fbank kernel suite hard-codes the Whisper choices (N=400 FFT, periodic
402	// Hann, reflect-pad, log10 + max-floor, whisper-clamp post-norm, [nMel,T] layout,
403	// drop-last-frame, no pre-emphasis). Validate the bound MelExtractor's config is
404	// Whisper-spec before enabling online fbank; any mismatch (e.g. a Parakeet
405	// extractor) cleanly falls back to the CPU path instead of silently producing a
406	// wrong spectrogram. The config is the single source of truth — these are the
407	// only places the "expected Whisper spec" literals live.
408	bool whisperFbankConfigOk(audio::MelExtractorConfig const& cfg, std::string& reason)
409	{
410	    auto fail = [&reason](char const* msg) {
411	        reason = msg;
412	        return false;
413	    };
414	    // Shape: the kernel FFT is N=400-specific and the encoder takes [1, 128, T].
415	    if (!(cfg.nFFT == 400 && cfg.winLength == cfg.nFFT && cfg.nMel == 128))
416	        return fail("needs nFFT==400, winLength==nFFT, nMel==128.");
417	    // Windowing / framing.
418	    if (!(cfg.windowType == audio::WindowType::kHannPeriodic && cfg.framePadding == audio::FramePadding::kCenterReflect
419	            && cfg.preemphCoeff == 0.0f))
420	        return fail("needs periodic Hann window, centre-reflect framing, no pre-emphasis.");
421	    // Log + post-normalize.
422	    if (!(cfg.logType == audio::LogType::kLog10 && cfg.logFloorMode == audio::LogFloorMode::kMax
423	            && cfg.postNormalize == audio::PostNormalize::kWhisperClamp))
424	        return fail("needs log10 + max-floor + Whisper-clamp post-normalize.");
425	    // Layout + dynamic T.
426	    if (!(cfg.layout == audio::MelLayout::kMelTime && cfg.dropLastStftFrame
427	            && cfg.timePadding == audio::TimePadding::kNone))
428	        return fail("needs [nMel, T] layout, drop-last-frame, no static time padding.");
429	    return true;
430	}
