434	bool Qwen3OmniAudioRunner::initFbankResources(cudaStream_t stream)
435	{
436	    // The bound CPU MelExtractor's config is the single source of truth for every
437	    // STFT/mel param AND the mel filter weights. The GPU kernels hard-code the
438	    // Whisper choices, so validate the config is Whisper-spec before enabling —
439	    // otherwise fall back to CPU.
440	    audio::MelExtractorConfig const& cfg = mFeMel.config();
441	    std::string reason;
442	    if (!whisperFbankConfigOk(cfg, reason))
443	    {
444	        LOG_WARNING("Online GPU fbank disabled (extractor not Whisper-spec): %s", reason.c_str());
445	        return false;
446	    }
447	    int32_t const nFft = cfg.nFFT;
448	    int32_t const nMel = cfg.nMel;
449	    int32_t const nFreq = nFft / 2 + 1;
450	
451	    // Single source of truth for the mel filter: reuse the exact Slaney weights
452	    // the CPU MelExtractor (mFeMel) was built with, so the GPU fbank and the CPU
453	    // fallback can never drift apart. No external mel_filter.bin to ship or keep
454	    // in sync. buildMelFilterBank already emits the [nMel, nBins] (nMel-major,
455	    // freq-contiguous) layout the GEMM A-matrix wants, so this is a pure FP16
456	    // cast + K-pad — no transpose.
457	    std::vector<float> const& melFilterHost = mFeMel.melFilterBank(); // [nMel, nBins] row-major F32
458	    if (melFilterHost.size() != static_cast<size_t>(nMel) * nFreq)
459	    {
460	        LOG_WARNING("Online fbank disabled: mel filter size %zu != %d x %d.", melFilterHost.size(), nMel, nFreq);
461	        return false;
462	    }
463	
464	    // Single source of truth for the window: reuse the exact periodic-Hann taps
465	    // the CPU MelExtractor built (buildWindow), so the GPU fbank and the CPU
466	    // fallback can never drift. The config gate guarantees winLength == nFft.
467	    std::vector<float> const& windowHost = mFeMel.window();
468	    if (windowHost.size() != static_cast<size_t>(nFft))
469	    {
470	        LOG_WARNING("Online GPU fbank disabled: window size %zu != nFft=%d.", windowHost.size(), nFft);
471	        return false;
472	    }
473	
474	#ifdef CUTE_DSL_GEMM_ENABLED
475	    // Idempotent + thread-safe; returns false (with its own LOG_ERROR) when no
476	    // GEMM variant is compiled for the current SM, so online fbank fails early
477	    // here rather than dispatching to an unloaded module at the first GEMM call.
478	    if (!CuteDslGemmRunner::loadKernelModule())
479	    {
480	        LOG_ERROR("CuteDslGemmRunner::loadKernelModule failed — online fbank GEMM unavailable on this device.");
481	        return false;
482	    }
483	#else
484	    LOG_WARNING(
485	        "Online GPU fbank disabled: built without CuTe DSL GEMM (rebuild with -DENABLE_CUTE_DSL=gemm). "
486	        "Using CPU MelExtractor.");
487	    return false;
488	#endif
489	
490	    // Upper bounds from the engine kMAX profile, mirroring allocateBuffer: the
491	    // encoder consumes at most maxNumChunks × maxChunkLen mel frames, and
492	    // T_out == floor(N / hopLength) for the Whisper-gated geometry
493	    // (2 * padLength == nFft), so the largest PCM the GPU path accepts is the
494	    // largest N with T_out <= maxFrames. Longer clips exceed the encoder
495	    // profile on any path; tryOnlineGpuFbank routes them to the CPU fallback.
496	    nvinfer1::Dims const paddedFeaturesShapeMax
497	        = mAudioEngine->getProfileShape(binding_names::kAudioPaddedFeatures, 0, nvinfer1::OptProfileSelector::kMAX);
498	    int64_t const maxFrames = paddedFeaturesShapeMax.d[0] * paddedFeaturesShapeMax.d[2];
499	    if (maxFrames <= 0)
500	    {
501	        LOG_WARNING("Online GPU fbank disabled: engine kMAX profile gives non-positive max mel frames (%ld).",
502	            static_cast<long>(maxFrames));
503	        return false;
504	    }
505	    int64_t const maxPcmSamples = (maxFrames + 1) * cfg.hopLength - 1;
506	    int64_t const maxFramesFull = maxFrames + 1; // fbankWhisper frames T_full = T_out + 1
507	    int64_t const nPadMax = audioUtils::fbankNPad(static_cast<int32_t>(maxFrames));
508	
509	    // Allocate every device buffer the online fbank path uses, sized at the
510	    // bounds above.
511	    mFbankResources.melFilterFp16Kmajor
512	        = rt::Tensor({nMel, audioUtils::kFbankKPad}, rt::DeviceType::kGPU, nvinfer1::DataType::kHALF);
513	    mFbankResources.hannWindow = rt::Tensor({nFft}, rt::DeviceType::kGPU, nvinfer1::DataType::kFLOAT);
514	    mFbankResources.fftTwiddle = rt::Tensor({nFft, 2}, rt::DeviceType::kGPU, nvinfer1::DataType::kFLOAT);
515	    mFbankResources.framedF32 = rt::Tensor({maxFramesFull, nFft}, rt::DeviceType::kGPU, nvinfer1::DataType::kFLOAT);
516	    mFbankResources.magFp16
517	        = rt::Tensor({nPadMax, audioUtils::kFbankKPad}, rt::DeviceType::kGPU, nvinfer1::DataType::kHALF);
518	    mFbankResources.melPowerFp16 = rt::Tensor({nMel, nPadMax}, rt::DeviceType::kGPU, nvinfer1::DataType::kHALF);
519	    mFbankResources.maxLogScalar = rt::Tensor({1}, rt::DeviceType::kGPU, nvinfer1::DataType::kFLOAT);
520	    mPcmF32Device = rt::Tensor({maxPcmSamples}, rt::DeviceType::kGPU, nvinfer1::DataType::kFLOAT);
521	    mMelSpecDevice = rt::Tensor({1, nMel, maxFrames}, rt::DeviceType::kGPU, nvinfer1::DataType::kHALF);
522	
523	    // Fill the persistent weight / table tensors (H2D). Mel filter: cast +
524	    // K-pad the Slaney weights into the [nMel, K_pad] F16 K-major GEMM
525	    // A-matrix layout.
526	    if (!audioUtils::fillMelFilterFp16Kmajor(
527	            melFilterHost.data(), nMel, nFreq, audioUtils::kFbankKPad, mFbankResources.melFilterFp16Kmajor, stream))
528	    {
529	        return false;
530	    }
531	    CUDA_CHECK(cudaMemcpyAsync(mFbankResources.hannWindow.rawPointer(), windowHost.data(),
532	        windowHost.size() * sizeof(float), cudaMemcpyHostToDevice, stream));
533	    std::vector<float> twiddleHost;
534	    audioUtils::makeFftTwiddleHost(nFft, twiddleHost);
535	    CUDA_CHECK(cudaMemcpyAsync(mFbankResources.fftTwiddle.rawPointer(), twiddleHost.data(),
536	        twiddleHost.size() * sizeof(float), cudaMemcpyHostToDevice, stream));
537	
538	    // Publish the scalar params derived from cfg — the single source of truth
539	    // for fbankWhisper / computeNumMelFrames (no duplicated constants downstream).
540	    mFbankResources.nFft = nFft;
541	    mFbankResources.hopLength = cfg.hopLength;
542	    mFbankResources.padLength = nFft / 2;
543	    mFbankResources.nMel = nMel;
544	    mFbankResources.nFreq = nFreq;
545	    mFbankResources.maxFrames = static_cast<int32_t>(maxFrames);
546	    mFbankResources.melFloor = cfg.logFloor;
547	
548	    LOG_INFO(
549	        "Online GPU fbank ready (mel filter %d×%d Slaney reused from CPU MelExtractor → [%d, %d] F16 K-major; "
550	        "buffers pre-allocated for up to %ld mel frames).",
551	        nMel, nFreq, nMel, audioUtils::kFbankKPad, static_cast<long>(maxFrames));
552	    return true;
553	}
554	
555	bool Qwen3OmniAudioRunner::tryOnlineGpuFbank(rt::audio::AudioPCM const& pcm, rt::Tensor& melSpec, cudaStream_t stream)
556	{
557	    // Gate: online fbank ready (config validated Whisper-spec, params published
558	    // into mFbankResources), the engine mel width agrees, and the sample rate
559	    // matches what the kernels assume. The CPU MelExtractor rejects a rate
560	    // mismatch, so the GPU path must too, or it would silently produce a
561	    // wrong-but-plausible spectrogram.
562	    if (!mFbankReady || mConfig.melBins != mFbankResources.nMel || pcm.sampleRate != mFeMel.config().sampleRate)
563	    {
564	        return false;
565	    }
566	
567	    // Frame count from the host PCM length, before any upload. Clips too short
568	    // for the GPU fbank framing (numFrames <= 0; the CPU MelExtractor clamps to
569	    // >= 1 frame) and clips beyond the engine kMAX profile the fbank buffers
570	    // were pre-allocated for (numFrames > maxFrames) fall back to the CPU path
571	    // without touching the GPU.
572	    int32_t const numFrames = audioUtils::computeNumMelFrames(static_cast<int64_t>(pcm.samples.size()),
573	        mFbankResources.nFft, mFbankResources.hopLength, mFbankResources.padLength);
574	    if (numFrames <= 0 || numFrames > mFbankResources.maxFrames)
575	    {
576	        return false;
577	    }
578	
579	    // Upload host FP32 PCM [-1, 1] into the pre-allocated [N] GPU staging tensor
580	    // (metadata-only reshape; the maxFrames gate above bounds N). pcm.samples is
581	    // owned by the request and outlives preprocessAudio, covering the async
582	    // fbank launches and the cudaStreamSynchronize at the end of that function.
583	    if (!audioUtils::uploadHostPcmF32ToGpu(pcm.samples, mPcmF32Device, stream))
584	    {
585	        return false;
586	    }
587	
588	    // Non-owning view of the pre-allocated backing store at this clip's width.
589	    // A move-assignment into melSpec (the CPU fallback path) cannot free the
590	    // backing store, and every consumer of melSpec runs within this
591	    // preprocessAudio call — inside mMelSpecDevice's lifetime.
592	    melSpec = rt::Tensor(mMelSpecDevice.rawPointer(),
593	        {1, static_cast<int64_t>(mFbankResources.nMel), static_cast<int64_t>(numFrames)}, rt::DeviceType::kGPU,
594	        nvinfer1::DataType::kHALF);
595	    if (!audioUtils::fbankWhisper(mPcmF32Device, mFbankResources, melSpec, stream))
596	    {
597	        LOG_WARNING("Online GPU fbank failed; falling back to CPU MelExtractor for this clip.");
598	        return false;
599	    }
600	    return true;
601	}
