603	bool Qwen3OmniAudioRunner::preprocessAudio(std::vector<rt::audioUtils::AudioData> const& audioBuffers,
604	    std::vector<int64_t>& audioTokenLengths, cudaStream_t stream)
605	{
606	    if (audioBuffers.empty())
607	    {
608	        return true;
609	    }
610	
611	    if (!mAudioEngine || !mAudioContext)
612	    {
613	        LOG_ERROR("Audio encoder not loaded");
614	        return false;
615	    }
616	
617	    // Process each audio clip
618	    for (auto const& audio : audioBuffers)
619	    {
620	        // PCM-only contract; runner extracts mel internally via mFeMel.
621	        if (!audio.pcm)
622	        {
623	            LOG_ERROR(
624	                "AudioData.pcm is null; populate via load_audio_buffer_from_bytes "
625	                "(server) or requestFileParser (CLI).");
626	            return false;
627	        }
628	        rt::Tensor melSpec;
629	
630	        // Default path: online GPU fbank — PCM→log-mel entirely on device. On
631	        // any gate miss or kernel failure it returns false and we fall through
632	        // to the CPU MelExtractor below; both produce the identical
633	        // [1, nMel, T] FP16 contract, so the encoder is oblivious.
634	        bool const gpuFbankDone = tryOnlineGpuFbank(*audio.pcm, melSpec, stream);
635	
636	        // Fallback path (also the default when online fbank is unavailable):
637	        // CPU MelExtractor → FP16 GPU upload (the legacy CPU mel path).
638	        if (!gpuFbankDone)
639	        {
640	            rt::Tensor hostMel;
641	            if (!mFeMel.extract(*audio.pcm, hostMel))
642	            {
643	                LOG_ERROR("Mel extraction failed");
644	                return false;
645	            }
646	            // FP32 host mel -> FP16 GPU mel ([1, mel_bins, T] for whisper layout).
647	            if (!audioUtils::uploadHostMelFp32ToFp16Gpu(hostMel, melSpec, stream, "Qwen3OmniAudioRunner::mel"))
648	            {
649	                return false;
650	            }
651	        }
652	
653	        int64_t const timeSteps = melSpec.getShape()[2];
654	        LOG_DEBUG("Mel-spectrogram shape: [%ld, %ld, %ld]", melSpec.getShape()[0], melSpec.getShape()[1], timeSteps);
655	
656	        // Preprocess for audio encoder
657	        std::vector<int64_t> afterCNNLens;
658	        if (!audioUtils::preprocessAudioForEncoder(
659	                melSpec, mConfig.nWindow, mPaddedFeature, mPaddedMaskAfterCNN, afterCNNLens, stream))
660	        {
661	            LOG_ERROR("Failed to preprocess audio for encoder");
662	            return false;
663	        }
664	
665	        // Convert mask to indices
666	        if (!audioUtils::convertMaskToIndices(mPaddedMaskAfterCNN, mPaddedMaskIndices, stream))
667	        {
668	            LOG_ERROR("Failed to convert mask to indices");
669	            return false;
670	        }
671	
672	        LOG_DEBUG("Mask shape: [%ld, %ld], Indices shape: [%ld, %ld]", mPaddedMaskAfterCNN.getShape()[0],
673	            mPaddedMaskAfterCNN.getShape()[1], mPaddedMaskIndices.getShape()[0], mPaddedMaskIndices.getShape()[1]);
674	
675	        // Create attention mask with merged windows (matching PyTorch cu_seqlens logic)
676	        if (!audioUtils::createChunkwiseAttentionMask(
677	                afterCNNLens, mConfig.nWindow, mConfig.nWindowInfer, mAudioAttentionMask, stream))
678	        {
679	            LOG_ERROR("Failed to create attention mask");
680	            return false;
681	        }
682	
683	        LOG_DEBUG(
684	            "Created attention mask [%ld, %ld]", mAudioAttentionMask.getShape()[0], mAudioAttentionMask.getShape()[1]);
685	
686	        // Calculate total audio tokens
687	        int64_t const totalAudioTokens = mPaddedMaskIndices.getShape()[0];
688	
689	        if (mHasCuSeqlens || mHasKvLengths)
690	        {
691	            // NOTE: Currently, audio encoder always runs at batch size of 1.
692	            // Thus, we always set the seqlens size to 2 and set values to {0, totalAudioTokens}.
693	            int64_t const seqlensSize = 2;
694	            int64_t const seqlensSizeInBytes = seqlensSize * static_cast<int64_t>(sizeof(int32_t));
695	            if (mCuSeqlensHost.getMemoryCapacity() < seqlensSizeInBytes)
696	            {
697	                LOG_ERROR("cu_seqlens host capacity too small: need=%ld bytes, capacity=%ld bytes", seqlensSizeInBytes,
698	                    mCuSeqlensHost.getMemoryCapacity());
699	                return false;
700	            }
701	
702	            if (!mCuSeqlensHost.reshape({seqlensSize}))
703	            {
704	                LOG_ERROR("Failed to reshape host cu_seqlens buffer");
705	                return false;
706	            }
707	            int32_t* seqlensData = mCuSeqlensHost.dataPointer<int32_t>();
708	            seqlensData[0] = 0;
709	            seqlensData[1] = static_cast<int32_t>(totalAudioTokens);
710	
711	            if (mHasCuSeqlens)
712	            {
713	                if (!prepareSeqlensInput(mCuSeqlens, *mAudioContext, binding_names::kCuSeqlens, mCuSeqlensHost,
714	                        seqlensSize, seqlensSizeInBytes, stream, "cu_seqlens"))
715	                {
716	                    return false;
717	                }
718	            }
719	
720	            if (mHasKvLengths)
721	            {
722	                if (!prepareSeqlensInput(mKvLengths, *mAudioContext, binding_names::kKvLengths, mCuSeqlensHost,
723	                        seqlensSize, seqlensSizeInBytes, stream, "kv_lengths"))
724	                {
725	                    return false;
726	                }
727	            }
728	        }
729	
730	        // Reshape output buffer
731	        if (!mAudioEmbedding.reshape({totalAudioTokens, mConfig.audioFeatureDim}))
732	        {
733	            LOG_ERROR("Failed to reshape audio output");
734	            return false;
735	        }
736	
737	        LOG_DEBUG("Reshaped audio output to [%ld, %d]", totalAudioTokens, mConfig.audioFeatureDim);
738	
739	        // Set input shapes
740	        if (!mAudioContext->setInputShape(binding_names::kAudioPaddedFeatures, mPaddedFeature.getShape().getTRTDims()))
741	        {
742	            LOG_ERROR("Failed to set padded features input shape");
743	            return false;
744	        }
745	
746	        if (!mAudioContext->setInputShape(
747	                binding_names::kAudioPaddedMaskIndices, mPaddedMaskIndices.getShape().getTRTDims()))
748	        {
749	            LOG_ERROR("Failed to set padded mask indices input shape");
750	            return false;
751	        }
752	
753	        if (!mAudioContext->setInputShape(
754	                binding_names::kAudioAttentionMask, mAudioAttentionMask.getShape().getTRTDims()))
755	        {
756	            LOG_ERROR("Failed to set attention mask input shape");
757	            return false;
758	        }
759	
760	        // Set tensor addresses
761	        if (!mAudioContext->setTensorAddress(binding_names::kAudioPaddedFeatures, mPaddedFeature.rawPointer()))
762	        {
763	            LOG_ERROR("Failed to set padded features input address");
764	            return false;
765	        }
766	
767	        if (!mAudioContext->setTensorAddress(binding_names::kAudioPaddedMaskIndices, mPaddedMaskIndices.rawPointer()))
768	        {
769	            LOG_ERROR("Failed to set padded mask indices input address");
770	            return false;
771	        }
772	
773	        if (!mAudioContext->setTensorAddress(binding_names::kAudioAttentionMask, mAudioAttentionMask.rawPointer()))
774	        {
775	            LOG_ERROR("Failed to set attention mask input address");
776	            return false;
777	        }
778	
779	        if (!mAudioContext->setTensorAddress(binding_names::kAudioOutput, mAudioEmbedding.rawPointer()))
780	        {
781	            LOG_ERROR("Failed to set audio output address");
782	            return false;
783	        }
784	
785	        // Execute audio encoder
786	        LOG_DEBUG(
787	            "Executing audio encoder with shapes: "
788	            "input=[%ld,%ld,%ld], indices=[%ld,2], mask=[%ld,%ld], output=[%ld,%ld]",
789	            mPaddedFeature.getShape()[0], mPaddedFeature.getShape()[1], mPaddedFeature.getShape()[2],
790	            mPaddedMaskIndices.getShape()[0], mAudioAttentionMask.getShape()[0], mAudioAttentionMask.getShape()[1],
791	            mAudioEmbedding.getShape()[0], mAudioEmbedding.getShape()[1]);
792	
793	        {
794	            TIME_STAGE(metrics::StageNames::kAUDIO_ENCODER, stream);
795	
796	            if (!mAudioContext->enqueueV3(stream))
797	            {
798	                LOG_ERROR("Audio encoder inference failed");
799	                return false;
800	            }
801	        }
802	
803	        LOG_DEBUG("Audio encoder inference completed");
804	        audioTokenLengths.push_back(totalAudioTokens);
805	        mMultimodalMetrics.recordRun(0, 0, 1, totalAudioTokens);
806	    }
807	
808	    CUDA_CHECK(cudaStreamSynchronize(stream));
809	    return true;
810	}
