823	bool Qwen3OmniAudioRunner::preprocessSystemPrompt(std::string const& systemPrompt,
824	    [[maybe_unused]] tokenizer::Tokenizer const* tokenizer, rt::OptionalOutputTensor mropeCosSinOut,
