832	    if (!mropeCosSinOut.has_value())
833	    {
834	        LOG_ERROR("mropeCosSinOut is required for non-empty system prompts.");
835	        return false;
836	    }
837	
838	    // For audio-only MRope models (e.g. Qwen3-ASR), initialize sequential MRope cache
839	    // for system prompt since no vision runner will fill it.
840	    // Batch size is always 1 for system prompt KVCache generation.
