843	
844	bool Qwen3OmniAudioRunner::initializeSequentialMRopeCache(
845	    int64_t activeBatchSize, rt::Tensor& ropeRotaryCosSinDevice, cudaStream_t stream)
846	{
847	    if (mConfig.mropeTheta <= 0.0F)
848	    {
849	        // Not an MRope model, nothing to do.
850	        return true;
851	    }
852	
853	    auto const ropeShape = ropeRotaryCosSinDevice.getShape();
854	    int64_t const maxPositionEmbeddings = ropeShape[1];
855	    int64_t const rotaryDim = ropeShape[2];
856	
857	    // Allocate host position IDs: [activeBatchSize, 3, maxPositionEmbeddings]
858	    // For audio+text only, all 3 dimensions (T, H, W) use identical sequential positions [0, 1, 2, ...]
859	    int64_t const numElements = activeBatchSize * 3 * maxPositionEmbeddings;
860	    std::vector<int64_t> positionIdsHost(numElements);
861	
862	    for (int64_t b = 0; b < activeBatchSize; ++b)
863	    {
864	        int64_t batchOffset = b * 3 * maxPositionEmbeddings;
865	        for (int64_t dim = 0; dim < 3; ++dim)
866	        {
867	            for (int64_t pos = 0; pos < maxPositionEmbeddings; ++pos)
868	            {
869	                positionIdsHost[batchOffset + dim * maxPositionEmbeddings + pos] = pos;
870	            }
871	        }
872	    }
873	
874	    // Copy position IDs to device
875	    rt::Tensor positionIdsDevice({activeBatchSize, 3, maxPositionEmbeddings}, rt::DeviceType::kGPU,
876	        nvinfer1::DataType::kINT64, "sequentialMRopePositionIds");
877	    CUDA_CHECK(cudaMemcpyAsync(positionIdsDevice.rawPointer(), positionIdsHost.data(), numElements * sizeof(int64_t),
878	        cudaMemcpyHostToDevice, stream));
879	
880	    // Reshape the cos/sin cache and fill it
881	    check::check(
882	        ropeRotaryCosSinDevice.reshape({activeBatchSize, maxPositionEmbeddings, rotaryDim}), "Tensor reshape failed");
883	
884	    // All audio+text MRope models (Qwen3-ASR, Qwen3-Omni) use interleaved layout.
885	    bool constexpr interleaved = true;
886	    try
887	    {
888	        kernel::initializeMRopeCosSin(ropeRotaryCosSinDevice.dataPointer<float>(),
889	            positionIdsDevice.dataPointer<int64_t>(), mConfig.mropeTheta, rotaryDim, maxPositionEmbeddings,
890	            activeBatchSize, interleaved, mConfig.mropeSectionH, mConfig.mropeSectionW, stream);
891	    }
892	    catch (std::exception const& e)
893	    {
894	        LOG_ERROR("initializeSequentialMRopeCache: kernel launch failed: %s", e.what());
895	        return false;
896	    }
897	
898	    // Synchronize to ensure kernel completes before local positionIdsDevice is freed.
899	    CUDA_CHECK(cudaStreamSynchronize(stream));
900	    LOG_INFO("Initialized sequential MRope cos/sin cache for %ld batches, %ld positions", activeBatchSize,
901	        maxPositionEmbeddings);
902	
903	    return true;
904	}
905	
906	} // namespace rt
907	} // namespace trt_edgellm
