54	// Helper: Extract MLP weights from safetensors (eliminates code duplication)
55	bool extractMLPWeightsFromTensors(std::vector<rt::Tensor>& tensors, rt::Tensor& fc1Weight, rt::Tensor& fc1Bias,
56	    rt::Tensor& fc2Weight, rt::Tensor& fc2Bias, std::string const& projectionName)
57	{
58	    constexpr int32_t kExpectedTensorCount = 4;
59	    check::check(
60	        tensors.size() == kExpectedTensorCount, projectionName + ".safetensors should contain exactly 4 tensors");
61	
62	    bool foundFC1Weight = false, foundFC1Bias = false, foundFC2Weight = false, foundFC2Bias = false;
63	
64	    for (auto& tensor : tensors)
65	    {
66	        std::string const& name = tensor.getName();
67	        if (name.find("fc1.weight") != std::string::npos)
68	        {
69	            fc1Weight = std::move(tensor);
70	            foundFC1Weight = true;
71	        }
72	        else if (name.find("fc1.bias") != std::string::npos)
73	        {
74	            fc1Bias = std::move(tensor);
75	            foundFC1Bias = true;
76	        }
77	        else if (name.find("fc2.weight") != std::string::npos)
78	        {
79	            fc2Weight = std::move(tensor);
80	            foundFC2Weight = true;
81	        }
82	        else if (name.find("fc2.bias") != std::string::npos)
83	        {
84	            fc2Bias = std::move(tensor);
85	            foundFC2Bias = true;
86	        }
87	    }
88	
89	    if (!foundFC1Weight || !foundFC1Bias || !foundFC2Weight || !foundFC2Bias)
90	    {
91	        LOG_ERROR("Failed to find all required tensors in %s.safetensors", projectionName.c_str());
92	        return false;
93	    }
94	
95	    return true;
