98	// Shared chunk accumulator + emitter for streaming RVQ codes.
99	// Used by both runTalkerGenerationLoop (per-batch in TTS) and handleStreamingGeneration (bs=1 Omni)
100	// so chunk semantics (threshold-triggered non-final emit + single final flush) live in one place.
101	struct ChunkEmitter
102	{
103	    int32_t chunkFrames{0};
104	    std::function<void(std::vector<std::vector<int32_t>> const& chunk, bool isFinal)> onChunk;
105	    std::vector<std::vector<int32_t>> buffer;
106	
107	    bool active() const
108	    {
109	        return chunkFrames > 0 && static_cast<bool>(onChunk);
110	    }
111	
112	    // Append a frame; emit non-final chunk when buffer hits the threshold.
113	    void append(std::vector<int32_t> const& frame)
114	    {
115	        if (!active())
116	            return;
117	        buffer.push_back(frame);
118	        if (static_cast<int32_t>(buffer.size()) >= chunkFrames)
119	        {
120	            onChunk(buffer, /*isFinal=*/false);
121	            buffer.clear();
122	        }
123	    }
124	
125	    // Final flush — always invoked once per active emitter at end-of-stream, even if buffer empty
126	    // (callers rely on this as the end-of-stream signal).
127	    void flushFinal()
128	    {
129	        if (!active())
130	            return;
131	        onChunk(buffer, /*isFinal=*/true);
132	        buffer.clear();
133	    }
134	};
