137	Qwen3OmniTTSRuntime::Qwen3OmniTTSRuntime(std::string const& talkerEngineDir, std::string const& codePredictorEngineDir,
138	    std::string const& tokenizerDir, cudaStream_t stream)
139	    : mStream(stream)
140	{
141	    NVTX_SCOPED_RANGE(nvtx_range, "TalkerRunner::init", nvtx_colors::YELLOW);
142	    LOG_INFO("Initializing Qwen3-Omni Talker runner");
143	    LOG_INFO("  Talker: %s", talkerEngineDir.c_str());
144	    LOG_INFO("  CodePredictor: %s", codePredictorEngineDir.c_str());
145	
146	    // Load tokenizer
147	    std::filesystem::path const tokenizerPath = tokenizerDir.empty()
148	        ? std::filesystem::path(talkerEngineDir).parent_path()
149	        : std::filesystem::path(tokenizerDir);
150	    LOG_INFO("  Tokenizer: %s", tokenizerPath.string().c_str());
151	    mTokenizer = std::make_unique<tokenizer::Tokenizer>();
152	    bool const tokenizerLoaded = mTokenizer->loadFromHF(tokenizerPath);
153	    ELLM_CHECK(tokenizerLoaded, "Failed to load tokenizer from: " + tokenizerPath.string());
154	
155	    bool const configValid = validateAndFillConfig(talkerEngineDir);
156	    ELLM_CHECK(configValid, "Failed to validate and fill config");
157	
158	    bool const runnersInitialized = initializeEngineRunners(talkerEngineDir, codePredictorEngineDir);
159	    ELLM_CHECK(runnersInitialized, "Failed to initialize engine runners");
160	
161	    // Setup shared execution context memory for Talker and CodePredictor engines.
162	    // Both use kUSER_MANAGED allocation and require setContextMemory() before execution.
163	    {
164	        int64_t const talkerCtxSize = mTalkerExec->getRequiredContextMemorySize();
165	        int64_t const cpCtxSize = mCodePredictorExec ? mCodePredictorExec->getRequiredContextMemorySize() : 0;
166	        int64_t const sharedCtxSize = std::max(talkerCtxSize, cpCtxSize);
167	        LOG_INFO("Setup shared execution context memory: %zu bytes (talker: %zu, code_predictor: %zu)",
168	            static_cast<size_t>(sharedCtxSize), static_cast<size_t>(talkerCtxSize), static_cast<size_t>(cpCtxSize));
169	        mSharedExecContextMemory = rt::Tensor({sharedCtxSize}, rt::DeviceType::kGPU, nvinfer1::DataType::kUINT8,
170	            "Qwen3OmniTTSRuntime::mSharedExecContextMemory");
171	        bool const talkerCtxSet = mTalkerExec->setContextMemory(mSharedExecContextMemory);
172	        ELLM_CHECK(talkerCtxSet, "Failed to set context memory for Talker LLM engine");
173	        ELLM_CHECK(!mCodePredictorExec || mCodePredictorExec->setContextMemory(mSharedExecContextMemory),
174	            "Failed to set context memory for CodePredictor engine");
175	    }
176	
177	    // Determine max batch size from engine configs (use the minimum of Talker and CodePredictor)
178	    mMaxBatchSize = std::min(mTalkerLLMConfig.maxSupportedBatchSize, mCodePredictorConfig.maxSupportedBatchSize);
179	    check::check(mMaxBatchSize >= 1, "maxBatchSize must be >= 1");
180	    LOG_INFO("Max batch size: %d (Talker=%d, CodePredictor=%d)", mMaxBatchSize, mTalkerLLMConfig.maxSupportedBatchSize,
181	        mCodePredictorConfig.maxSupportedBatchSize);
182	
183	    bool const codePredictorWeightsLoaded = loadCodePredictorWeights(codePredictorEngineDir);
184	    ELLM_CHECK(codePredictorWeightsLoaded, "Failed to load CodePredictor weights");
185	
186	#ifdef CUTE_DSL_GEMM_ENABLED
187	    bool const cuteDslLoaded = CuteDslGemmRunner::loadKernelModule();
188	    ELLM_CHECK(cuteDslLoaded, "Failed to load CuTe DSL GEMM kernel module");
189	#endif
190	
191	    bool const bufferAllocated = allocateBuffer();
192	    ELLM_CHECK(bufferAllocated, "Failed to allocate buffers");
193	
194	    bool const talkerWeightsLoaded = loadTalkerWeights(talkerEngineDir, stream);
195	    ELLM_CHECK(talkerWeightsLoaded, "Failed to load Talker weights");
196	
197	    // Load text embedding table (thinker vocab).
198	    // Used for standalone TTS and for projecting TTS special tokens.
199	    // TTS: text_embedding.safetensors in talkerEngineDir (copied by builder).
200	    // Omni: use thinker's embedding.safetensors from tokenizerPath instead.
201	    {
202	        std::filesystem::path const textEmbedPath = mIsOmni
203	            ? tokenizerPath / "embedding.safetensors"
204	            : std::filesystem::path(talkerEngineDir) / "text_embedding.safetensors";
205	        LOG_INFO("Loading text embedding from: %s", textEmbedPath.string().c_str());
206	        std::vector<rt::Tensor> textEmbedTensors;
207	        bool const textEmbedLoaded = safetensors::loadSafetensors(textEmbedPath, textEmbedTensors, stream);
208	        ELLM_CHECK(textEmbedLoaded, "Failed to load text embedding from: " + textEmbedPath.string());
209	        check::check(!textEmbedTensors.empty(), "text embedding file is empty");
210	        check::check(textEmbedTensors[0].getShape().getNumDims() == 2,
211	            "text embedding tensor should be 2D [vocabSize, hiddenSize]");
212	        mTextEmbeddingTable = std::move(textEmbedTensors[0]);
213	        LOG_INFO("Text embedding table loaded: [%lld, %lld]", mTextEmbeddingTable.getShape()[0],
214	            mTextEmbeddingTable.getShape()[1]);
215	    }
216	
217	    // Note: mTalkerEmbeddingTable is loaded by loadTalkerWeights() above.
218	
219	    // Load CodePredictor embedding tables from codec_embeddings.safetensors
220	    // mNumRvqLayers is already set from config.json num_code_groups in validateAndFillConfig()
221	    {
222	        std::filesystem::path const embedPath
223	            = std::filesystem::path(codePredictorEngineDir) / "codec_embeddings.safetensors";
224	        std::vector<rt::Tensor> allEmbedTensors;
225	        bool const codecEmbedLoaded = safetensors::loadSafetensors(embedPath, allEmbedTensors, stream);
226	        ELLM_CHECK(codecEmbedLoaded, "Failed to load codec_embeddings.safetensors from: " + embedPath.string());
227	        check::check(static_cast<int32_t>(allEmbedTensors.size()) == mNumRvqLayers,
228	            "codec_embeddings.safetensors has " + std::to_string(allEmbedTensors.size()) + " tensors, expected "
229	                + std::to_string(mNumRvqLayers) + " (num_code_groups - 1)");
230	        mCodePredictorEmbeddingTables.resize(mNumRvqLayers);
231	        for (int32_t i = 0; i < mNumRvqLayers; ++i)
232	        {
233	            std::string const key = "embedding_" + std::to_string(i);
234	            auto it = std::find_if(allEmbedTensors.begin(), allEmbedTensors.end(),
235	                [&key](rt::Tensor const& t) { return t.getName() == key; });
236	            check::check(it != allEmbedTensors.end(), "Missing key '" + key + "' in codec_embeddings.safetensors");
237	            check::check(it->getShape().getNumDims() == 2, key + " should be 2D [codebookSize, hiddenSize]");
238	            mCodePredictorEmbeddingTables[i] = std::move(*it);
239	        }
240	    }
241	    LOG_INFO("Loaded %d CodePredictor embedding tables (from config num_code_groups=%d)", mNumRvqLayers,
242	        mTalkerConfig.numCodeGroups);
243	
244	    initializeTTSEmbeddings(stream);
245	
246	    CUDA_CHECK(cudaEventCreateWithFlags(&mTtfaStart, cudaEventDefault));
247	    CUDA_CHECK(cudaEventCreateWithFlags(&mTtfaEnd, cudaEventDefault));
248	
249	    LOG_INFO("Qwen3-Omni TTS runtime initialized successfully");
250	}
