267	bool Qwen3OmniTTSRuntime::initializeEngineRunners(
268	    std::string const& talkerEngineDir, std::string const& codePredictorEngineDir)
269	{
270	    // Load Talker LLM engine via EngineExecutor (migrated from LLMEngineRunner)
271	    std::filesystem::path talkerEnginePath = std::filesystem::path(talkerEngineDir) / "llm.engine";
272	    std::filesystem::path talkerConfigPath = std::filesystem::path(talkerEngineDir) / "config.json";
273	
274	    LOG_INFO("Loading Talker LLM engine from: %s", talkerEnginePath.string().c_str());
275	
276	    try
277	    {
278	        mTalkerLLMConfig = rt::parseEngineConfig(talkerConfigPath);
279	        mTalkerExec = rt::EngineExecutor::createForLLM(talkerEnginePath, mTalkerLLMConfig);
280	        std::unordered_map<std::string, std::string> emptyLoraMap;
281	        mTalkerSharedRes = rt::SharedResources::createForLLM(mTalkerLLMConfig, emptyLoraMap, mStream);
282	        mTalkerPipelineIO = std::make_unique<rt::PipelineIO>(rt::PipelineIO::createForLLM(mTalkerLLMConfig, mStream));
283	        mTalkerStepPreparer = std::make_unique<rt::StepPreparer>(mTalkerLLMConfig);
284	        rt::buildTensorMap(
285	            mTalkerTensorMap, *mTalkerPipelineIO, *mTalkerSharedRes, mTalkerLLMConfig, /*kvCacheIndex=*/0);
286	
287	        LOG_INFO("Talker LLM engine loaded: vocabSize=%d, hiddenSize=%d", mTalkerLLMConfig.vocabSize,
288	            mTalkerLLMConfig.hiddenSize);
289	        auto talkerKVType = mTalkerLLMConfig.kvCacheDtype;
290	        LOG_INFO("Talker KV cache dtype: %s",
291	            talkerKVType == nvinfer1::DataType::kHALF ? "FP16"
292	                                                      : (talkerKVType == nvinfer1::DataType::kFP8 ? "FP8" : "UNKNOWN"));
293	    }
294	    catch (std::exception const& e)
295	    {
296	        LOG_ERROR("Failed to load Talker LLM engine: %s", e.what());
297	        return false;
298	    }
299	
300	    // Load CodePredictor engine via EngineExecutor (migrated from LLMEngineRunner)
301	    std::filesystem::path codePredictorEnginePath = std::filesystem::path(codePredictorEngineDir) / "llm.engine";
302	    std::filesystem::path codePredictorConfigPath = std::filesystem::path(codePredictorEngineDir) / "config.json";
303	
304	    LOG_INFO("Loading CodePredictor engine from: %s", codePredictorEnginePath.string().c_str());
305	
306	    try
307	    {
308	        mCodePredictorConfig = rt::parseEngineConfig(codePredictorConfigPath);
309	        mCodePredictorExec = rt::EngineExecutor::createForLLM(codePredictorEnginePath, mCodePredictorConfig);
310	        std::unordered_map<std::string, std::string> emptyLoraMap;
311	        mCodePredictorSharedRes = rt::SharedResources::createForLLM(mCodePredictorConfig, emptyLoraMap, mStream);
312	        mCodePredictorPipelineIO
313	            = std::make_unique<rt::PipelineIO>(rt::PipelineIO::createForLLM(mCodePredictorConfig, mStream));
314	        mCodePredictorStepPreparer = std::make_unique<rt::StepPreparer>(mCodePredictorConfig);
315	        rt::buildTensorMap(mCodePredictorTensorMap, *mCodePredictorPipelineIO, *mCodePredictorSharedRes,
316	            mCodePredictorConfig, /*kvCacheIndex=*/0);
317	
318	        // CodePredictor ONNX outputs FP32 logits directly (lm_head applied in-engine via the
319	        // dynamic lm_head_weight input). We rebind that input per RVQ head before each call.
320	
321	        // Read CodePredictor dimensions from loaded config (vocab_size==hidden_size since
322	        // engine output is last_hidden; real codebook_size is inferred from lm_head shape later)
323	        mTalkerConfig.codePredictorHiddenSize = mCodePredictorConfig.hiddenSize;
324	
325	        LOG_INFO("CodePredictor engine loaded: vocabSize=%d, hiddenSize=%d, numLayers=%d",
326	            mCodePredictorConfig.vocabSize, mCodePredictorConfig.hiddenSize, mCodePredictorConfig.numDecoderLayers);
327	        auto cpKVType = mCodePredictorConfig.kvCacheDtype;
328	        LOG_INFO("CodePredictor KV cache dtype: %s",
329	            cpKVType == nvinfer1::DataType::kHALF ? "FP16"
330	                                                  : (cpKVType == nvinfer1::DataType::kFP8 ? "FP8" : "UNKNOWN"));
331	    }
332	    catch (std::exception const& e)
333	    {
334	        LOG_ERROR("Failed to load CodePredictor engine: %s", e.what());
335	        return false;
336	    }
337	
338	    return true;
339	}
