341	bool Qwen3OmniTTSRuntime::validateAndFillConfig(std::string const& talkerEngineDir)
342	{
343	    // Load config.json from talker directory
344	    std::filesystem::path configPath = std::filesystem::path(talkerEngineDir) / "config.json";
345	    LOG_INFO("Loading Talker config from: %s", configPath.string().c_str());
346	
347	    std::ifstream configFileStream(configPath);
348	    if (!configFileStream.is_open())
349	    {
350	        LOG_ERROR("Failed to open config file: %s", configPath.string().c_str());
351	        return false;
352	    }
353	
354	    Json configJson;
355	    try
356	    {
357	        configJson = Json::parse(configFileStream);
358	        configFileStream.close();
359	    }
360	    catch (Json::parse_error const& e)
361	    {
362	        LOG_ERROR("Failed to parse config: %s", e.what());
363	        return false;
364	    }
365	
366	    // Model dimensions
367	    mTalkerConfig.thinkerHiddenSize = configJson.value("thinker_hidden_size", 2048);
368	    mTalkerConfig.talkerHiddenSize = configJson["hidden_size"].get<int32_t>();
369	    mTalkerConfig.talkerVocabSize = configJson["vocab_size"].get<int32_t>();
370	
371	    // CodePredictor RVQ configuration: Omni uses 16 code groups, TTS uses 32
372	    mTalkerConfig.numCodeGroups = configJson["num_code_groups"].get<int32_t>();
373	    check::check(mTalkerConfig.numCodeGroups >= 2,
374	        "num_code_groups must be >= 2, got: " + std::to_string(mTalkerConfig.numCodeGroups));
375	    mNumRvqLayers = mTalkerConfig.numCodeGroups - 1;
376	    mNumCodesPerFrame = mTalkerConfig.numCodeGroups;
377	    LOG_INFO("Config num_code_groups=%d -> RVQ layers=%d, codes per frame=%d", mTalkerConfig.numCodeGroups,
378	        mNumRvqLayers, mNumCodesPerFrame);
379	
380	    // Runtime parameters
381	    mTalkerConfig.maxSeqLen = configJson.value("max_position_embeddings", 8192);
382	
383	    // Validate dimensions with reasonable limits
384	    constexpr int32_t kMaxReasonableVocabSize = 200000;
385	    constexpr int32_t kMaxReasonableHiddenSize = 16384;
386	    constexpr int32_t kMaxReasonableSeqLen = 131072;
387	
388	    check::check(mTalkerConfig.talkerVocabSize > 0 && mTalkerConfig.talkerVocabSize < kMaxReasonableVocabSize,
389	        "Invalid talker vocab size: " + std::to_string(mTalkerConfig.talkerVocabSize));
390	    check::check(mTalkerConfig.thinkerHiddenSize > 0 && mTalkerConfig.thinkerHiddenSize < kMaxReasonableHiddenSize,
391	        "Invalid thinker hidden size: " + std::to_string(mTalkerConfig.thinkerHiddenSize));
392	    check::check(mTalkerConfig.talkerHiddenSize > 0 && mTalkerConfig.talkerHiddenSize < kMaxReasonableHiddenSize,
393	        "Invalid talker hidden size: " + std::to_string(mTalkerConfig.talkerHiddenSize));
394	    check::check(mTalkerConfig.maxSeqLen > 0 && mTalkerConfig.maxSeqLen < kMaxReasonableSeqLen,
395	        "Invalid max sequence length: " + std::to_string(mTalkerConfig.maxSeqLen));
396	
397	    // TTS special tokens (from thinker vocab)
398	    mTalkerConfig.ttsPadTokenId = configJson.value("tts_pad_token_id", 151671);
399	    mTalkerConfig.ttsBosTokenId = configJson.value("tts_bos_token_id", 151672);
400	    mTalkerConfig.ttsEosTokenId = configJson.value("tts_eos_token_id", 151673);
401	
402	    // Codec special tokens (from talker vocab)
403	    mTalkerConfig.codecNothinkId = configJson["codec_nothink_id"].get<int32_t>();
404	    mTalkerConfig.codecThinkBosId = configJson["codec_think_bos_id"].get<int32_t>();
405	    mTalkerConfig.codecThinkEosId = configJson["codec_think_eos_id"].get<int32_t>();
406	    mTalkerConfig.codecPadId = configJson["codec_pad_id"].get<int32_t>();
407	    mTalkerConfig.codecBosId = configJson["codec_bos_id"].get<int32_t>();
408	    // Support both codec_eos_token_id (original) and codec_eos_id (legacy) for backward compatibility
409	    if (configJson.contains("codec_eos_token_id"))
410	    {
411	        mTalkerConfig.codecEosId = configJson["codec_eos_token_id"].get<int32_t>();
412	    }
413	    else
414	    {
415	        mTalkerConfig.codecEosId = configJson["codec_eos_id"].get<int32_t>();
416	    }
417	
418	    // Speaker ID configuration
419	    mTalkerConfig.defaultSpeakerId = configJson.value("default_speaker_id", 2301);
420	
421	    // Thinker→Talker streaming uses this to route engine hidden_states from
422	    // the Thinker portal into the Talker prefill. Standalone Qwen3-TTS Talker
423	    // configs (no Thinker) legitimately omit the field; the streaming code
424	    // path validates the value before use. Sentinel -1 means "unconfigured".
425	    mTalkerConfig.acceptHiddenLayer = configJson.value("accept_hidden_layer", -1);
426	
427	    // Load speaker ID mapping if available
428	    if (configJson.contains("speaker_id") && configJson["speaker_id"].is_object())
429	    {
430	        for (auto const& [speaker_name, speaker_id] : configJson["speaker_id"].items())
431	        {
432	            mSpeakerIdMap[speaker_name] = speaker_id.get<int32_t>();
433	        }
434	        LOG_INFO("Loaded %zu speaker IDs from config", mSpeakerIdMap.size());
435	
436	        // Log available speakers
437	        if (!mSpeakerIdMap.empty())
438	        {
439	            std::string speakerList;
440	            for (auto const& [name, id] : mSpeakerIdMap)
441	            {
442	                if (!speakerList.empty())
443	                {
444	                    speakerList += ", ";
445	                }
446	                speakerList += name + ":" + std::to_string(id);
447	            }
448	            LOG_DEBUG("Available speakers: %s", speakerList.c_str());
449	        }
450	    }
451	
452	    LOG_INFO("Talker config: vocabSize=%d, hiddenSize=%d, thinkerHiddenSize=%d, defaultSpeaker=%d",
453	        mTalkerConfig.talkerVocabSize, mTalkerConfig.talkerHiddenSize, mTalkerConfig.thinkerHiddenSize,
454	        mTalkerConfig.defaultSpeakerId);
455	    LOG_DEBUG("TTS tokens: pad=%d, bos=%d, eos=%d", mTalkerConfig.ttsPadTokenId, mTalkerConfig.ttsBosTokenId,
456	        mTalkerConfig.ttsEosTokenId);
457	    LOG_DEBUG("Codec tokens: skipThink=%d, thinkBos=%d, thinkEos=%d, pad=%d, bos=%d, eos=%d",
458	        mTalkerConfig.codecNothinkId, mTalkerConfig.codecThinkBosId, mTalkerConfig.codecThinkEosId,
459	        mTalkerConfig.codecPadId, mTalkerConfig.codecBosId, mTalkerConfig.codecEosId);
460	
461	    return true;
462	}
