464	bool Qwen3OmniTTSRuntime::loadCodePredictorWeights(std::string const& codePredictorEngineDir)
465	{
466	    LOG_INFO("Loading %d CodePredictor lm_head weights", mNumRvqLayers);
467	    mCodePredictorLmHeadWeights.resize(mNumRvqLayers);
468	    {
469	        std::filesystem::path const lmHeadPath = std::filesystem::path(codePredictorEngineDir) / "lm_heads.safetensors";
470	        std::vector<rt::Tensor> allLmHeadTensors;
471	        if (!safetensors::loadSafetensors(lmHeadPath, allLmHeadTensors, mStream))
472	        {
473	            LOG_ERROR("Failed to load lm_heads.safetensors from: %s", lmHeadPath.string().c_str());
474	            return false;
475	        }
476	        if (static_cast<int32_t>(allLmHeadTensors.size()) != mNumRvqLayers)
477	        {
478	            LOG_ERROR("lm_heads.safetensors has %zu entries, expected %d (matching codec_embeddings count)",
479	                allLmHeadTensors.size(), mNumRvqLayers);
480	            return false;
481	        }
482	        for (int32_t i = 0; i < mNumRvqLayers; ++i)
483	        {
484	            std::string const weightKey = "lm_head_" + std::to_string(i) + ".weight";
485	            auto it = std::find_if(allLmHeadTensors.begin(), allLmHeadTensors.end(),
486	                [&weightKey](rt::Tensor const& t) { return t.getName() == weightKey; });
487	            if (it == allLmHeadTensors.end())
488	            {
489	                LOG_ERROR("Missing key '%s' in lm_heads.safetensors", weightKey.c_str());
490	                return false;
491	            }
492	            if (it->getShape().getNumDims() != 2)
493	            {
494	                LOG_ERROR("%s should be 2D [vocabSize, hiddenSize]", weightKey.c_str());
495	                return false;
496	            }
497	            LOG_DEBUG("Loaded %s [%d, %d]", weightKey.c_str(), it->getShape()[0], it->getShape()[1]);
498	            mCodePredictorLmHeadWeights[i] = std::move(*it);
499	        }
500	    }
501	
502	    mTalkerConfig.codebookSize = static_cast<int32_t>(mCodePredictorLmHeadWeights[0].getShape()[0]);
503	    LOG_INFO("Loaded %d CodePredictor lm_head weights, codebookSize=%d", mNumRvqLayers, mTalkerConfig.codebookSize);
504	
505	    // Load small_to_mtp_projection: projects Talker hidden (2048) → CodePredictor input (1024)
506	    {
507	        std::filesystem::path const projPath
508	            = std::filesystem::path(codePredictorEngineDir) / "small_to_mtp_projection.safetensors";
509	        if (std::filesystem::exists(projPath))
510	        {
511	            std::vector<rt::Tensor> projTensors;
512	            if (!safetensors::loadSafetensors(projPath, projTensors, mStream))
513	            {
514	                LOG_ERROR("Failed to load small_to_mtp_projection from: %s", projPath.string().c_str());
515	                return false;
516	            }
517	            bool foundWeight = false, foundBias = false;
518	            for (auto& t : projTensors)
519	            {
520	                if (t.getName() == "weight")
521	                {
522	                    mSmallToMtpWeight = std::move(t);
523	                    foundWeight = true;
524	                }
525	                else if (t.getName() == "bias")
526	                {
527	                    mSmallToMtpBias = std::move(t);
528	                    foundBias = true;
529	                }
530	            }
531	            if (!foundWeight || !foundBias)
532	            {
533	                LOG_ERROR("Missing 'weight' or 'bias' in small_to_mtp_projection.safetensors");
534	                return false;
535	            }
536	            mUseSmallToMtpProjection = true;
537	            LOG_INFO("Loaded small_to_mtp_projection: weight=%ldx%ld, bias=%ld", mSmallToMtpWeight.getShape()[0],
538	                mSmallToMtpWeight.getShape()[1], mSmallToMtpBias.getShape()[0]);
539	        }
540	        else if (mTalkerConfig.talkerHiddenSize == mTalkerConfig.codePredictorHiddenSize)
541	        {
542	            mUseSmallToMtpProjection = false;
543	            LOG_INFO("No small_to_mtp_projection needed (talkerHiddenSize == codePredictorHiddenSize = %d)",
544	                mTalkerConfig.talkerHiddenSize);
545	        }
546	        else
547	        {
548	            LOG_ERROR(
549	                "small_to_mtp_projection.safetensors required when talkerHiddenSize (%d) != "
550	                "codePredictorHiddenSize (%d)",
551	                mTalkerConfig.talkerHiddenSize, mTalkerConfig.codePredictorHiddenSize);
552	            return false;
553	        }
554	    }
555	
556	    // CodePredictor embedding tables are already loaded in the constructor (with auto-detection
557	    // of mNumRvqLayers from codec_embeddings.safetensors).
558	
559	    return true;
560	}
