562	bool Qwen3OmniTTSRuntime::allocateBuffer()
563	{
564	    LOG_INFO("Allocating Qwen3-Omni TTS Runtime inference workspace buffers (maxBatchSize=%d)...", mMaxBatchSize);
565	
566	    int64_t const maxSeqLen = mTalkerConfig.maxSeqLen;
567	    int64_t const thinkerHiddenSize = mTalkerConfig.thinkerHiddenSize;
568	    int64_t const talkerHiddenSize = mTalkerConfig.talkerHiddenSize;
569	    int64_t const maxBS = mMaxBatchSize;
570	
571	    try
572	    {
573	        // Per-batch prefill workspace (reused sequentially per batch in buildTalkerPrefillFromSegments)
574	        mThinkerEmbedBuffer = rt::Tensor(
575	            {maxSeqLen, thinkerHiddenSize}, rt::DeviceType::kGPU, nvinfer1::DataType::kHALF, "mThinkerEmbedBuffer");
576	        mGpuTokenIdsBuffer
577	            = rt::Tensor({1, maxSeqLen}, rt::DeviceType::kGPU, nvinfer1::DataType::kINT32, "mGpuTokenIdsBuffer");
578	        mMLPWorkspace = rt::Tensor(
579	            {maxSeqLen, thinkerHiddenSize}, rt::DeviceType::kGPU, nvinfer1::DataType::kHALF, "mMLPWorkspace");
580	        mProjectedBuffer = rt::Tensor(
581	            {maxSeqLen, talkerHiddenSize}, rt::DeviceType::kGPU, nvinfer1::DataType::kHALF, "mProjectedBuffer");
582	        // Talker input embeds: [maxBS, maxSeqLen, H] for batched prefill
583	        mTalkerInputEmbeds = rt::Tensor({maxBS * maxSeqLen, talkerHiddenSize}, rt::DeviceType::kGPU,
584	            nvinfer1::DataType::kHALF, "mTalkerInputEmbeds");
585	
586	        // Talker LLM workspace — batched
587	        mTalkerLogits = rt::Tensor(
588	            {maxBS, mTalkerConfig.talkerVocabSize}, rt::DeviceType::kGPU, nvinfer1::DataType::kFLOAT, "mTalkerLogits");
589	        mTalkerSelectedIndices
590	            = rt::Tensor({maxBS, 1}, rt::DeviceType::kGPU, nvinfer1::DataType::kINT32, "mTalkerSelectedIndices");
591	        mHostSelectedTokenIds
592	            = rt::Tensor({maxBS}, rt::DeviceType::kCPU, nvinfer1::DataType::kINT32, "mHostSelectedTokenIds");
593	
594	        // CodePredictor workspace — sized to maxBS so any batch in [1, maxBS] just reshapes per-call.
595	        // Same pattern as Talker: framework primitives (EngineExecutor / StepPreparer) are
596	        // batch-size-agnostic; the per-call reshape({activeBatchSize, ...}) makes them work.
597	        mCodePredictorLogits = rt::Tensor({maxBS, mTalkerConfig.codebookSize}, rt::DeviceType::kGPU,
598	            nvinfer1::DataType::kFLOAT, "mCodePredictorLogits");
599	
600	        mCodePredictorLogitsPerHead.resize(mNumRvqLayers);
601	        for (int32_t i = 0; i < mNumRvqLayers; ++i)
602	        {
603	            mCodePredictorLogitsPerHead[i] = rt::Tensor({maxBS, mTalkerConfig.codebookSize}, rt::DeviceType::kGPU,
604	                nvinfer1::DataType::kFLOAT, "mCodePredictorLogitsPerHead_" + std::to_string(i));
605	        }
606	
607	        mCodePredictorPrefillInput = rt::Tensor({maxBS, 2, mTalkerConfig.codePredictorHiddenSize}, rt::DeviceType::kGPU,
608	            nvinfer1::DataType::kHALF, "mCodePredictorPrefillInput");
609	        mCodePredictorCodecIds
610	            = rt::Tensor({maxBS, 1}, rt::DeviceType::kGPU, nvinfer1::DataType::kINT32, "mCodePredictorCodecIds");
611	        mCodePredictorCodecEmbed = rt::Tensor({maxBS, 1, mTalkerConfig.codePredictorHiddenSize}, rt::DeviceType::kGPU,
612	            nvinfer1::DataType::kHALF, "mCodePredictorCodecEmbed");
613	        mRawCodecEmbed = rt::Tensor({maxBS, 1, mTalkerConfig.talkerHiddenSize}, rt::DeviceType::kGPU,
614	            nvinfer1::DataType::kHALF, "mRawCodecEmbed");
615	        mSmallToMtpProjectedHidden = rt::Tensor({maxBS, mTalkerConfig.codePredictorHiddenSize}, rt::DeviceType::kGPU,
616	            nvinfer1::DataType::kHALF, "mSmallToMtpProjectedHidden");
617	        mCodePredictorSelectedIndices
618	            = rt::Tensor({maxBS, 1}, rt::DeviceType::kGPU, nvinfer1::DataType::kINT32, "mCodePredictorSelectedIndices");
619	        mHostSelectedCodeIds
620	            = rt::Tensor({maxBS}, rt::DeviceType::kCPU, nvinfer1::DataType::kINT32, "mHostSelectedCodeIds");
621	        // Pinned (cudaMallocHost) buffer that accumulates the deferred CP gen samples
622	        // across all (mNumRvqLayers - 1) steps for up to maxBS active batches, so we
623	        // can do a single cudaStreamSynchronize per frame instead of one per step.
624	        // Layout: [step_idx, batch_idx] — step k writes to row k.
625	        mHostGenCodeBuf = rt::Tensor({static_cast<int64_t>(mNumRvqLayers - 1), maxBS}, rt::DeviceType::kCPU,
626	            nvinfer1::DataType::kINT32, "mHostGenCodeBuf");
627	        mHostCodePredictorContextLength
628	            = rt::Tensor({maxBS}, rt::DeviceType::kCPU, nvinfer1::DataType::kINT32, "mHostCodePredictorContextLength");
629	
630	        // Residual + decode buffers — batched for Talker engine execution
631	        mResidualEmbedBuffer = rt::Tensor({maxBS, 1, mTalkerConfig.talkerHiddenSize}, rt::DeviceType::kGPU,
632	            nvinfer1::DataType::kHALF, "mResidualEmbedBuffer");
633	        mTalkerDecodingIds
634	            = rt::Tensor({maxBS, 1}, rt::DeviceType::kGPU, nvinfer1::DataType::kINT32, "mTalkerDecodingIds");
635	        mTalkerDecodingEmbed = rt::Tensor({maxBS, 1, mTalkerConfig.talkerHiddenSize}, rt::DeviceType::kGPU,
636	            nvinfer1::DataType::kHALF, "mTalkerDecodingEmbed");
637	
638	        // KVCache reset — batched
639	        mHostReuseKVCacheLengths
640	            = rt::Tensor({maxBS}, rt::DeviceType::kCPU, nvinfer1::DataType::kINT32, "mHostReuseKVCacheLengths");
641	
642	        // Sampling workspace — allocated at maxBS for batched topKtopP
643	        int32_t const defaultTopK{0};
644	        float const defaultTopP{0.9F};
645	        trt_edgellm::SamplingParams samplingParams(
646	            static_cast<int32_t>(maxBS), mTalkerConfig.talkerVocabSize, 1.0f, defaultTopK, defaultTopP);
647	        int64_t const samplingWorkspaceSize = trt_edgellm::getTopKtopPSamplingWorkspaceSize(
648	            static_cast<int32_t>(maxBS), mTalkerConfig.talkerVocabSize, samplingParams);
649	        mSamplingWorkspace = rt::Tensor(
650	            {samplingWorkspaceSize}, rt::DeviceType::kGPU, nvinfer1::DataType::kINT8, "mSamplingWorkspace");
651	        // Per-batch seen codec tokens for repetition penalty
652	        mSeenCodecTokensBuf = rt::Tensor({maxBS, mTalkerLLMConfig.maxKVCacheCapacity}, rt::DeviceType::kGPU,
653	            nvinfer1::DataType::kINT32, "mSeenCodecTokensBuf");
654	
655	        // Generation loop workspace — Talker batched, CodePredictor batch=1
656	        mTalkerHiddenStatesBuffer = rt::Tensor({maxBS, maxSeqLen, talkerHiddenSize}, rt::DeviceType::kGPU,
657	            nvinfer1::DataType::kHALF, "mTalkerHiddenStatesBuffer");
658	        mCodePredictorHiddenStatesBuffer = rt::Tensor({maxBS, mNumCodesPerFrame, mTalkerConfig.codePredictorHiddenSize},
659	            rt::DeviceType::kGPU, nvinfer1::DataType::kHALF, "mCodePredictorHiddenStatesBuffer");
660	        mTalkerLastHidden = rt::Tensor(
661	            {maxBS, talkerHiddenSize}, rt::DeviceType::kGPU, nvinfer1::DataType::kHALF, "mTalkerLastHidden");
662	        mCodecHiddensBuffer = rt::Tensor({maxBS, mNumCodesPerFrame, mTalkerConfig.talkerHiddenSize},
663	            rt::DeviceType::kGPU, nvinfer1::DataType::kHALF, "mCodecHiddensBuffer");
664	
665	        // Trailing text hidden buffer: [maxBS * (maxSeqLen+1), H] — per-batch regions for Omni multi-batch
666	        mStreamingTrailingHidden = rt::Tensor({maxBS * (maxSeqLen + 1), talkerHiddenSize}, rt::DeviceType::kGPU,
667	            nvinfer1::DataType::kHALF, "mStreamingTrailingHidden");
668	
669	        // Gather/scatter index buffer for multimodal token projection
670	        mGatherIndicesBuffer
671	            = rt::Tensor({maxSeqLen}, rt::DeviceType::kGPU, nvinfer1::DataType::kINT32, "mGatherIndicesBuffer");
672	
673	        // Streaming: single-token workspace for appendTrailingToken
674	        mStreamingTokenId = rt::Tensor({1, 1}, rt::DeviceType::kGPU, nvinfer1::DataType::kINT32, "mStreamingTokenId");
675	        mStreamingTokenEmbed = rt::Tensor(
676	            {1, thinkerHiddenSize}, rt::DeviceType::kGPU, nvinfer1::DataType::kHALF, "mStreamingTokenEmbed");
677	        mStreamingProjOut
678	            = rt::Tensor({1, talkerHiddenSize}, rt::DeviceType::kGPU, nvinfer1::DataType::kHALF, "mStreamingProjOut");
679	        mStreamingMlpWork
680	            = rt::Tensor({1, thinkerHiddenSize}, rt::DeviceType::kGPU, nvinfer1::DataType::kHALF, "mStreamingMlpWork");
681	
682	        LOG_INFO("Talker buffers allocated (maxBS=%d, maxSeqLen=%ld, talkerH=%ld, cpH=%d)", mMaxBatchSize, maxSeqLen,
683	            talkerHiddenSize, mTalkerConfig.codePredictorHiddenSize);
684	        return true;
685	    }
686	    catch (std::exception const& e)
687	    {
688	        LOG_ERROR("Failed to allocate Talker buffers: %s", e.what());
689	        return false;
690	    }
691	}
