693	bool Qwen3OmniTTSRuntime::loadTalkerWeights(std::string const& weightsDir, cudaStream_t stream)
694	{
695	    NVTX_SCOPED_RANGE(nvtx_range, "TalkerRunner::loadTalkerWeights", nvtx_colors::YELLOW);
696	
697	    // Load text_projection weights
698	    std::filesystem::path const textProjPath = std::filesystem::path(weightsDir) / "text_projection.safetensors";
699	    std::vector<rt::Tensor> textTensors;
700	    if (!safetensors::loadSafetensors(textProjPath, textTensors, stream))
701	    {
702	        LOG_ERROR("Failed to load text_projection from: %s", textProjPath.string().c_str());
703	        return false;
704	    }
705	    if (!extractMLPWeightsFromTensors(
706	            textTensors, mTextFC1Weight, mTextFC1Bias, mTextFC2Weight, mTextFC2Bias, "text_projection"))
707	    {
708	        return false;
709	    }
710	
711	    // Load hidden_projection weights (same architecture as text_projection, different weights)
712	    std::filesystem::path const hiddenProjPath = std::filesystem::path(weightsDir) / "hidden_projection.safetensors";
713	    if (std::filesystem::exists(hiddenProjPath))
714	    {
715	        mIsOmni = true;
716	        std::vector<rt::Tensor> hiddenTensors;
717	        if (!safetensors::loadSafetensors(hiddenProjPath, hiddenTensors, stream))
718	        {
719	            LOG_ERROR("Failed to load hidden_projection from: %s", hiddenProjPath.string().c_str());
720	            return false;
721	        }
722	        if (!extractMLPWeightsFromTensors(
723	                hiddenTensors, mHiddenFC1Weight, mHiddenFC1Bias, mHiddenFC2Weight, mHiddenFC2Bias, "hidden_projection"))
724	        {
725	            return false;
726	        }
727	        LOG_INFO("hidden_projection weights loaded from: %s", hiddenProjPath.string().c_str());
728	    }
729	    else
730	    {
731	        mIsOmni = false;
732	        LOG_INFO("hidden_projection.safetensors not found at %s (multimodal token projection unavailable)",
733	            hiddenProjPath.string().c_str());
734	    }
735	
736	    // Note: mTextEmbeddingTable is loaded separately in the constructor with mIsOmni-aware path selection
737	    // (TTS: text_embedding.safetensors from talkerEngineDir, Omni: embedding.safetensors from tokenizerDir)
738	
739	    // Load Talker embedding table
740	    std::filesystem::path const talkerEmbedPath = std::filesystem::path(weightsDir) / "embedding.safetensors";
741	    std::vector<rt::Tensor> talkerEmbedTensors;
742	    if (!safetensors::loadSafetensors(talkerEmbedPath, talkerEmbedTensors, stream))
743	    {
744	        LOG_ERROR("Failed to load Talker embedding from: %s", talkerEmbedPath.string().c_str());
745	        return false;
746	    }
747	    check::check(talkerEmbedTensors.size() == 1, "Talker embedding.safetensors should contain exactly one tensor");
748	    check::check(talkerEmbedTensors[0].getShape().getNumDims() == 2,
749	        "Talker embedding tensor should be 2D [vocabSize, hiddenSize]");
750	    mTalkerEmbeddingTable = std::move(talkerEmbedTensors[0]);
751	    LOG_INFO("Talker embedding table loaded: [%lld, %lld]", mTalkerEmbeddingTable.getShape()[0],
752	        mTalkerEmbeddingTable.getShape()[1]);
753	
754	    LOG_INFO("Talker weights loaded successfully");
755	    return true;
756	}
