758	void Qwen3OmniTTSRuntime::initializeTTSEmbeddings(cudaStream_t stream)
759	{
760	    NVTX_SCOPED_RANGE(nvtx_range, "TalkerRunner::initializeTTSEmbeddings", nvtx_colors::YELLOW);
761	
762	    auto const shape = mTextEmbeddingTable.getShape();
763	    ELLM_CHECK(
764	        shape.getNumDims() == 2, "Text embedding table must be 2D, got " + std::to_string(shape.getNumDims()) + "D");
765	
766	    int64_t const vocabSize = shape[0];
767	    int64_t const thinkerHiddenSize = shape[1];
768	
769	    ELLM_CHECK(mTalkerConfig.ttsPadTokenId < vocabSize && mTalkerConfig.ttsBosTokenId < vocabSize
770	            && mTalkerConfig.ttsEosTokenId < vocabSize,
771	        "TTS token IDs out of vocab range: pad=" + std::to_string(mTalkerConfig.ttsPadTokenId)
772	            + ", bos=" + std::to_string(mTalkerConfig.ttsBosTokenId)
773	            + ", eos=" + std::to_string(mTalkerConfig.ttsEosTokenId) + ", vocabSize=" + std::to_string(vocabSize));
774	
775	    constexpr int32_t kNumTtsTokens = 3;
776	    std::vector<int32_t> const hostTtsIds
777	        = {mTalkerConfig.ttsPadTokenId, mTalkerConfig.ttsBosTokenId, mTalkerConfig.ttsEosTokenId};
778	
779	    rt::Tensor ttsIds({1, kNumTtsTokens}, rt::DeviceType::kGPU, nvinfer1::DataType::kINT32);
780	    rt::Tensor ttsRaw({1, kNumTtsTokens, thinkerHiddenSize}, rt::DeviceType::kGPU, nvinfer1::DataType::kHALF);
781	    rt::Tensor ttsProjected(
782	        {kNumTtsTokens, mTalkerConfig.talkerHiddenSize}, rt::DeviceType::kGPU, nvinfer1::DataType::kHALF);
783	    rt::Tensor workspace({kNumTtsTokens, thinkerHiddenSize}, rt::DeviceType::kGPU, nvinfer1::DataType::kHALF);
784	
785	    CUDA_CHECK(cudaMemcpyAsync(
786	        ttsIds.rawPointer(), hostTtsIds.data(), kNumTtsTokens * sizeof(int32_t), cudaMemcpyHostToDevice, stream));
787	
788	    kernel::embeddingLookup(ttsIds, mTextEmbeddingTable, std::nullopt, ttsRaw, stream);
789	    // Reshape from [1, 3, hidden] to [3, hidden] for MLP (expects 2D input)
790	    check::check(ttsRaw.reshape({kNumTtsTokens, thinkerHiddenSize}), "Tensor reshape failed");
791	    kernel::invokeTalkerMLP(
792	        ttsRaw, mTextFC1Weight, mTextFC1Bias, mTextFC2Weight, mTextFC2Bias, ttsProjected, workspace, stream);
793	
794	    int64_t const hiddenSize = mTalkerConfig.talkerHiddenSize;
795	    mTtsPadEmbed = rt::Tensor({hiddenSize}, rt::DeviceType::kGPU, nvinfer1::DataType::kHALF);
796	    mTtsBosEmbed = rt::Tensor({hiddenSize}, rt::DeviceType::kGPU, nvinfer1::DataType::kHALF);
797	    mTtsEosEmbed = rt::Tensor({hiddenSize}, rt::DeviceType::kGPU, nvinfer1::DataType::kHALF);
798	
799	    __half* const projectedPtr = static_cast<__half*>(ttsProjected.rawPointer());
800	    size_t const embedSize = hiddenSize * sizeof(__half);
801	
802	    CUDA_CHECK(cudaMemcpyAsync(
803	        mTtsPadEmbed.rawPointer(), projectedPtr + 0 * hiddenSize, embedSize, cudaMemcpyDeviceToDevice, stream));
804	    CUDA_CHECK(cudaMemcpyAsync(
805	        mTtsBosEmbed.rawPointer(), projectedPtr + 1 * hiddenSize, embedSize, cudaMemcpyDeviceToDevice, stream));
806	    CUDA_CHECK(cudaMemcpyAsync(
807	        mTtsEosEmbed.rawPointer(), projectedPtr + 2 * hiddenSize, embedSize, cudaMemcpyDeviceToDevice, stream));
808	
809	    LOG_INFO("TTS embeddings initialized");
810	}
