812	bool Qwen3OmniTTSRuntime::projectToTalkerInput(
813	    rt::Tensor const& thinkerEmbed, int32_t speakerId, rt::Tensor& output, int64_t& outputSeqLen, cudaStream_t stream)
814	{
815	    int64_t const seqLen = thinkerEmbed.getShape()[0];
816	    int64_t const hiddenSize = mTalkerConfig.talkerHiddenSize;
817	    int64_t const thinkerHiddenSize = mTalkerConfig.thinkerHiddenSize;
818	
819	    // N = text tokens after stripping 3-token role prefix and 5-token suffix
820	    int64_t const N = seqLen - kAssistantPrefixLen - kAssistantTrailingSuffix;
821	    // Non-streaming prefill: 8 fixed prefix rows + N text rows + 2 suffix rows
822	    outputSeqLen = kNonStreamingPrefixRows + N + 2; // = seqLen + 2
823	    LOG_INFO("projectToTalkerInput: seqLen=%ld, N=%ld (stripped prefix=%d suffix=%d), outputSeqLen=%ld, speakerId=%d",
824	        seqLen, N, kAssistantPrefixLen, kAssistantTrailingSuffix, outputSeqLen, speakerId);
825	
826	    // Project all tokens via text_projection MLP
827	    check::check(mProjectedBuffer.reshape({seqLen, hiddenSize}), "Tensor reshape failed");
828	    check::check(mMLPWorkspace.reshape({seqLen, thinkerHiddenSize}), "Tensor reshape failed");
829	    kernel::invokeTalkerMLP(thinkerEmbed, mTextFC1Weight, mTextFC1Bias, mTextFC2Weight, mTextFC2Bias, mProjectedBuffer,
830	        mMLPWorkspace, stream);
831	
832	    // Fused kernel: build complete non-streaming prefill buffer
833	    check::check(output.reshape({outputSeqLen, hiddenSize}), "Tensor reshape failed");
834	    kernel::invokeAssistantPreamble(mProjectedBuffer, mTtsPadEmbed, mTtsBosEmbed, mTtsEosEmbed, mTalkerEmbeddingTable,
835	        mTalkerConfig.codecNothinkId, mTalkerConfig.codecThinkBosId, mTalkerConfig.codecThinkEosId, speakerId,
836	        mTalkerConfig.codecPadId, mTalkerConfig.codecBosId, static_cast<int32_t>(N), output, stream);
837	
838	    return true;
839	}
