841	bool Qwen3OmniTTSRuntime::executeTalkerPrefillStep(rt::Tensor const& inputEmbeds, rt::Tensor& outputLogits,
842	    rt::Tensor& outputHiddenStates, cudaStream_t stream, std::vector<int64_t> const& perBatchContextLengths)
843	{
844	    NVTX_SCOPED_RANGE(nvtx_range, "TalkerRunner::executeTalkerPrefillStep", nvtx_colors::PURPLE);
845	
846	    auto inputShape = inputEmbeds.getShape();
847	    if (inputShape.getNumDims() != 3)
848	    {
849	        LOG_ERROR("executeTalkerPrefillStep: Input must be 3D [batchSize, seqLen, hiddenSize], got %dD",
850	            inputShape.getNumDims());
851	        return false;
852	    }
853	
854	    int64_t const batchSize = inputEmbeds.getTRTDims().d[0];
855	    int64_t const seqLen = inputEmbeds.getTRTDims().d[1];
856	
857	    if (batchSize > mMaxBatchSize)
858	    {
859	        LOG_ERROR("executeTalkerPrefillStep: batchSize %ld exceeds maxBatchSize %d", batchSize, mMaxBatchSize);
860	        return false;
861	    }
862	
863	    // Reset Talker KV cache — shape must match batchSize so commitSequenceLength sees consistent activeBatchSize
864	    auto& talkerCacheMgr = *mTalkerSharedRes->cacheManagers[0];
865	    check::check(mHostReuseKVCacheLengths.reshape({batchSize}), "Tensor reshape failed");
866	    std::fill_n(mHostReuseKVCacheLengths.dataPointer<int32_t>(), batchSize, 0);
867	    talkerCacheMgr.resetForNewSequences(mHostReuseKVCacheLengths, stream);
868	
869	    // Stage per-batch context lengths into PipelineIO's host buffer.
870	    // StepPreparer consumes hostContextLengths to fill GPU contextLengths + selectTokenIndices.
871	    check::check(mTalkerPipelineIO->hostContextLengths.reshape({batchSize}), "Tensor reshape failed");
872	    int32_t* hostContextLength = mTalkerPipelineIO->hostContextLengths.dataPointer<int32_t>();
873	    if (!perBatchContextLengths.empty())
874	    {
875	        for (int64_t i = 0; i < batchSize; ++i)
876	        {
877	            hostContextLength[i] = static_cast<int32_t>(perBatchContextLengths[i]);
878	        }
879	    }
880	    else
881	    {
882	        for (int64_t i = 0; i < batchSize; ++i)
883	        {
884	            hostContextLength[i] = static_cast<int32_t>(seqLen);
885	        }
886	    }
887	    // Reshape logits to match the prefill batch size (CUDA graph capture may leave it at maxBS).
888	    check::check(outputLogits.reshape({batchSize, outputLogits.getShape()[outputLogits.getShape().getNumDims() - 1]}),
889	        "Tensor reshape failed");
890	
891	    // Bind step-specific tensors into the Talker TensorMap. Engine I/O bindings whose
892	    // address/shape change per step (inputs_embeds, logits, hidden_states) get rewired here;
893	    // KV cache and rope cache were registered statically by buildTensorMap.
894	    mTalkerTensorMap.set(binding_names::kInputsEmbeds, const_cast<rt::Tensor&>(inputEmbeds));
895	    mTalkerTensorMap.set(binding_names::kLogits, outputLogits);
896	    mTalkerTensorMap.set(binding_names::kOutputHiddenStates, outputHiddenStates);
897	
898	    // Prepare per-step metadata (selectTokenIndices, contextLengths, kvcache_start_index sentinel).
899	    mTalkerStepPreparer->prepare(
900	        rt::InferencePhase::kPrefill, static_cast<int32_t>(batchSize), talkerCacheMgr, *mTalkerPipelineIO, stream);
901	
902	    bool const kvAllEmpty = talkerCacheMgr.getKVCacheAllEmpty();
903	    auto const prefillDims = mTalkerLLMConfig.prefillDims(batchSize, seqLen, kvAllEmpty);
904	    if (!mTalkerExec->prepare(/*prefillProfile=*/0, prefillDims, mTalkerTensorMap, stream))
905	    {
906	        LOG_ERROR("Talker prefill prepare failed");
907	        return false;
908	    }
909	    if (!mTalkerExec->execute(stream))
910	    {
911	        LOG_ERROR("Talker prefill execute failed");
912	        return false;
913	    }
914	    talkerCacheMgr.commitSequenceLength(mTalkerPipelineIO->contextLengths, stream);
915	    return true;
916	}
