918	bool Qwen3OmniTTSRuntime::executeTalkerDecodingStep(
919	    rt::Tensor const& inputEmbeds, rt::Tensor& outputLogits, rt::Tensor& outputHiddenStates, cudaStream_t stream)
920	{
921	    NVTX_SCOPED_RANGE(nvtx_range, "TalkerRunner::executeTalkerDecodingStep", nvtx_colors::PURPLE);
922	
923	    auto inputShape = inputEmbeds.getShape();
924	    check::check(inputShape.getNumDims() == 3, "executeTalkerDecodingStep: inputEmbeds must be 3D [batch, 1, hidden]");
925	    int64_t const batchSize = inputShape[0];
926	    check::check(batchSize <= mMaxBatchSize, "executeTalkerDecodingStep: batchSize exceeds maxBatchSize");
927	
928	    auto& talkerCacheMgr = *mTalkerSharedRes->cacheManagers[0];
929	
930	    mTalkerTensorMap.set(binding_names::kInputsEmbeds, const_cast<rt::Tensor&>(inputEmbeds));
931	    mTalkerTensorMap.set(binding_names::kLogits, outputLogits);
932	    mTalkerTensorMap.set(binding_names::kOutputHiddenStates, outputHiddenStates);
933	
934	    mTalkerStepPreparer->prepare(
935	        rt::InferencePhase::kDecode, static_cast<int32_t>(batchSize), talkerCacheMgr, *mTalkerPipelineIO, stream);
936	
937	    auto const decodeDims = mTalkerLLMConfig.decodeDims(batchSize);
938	    if (!mTalkerExec->prepare(/*decodeProfile=*/1, decodeDims, mTalkerTensorMap, stream))
939	    {
940	        LOG_ERROR("Talker decode prepare failed");
941	        return false;
942	    }
943	    if (!mTalkerExec->execute(stream))
944	    {
945	        LOG_ERROR("Talker decode execute failed");
946	        return false;
947	    }
948	    // Vanilla decode advances the KV cache by exactly 1 token per call (matches kVANILLA_DECODE_INCREMENT).
949	    talkerCacheMgr.commitSequenceLength(/*increment=*/1, stream);
950	    return true;
951	}
