953	bool Qwen3OmniTTSRuntime::executeCodePredictorPrefillStep(rt::Tensor const& inputsEmbeds, int32_t lmHeadIdx,
954	    rt::Tensor& outputLogits, rt::Tensor& outputHiddenStates, cudaStream_t stream)
955	{
956	    NVTX_SCOPED_RANGE(nvtx_range, "TalkerRunner::executeCodePredictorPrefillStep", nvtx_colors::ORANGE);
957	
958	    // Batch dim is implicit in input shape — same pattern as executeTalkerPrefillStep / spec decode.
959	    auto inputShape = inputsEmbeds.getShape();
960	    check::check(inputShape.getNumDims() == 3,
961	        "executeCodePredictorPrefillStep: inputsEmbeds must be 3D [batch, seqLen, cpHidden]");
962	    int64_t const batchSize = inputShape[0];
963	    int64_t const seqLen = inputShape[1];
964	    check::check(batchSize <= mMaxBatchSize, "executeCodePredictorPrefillStep: batchSize exceeds maxBatchSize");
965	
966	    auto& cpCacheMgr = *mCodePredictorSharedRes->cacheManagers[0];
967	
968	    // Reset CP KV cache for this batch (CP resets every frame — no cross-frame state).
969	    check::check(mHostReuseKVCacheLengths.reshape({batchSize}), "Tensor reshape failed");
970	    int32_t* reuseData = mHostReuseKVCacheLengths.dataPointer<int32_t>();
971	    std::fill_n(reuseData, batchSize, 0);
972	    cpCacheMgr.resetForNewSequences(mHostReuseKVCacheLengths, stream);
973	
974	    // Stage per-batch host context lengths (all = kCodePredictorPrefillSeqLen).
975	    check::check(mCodePredictorPipelineIO->hostContextLengths.reshape({batchSize}), "Tensor reshape failed");
976	    int32_t* hostCtxLen = mCodePredictorPipelineIO->hostContextLengths.dataPointer<int32_t>();
977	    std::fill_n(hostCtxLen, batchSize, static_cast<int32_t>(seqLen));
978	
979	    int32_t const clampedLmHeadIdx = std::min(lmHeadIdx, mNumRvqLayers - 1);
980	
981	    mCodePredictorTensorMap.set(binding_names::kInputsEmbeds, const_cast<rt::Tensor&>(inputsEmbeds));
982	    mCodePredictorTensorMap.set(binding_names::kLogits, outputLogits);
983	    mCodePredictorTensorMap.set(binding_names::kOutputHiddenStates, outputHiddenStates);
984	    mCodePredictorTensorMap.set(binding_names::kLmHeadWeight, mCodePredictorLmHeadWeights[clampedLmHeadIdx]);
985	
986	    mCodePredictorStepPreparer->prepare(
987	        rt::InferencePhase::kPrefill, static_cast<int32_t>(batchSize), cpCacheMgr, *mCodePredictorPipelineIO, stream);
988	
989	    bool const kvAllEmpty = cpCacheMgr.getKVCacheAllEmpty();
990	    auto const prefillDims = mCodePredictorConfig.prefillDims(batchSize, seqLen, kvAllEmpty);
991	    if (!mCodePredictorExec->prepare(/*prefillProfile=*/0, prefillDims, mCodePredictorTensorMap, stream))
992	    {
993	        LOG_ERROR("CodePredictor prefill prepare failed");
994	        return false;
995	    }
996	    if (!mCodePredictorExec->execute(stream))
997	    {
998	        LOG_ERROR("CodePredictor prefill execute failed");
999	        return false;
1000	    }
1001	    cpCacheMgr.commitSequenceLength(mCodePredictorPipelineIO->contextLengths, stream);
1002	    return true;
1003	}
