1005	bool Qwen3OmniTTSRuntime::executeCodePredictorDecodingStep(rt::Tensor const& inputsEmbeds, int32_t lmHeadIdx,
1006	    rt::Tensor& outputLogits, rt::Tensor& outputHiddenStates, cudaStream_t stream)
1007	{
1008	    NVTX_SCOPED_RANGE(nvtx_range, "TalkerRunner::executeCodePredictorDecodingStep", nvtx_colors::ORANGE);
1009	
1010	    auto inputShape = inputsEmbeds.getShape();
1011	    check::check(
1012	        inputShape.getNumDims() == 3, "executeCodePredictorDecodingStep: inputsEmbeds must be 3D [batch, 1, cpHidden]");
1013	    int64_t const batchSize = inputShape[0];
1014	    check::check(batchSize <= mMaxBatchSize, "executeCodePredictorDecodingStep: batchSize exceeds maxBatchSize");
1015	
1016	    auto& cpCacheMgr = *mCodePredictorSharedRes->cacheManagers[0];
1017	    int32_t const clampedLmHeadIdx = std::min(lmHeadIdx, mNumRvqLayers - 1);
1018	
1019	    mCodePredictorTensorMap.set(binding_names::kInputsEmbeds, const_cast<rt::Tensor&>(inputsEmbeds));
1020	    mCodePredictorTensorMap.set(binding_names::kLogits, outputLogits);
1021	    mCodePredictorTensorMap.set(binding_names::kOutputHiddenStates, outputHiddenStates);
1022	    mCodePredictorTensorMap.set(binding_names::kLmHeadWeight, mCodePredictorLmHeadWeights[clampedLmHeadIdx]);
1023	
1024	    mCodePredictorStepPreparer->prepare(
1025	        rt::InferencePhase::kDecode, static_cast<int32_t>(batchSize), cpCacheMgr, *mCodePredictorPipelineIO, stream);
1026	
1027	    auto const decodeDims = mCodePredictorConfig.decodeDims(batchSize);
1028	    if (!mCodePredictorExec->prepare(/*decodeProfile=*/1, decodeDims, mCodePredictorTensorMap, stream))
1029	    {
1030	        LOG_ERROR("CodePredictor decode prepare failed");
1031	        return false;
1032	    }
1033	    if (!mCodePredictorExec->execute(stream))
1034	    {
1035	        LOG_ERROR("CodePredictor decode execute failed");
1036	        return false;
1037	    }
1038	    cpCacheMgr.commitSequenceLength(/*increment=*/1, stream);
1039	    return true;
1040	}
