1043	
1044	bool Qwen3OmniTTSRuntime::captureDecodingCUDAGraph(cudaStream_t stream)
1045	{
1046	    std::string const emptyLoraWeightsName = "";
1047	
1048	    // Talker: capture for all supported batch sizes (1..maxBatchSize).
1049	    // EngineExecutor::captureGraph() hashes the current binding state, so each bs
1050	    // produces its own graph slot automatically.
1051	    bool captureStatus{true};
1052	    auto& talkerCacheMgr = *mTalkerSharedRes->cacheManagers[0];
1053	    for (int32_t bs = 1; bs <= mMaxBatchSize; ++bs)
1054	    {
1055	        // Simulate a mid-sequence decode state for capture (matches `simulateCacheLength=128`),
1056	        // so the captured graph reflects realistic plugin shapes / KV-length math.
1057	        constexpr int32_t kSimulateCacheLength{128};
1058	        std::vector<int32_t> reuseLens(bs, kSimulateCacheLength);
1059	        rt::Tensor simulatedReuse(reuseLens.data(), rt::Coords{bs}, rt::DeviceType::kCPU, nvinfer1::DataType::kINT32);
1060	        talkerCacheMgr.resetForNewSequences(simulatedReuse, stream);
1061	
1062	        check::check(mResidualEmbedBuffer.reshape({bs, 1, mTalkerConfig.talkerHiddenSize}), "Tensor reshape failed");
1063	        check::check(
1064	            mTalkerHiddenStatesBuffer.reshape({bs, 1, mTalkerConfig.talkerHiddenSize}), "Tensor reshape failed");
1065	        check::check(mTalkerLogits.reshape({bs, mTalkerConfig.talkerVocabSize}), "Tensor reshape failed");
1066	
1067	        mTalkerTensorMap.set(binding_names::kInputsEmbeds, mResidualEmbedBuffer);
1068	        mTalkerTensorMap.set(binding_names::kLogits, mTalkerLogits);
1069	        mTalkerTensorMap.set(binding_names::kOutputHiddenStates, mTalkerHiddenStatesBuffer);
1070	
1071	        mTalkerStepPreparer->prepare(rt::InferencePhase::kDecode, bs, talkerCacheMgr, *mTalkerPipelineIO, stream);
1072	
1073	        auto const decodeDims = mTalkerLLMConfig.decodeDims(bs);
1074	        captureStatus &= mTalkerExec->prepare(/*decodeProfile=*/1, decodeDims, mTalkerTensorMap, stream);
1075	        captureStatus &= mTalkerExec->captureGraph(stream);
1076	    }
1077	    // Restore Talker KV cache to "empty" state for the first real prefill.
1078	    // The simulated-cache-length init above leaves both the per-batch lengths AND
1079	    // the engine-written stale KV contents in mid-sequence state; resetForNewSequences
1080	    // with zero lengths is what every real prefill expects.
1081	    {
1082	        std::vector<int32_t> zeroLens(mMaxBatchSize, 0);
1083	        rt::Tensor zeroReuse(
1084	            zeroLens.data(), rt::Coords{mMaxBatchSize}, rt::DeviceType::kCPU, nvinfer1::DataType::kINT32);
1085	        talkerCacheMgr.resetForNewSequences(zeroReuse, stream);
1086	    }
1087	
1088	    // CodePredictor: capture one graph per RVQ head (mNumRvqLayers total).
1089	    // Each graph uses a distinct (lm_head_weight, logits) binding pair, so the
1090	    // EngineExecutor binding hash naturally distinguishes them.
1091	    auto& cpCacheMgr = *mCodePredictorSharedRes->cacheManagers[0];
1092	    check::check(
1093	        mCodePredictorCodecEmbed.reshape({1, 1, mTalkerConfig.codePredictorHiddenSize}), "Tensor reshape failed");
1094	    check::check(mCodePredictorHiddenStatesBuffer.reshape({1, 1, mTalkerConfig.codePredictorHiddenSize}),
1095	        "Tensor reshape failed");
1096	
1097	    for (int32_t i = 0; i < mNumRvqLayers; ++i)
1098	    {
1099	        // Simulate a mid-sequence CP decode state for capture (matches kSimulateCacheLength=128).
1100	        constexpr int32_t kSimulateCacheLength{128};
1101	        int32_t simLen = kSimulateCacheLength;
1102	        rt::Tensor simReuse(&simLen, rt::Coords{1}, rt::DeviceType::kCPU, nvinfer1::DataType::kINT32);
1103	        cpCacheMgr.resetForNewSequences(simReuse, stream);
1104	
1105	        mCodePredictorTensorMap.set(binding_names::kInputsEmbeds, mCodePredictorCodecEmbed);
1106	        mCodePredictorTensorMap.set(binding_names::kLogits, mCodePredictorLogitsPerHead[i]);
1107	        mCodePredictorTensorMap.set(binding_names::kOutputHiddenStates, mCodePredictorHiddenStatesBuffer);
1108	        mCodePredictorTensorMap.set(binding_names::kLmHeadWeight, mCodePredictorLmHeadWeights[i]);
1109	
1110	        mCodePredictorStepPreparer->prepare(
1111	            rt::InferencePhase::kDecode, /*batchSize=*/1, cpCacheMgr, *mCodePredictorPipelineIO, stream);
1112	
1113	        auto const decodeDims = mCodePredictorConfig.decodeDims(1);
1114	        captureStatus &= mCodePredictorExec->prepare(/*decodeProfile=*/1, decodeDims, mCodePredictorTensorMap, stream);
1115	        captureStatus &= mCodePredictorExec->captureGraph(stream);
1116	    }
1117	    // Restore CP KV cache to empty so the first real prefill starts from a clean state.
1118	    {
1119	        int32_t zero = 0;
1120	        rt::Tensor zeroReuse(&zero, rt::Coords{1}, rt::DeviceType::kCPU, nvinfer1::DataType::kINT32);
1121	        cpCacheMgr.resetForNewSequences(zeroReuse, stream);
1122	    }
1123	
1124	    // (mCodePredictorGraphsCaptured flag removed — EngineExecutor's graph cache auto-dispatches per binding hash.)
1125	
1126	    if (captureStatus)
1127	    {
1128	        LOG_INFO("Successfully captured decoding CUDA graphs for Talker and all CodePredictor lm_heads.");
1129	    }
1130	    else
1131	    {
1132	        LOG_WARNING("Failed to capture some decoding CUDA graphs. Will use fallback engine execution.");
1133	    }
1134	
1135	    return captureStatus;
1136	}
