1139	
1140	bool Qwen3OmniTTSRuntime::prepareTalkerInput(std::vector<int32_t> const& textTokenIds,
1141	    TalkerGenerationRequest const& request, int64_t& outSeqLen, cudaStream_t stream)
1142	{
1143	    int64_t const seqLen = static_cast<int64_t>(textTokenIds.size());
1144	    if (seqLen == 0)
1145	    {
1146	        LOG_ERROR("prepareTalkerInput: empty token ID list");
1147	        return false;
1148	    }
1149	    int64_t const thinkerHiddenSize = mTextEmbeddingTable.getShape()[1];
1150	    check::check(mGpuTokenIdsBuffer.reshape({1, seqLen}), "Tensor reshape failed");
1151	    CUDA_CHECK(cudaMemcpyAsync(mGpuTokenIdsBuffer.rawPointer(), textTokenIds.data(), seqLen * sizeof(int32_t),
1152	        cudaMemcpyHostToDevice, stream));
1153	    check::check(mThinkerEmbedBuffer.reshape({1, seqLen, thinkerHiddenSize}), "Tensor reshape failed");
1154	    kernel::embeddingLookup(mGpuTokenIdsBuffer, mTextEmbeddingTable, std::nullopt, mThinkerEmbedBuffer, stream);
1155	    check::check(mThinkerEmbedBuffer.reshape({seqLen, thinkerHiddenSize}), "Tensor reshape failed");
1156	
1157	    // Determine speaker ID
1158	    int32_t speakerId = mTalkerConfig.defaultSpeakerId;
1159	    if (request.speakerId >= 0)
1160	    {
1161	        speakerId = request.speakerId;
1162	    }
1163	    else if (!request.speakerName.empty())
1164	    {
1165	        speakerId = getSpeakerIdByName(request.speakerName);
1166	    }
1167	
1168	    // MLP projection: thinker embed → talker input embeds (non-streaming, outputSeqLen = seqLen + 2)
1169	    int64_t const hiddenSize = mTalkerConfig.talkerHiddenSize;
1170	    if (!projectToTalkerInput(mThinkerEmbedBuffer, speakerId, mTalkerInputEmbeds, outSeqLen, stream))
1171	    {
1172	        LOG_ERROR("MLP projection failed");
1173	        return false;
1174	    }
1175	
1176	    // Reshape buffers to 3D [1, seqLen, H] for Talker LLM input
1177	    check::check(mTalkerInputEmbeds.reshape({1, outSeqLen, hiddenSize}), "Tensor reshape failed");
1178	    check::check(
1179	        mTalkerHiddenStatesBuffer.reshape({1, outSeqLen, mTalkerConfig.talkerHiddenSize}), "Tensor reshape failed");
1180	    return true;
1181	}
1182	
1183	bool Qwen3OmniTTSRuntime::handleAudioGeneration(
1184	    std::vector<TalkerGenerationRequest> const& requests, TalkerGenerationResponse& response, cudaStream_t stream)
1185	{
1186	    NVTX_SCOPED_RANGE(nvtx_range, "TalkerRunner::handleAudioGeneration", nvtx_colors::PURPLE);
1187	    int32_t const activeBatchSize = static_cast<int32_t>(requests.size());
1188	    LOG_INFO("Starting batched audio generation for %d request(s)", activeBatchSize);
1189	
1190	    check::check(activeBatchSize > 0 && activeBatchSize <= mMaxBatchSize,
1191	        "Batch size " + std::to_string(activeBatchSize) + " exceeds max " + std::to_string(mMaxBatchSize));
1192	
1193	    response.batchRvqCodes.clear();
1194	    response.numFramesPerSample.clear();
1195	    response.success = false;
1196	
1197	    // Sampling params from requests[0], applied uniformly (matches LLMInferenceRuntime design)
1198	    auto const& req0 = requests[0];
1199	    float const talkerTemperature = (req0.talkerTemperature > 0) ? req0.talkerTemperature : 0.9f;
1200	    int32_t const talkerTopK = (req0.talkerTopK > 0) ? req0.talkerTopK : 50;
1201	    float const talkerTopP = (req0.talkerTopP > 0) ? req0.talkerTopP : 1.0f;
1202	    float const repetitionPenalty = req0.repetitionPenalty;
1203	
1204	    SamplingParams talkerSamplingParams(
1205	        activeBatchSize, mTalkerConfig.talkerVocabSize, talkerTemperature, talkerTopK, talkerTopP);
1206	    // CP sampling params come from HF's hardcoded ``code_predictor.generate``
1207	    // defaults; see ``kCPSamplingTemperature`` / ``kCPSamplingTopK`` /
1208	    // ``kCPSamplingTopP`` in qwen3OmniTTSRuntime.h for the source-code links.
1209	    SamplingParams predictorSamplingParams(
1210	        1, mTalkerConfig.codebookSize, kCPSamplingTemperature, kCPSamplingTopK, kCPSamplingTopP);
1211	    SamplingParams singleSamplingParams(1, mTalkerConfig.talkerVocabSize, talkerTemperature, talkerTopK, talkerTopP);
1212	
1213	    // Build per-batch Talker prefill embeddings into mTalkerInputEmbeds, then run a single
1214	    // batched prefill at bs=activeBatchSize (same pattern as handleAudioGenerationFromThinker).
1215	    // Per-batch sequential prefill is fundamentally wrong for bs>1: it overwrites mTalkerHiddenStatesBuffer
1216	    // slot 0 + Talker KV cache slot 0 each iteration, losing earlier batches' state.
1217	    std::vector<PerBatchTalkerState> states(activeBatchSize);
1218	    std::vector<int64_t> perBatchSeqLens(activeBatchSize);
1219	    int64_t const maxInputSeqLen = mTalkerLLMConfig.maxSupportedInputLength;
1220	    int64_t const hiddenSize = mTalkerConfig.talkerHiddenSize;
1221	    int64_t maxOutSeqLen = 0;
1222	
1223	    auto buildOneBatchTts = [&](int32_t b) -> bool {
1224	        LLMGenerationRequest::Request llmReq;
1225	        llmReq.messages = requests[b].messages;
1226	        LLMGenerationRequest::FormattedRequest formatted;
1227	        if (!mTokenizer->applyChatTemplate(llmReq, formatted, requests[b].applyChatTemplate,
1228	                requests[b].addGenerationPrompt, requests[b].enableThinking))
1229	        {
1230	            LOG_ERROR("Chat template failed for batch %d", b);
1231	            return false;
1232	        }
1233	        std::vector<int32_t> const textTokenIds = mTokenizer->encode(formatted.formattedCompleteRequest);
1234	
1235	        int64_t seqLen = 0;
1236	        if (!prepareTalkerInput(textTokenIds, requests[b], seqLen, stream))
1237	        {
1238	            LOG_ERROR("Input preparation failed for batch %d", b);
1239	            return false;
1240	        }
1241	        perBatchSeqLens[b] = seqLen;
1242	        maxOutSeqLen = std::max(maxOutSeqLen, seqLen);
1243	        return true;
1244	    };
1245	
1246	    // Build batches N-1..1 first, stash each into slot (b * maxInputSeqLen).
1247	    for (int32_t b = activeBatchSize - 1; b >= 1; --b)
1248	    {
1249	        if (!buildOneBatchTts(b))
1250	            return false;
1251	        __half* const slot = static_cast<__half*>(mTalkerInputEmbeds.rawPointer()) + b * maxInputSeqLen * hiddenSize;
1252	        CUDA_CHECK(cudaMemcpyAsync(slot, mTalkerInputEmbeds.rawPointer(),
1253	            perBatchSeqLens[b] * hiddenSize * sizeof(__half), cudaMemcpyDeviceToDevice, stream));
1254	    }
1255	    // Build batch 0 last — stays at slot 0.
1256	    if (!buildOneBatchTts(0))
1257	        return false;
1258	
1259	    // Re-pack from slots [b * maxInputSeqLen] → contiguous [BS, maxOutSeqLen, H]; pad with zeros.
1260	    __half* const inputBase = static_cast<__half*>(mTalkerInputEmbeds.rawPointer());
1261	    for (int32_t b = activeBatchSize - 1; b >= 0; --b)
1262	    {
1263	        __half* const src = inputBase + (b == 0 ? 0 : b * maxInputSeqLen * hiddenSize);
1264	        __half* const dst = inputBase + b * maxOutSeqLen * hiddenSize;
1265	        if (src != dst)
1266	        {
1267	            CUDA_CHECK(cudaMemcpyAsync(
1268	                dst, src, perBatchSeqLens[b] * hiddenSize * sizeof(__half), cudaMemcpyDeviceToDevice, stream));
1269	        }
1270	        if (perBatchSeqLens[b] < maxOutSeqLen)
1271	        {
1272	            CUDA_CHECK(cudaMemsetAsync(dst + perBatchSeqLens[b] * hiddenSize, 0,
1273	                (maxOutSeqLen - perBatchSeqLens[b]) * hiddenSize * sizeof(__half), stream));
1274	        }
1275	    }
1276	
1277	    // Single batched Talker prefill at bs=activeBatchSize.
1278	    check::check(mTalkerInputEmbeds.reshape({activeBatchSize, maxOutSeqLen, hiddenSize}), "Tensor reshape failed");
1279	    check::check(
1280	        mTalkerHiddenStatesBuffer.reshape({activeBatchSize, maxOutSeqLen, hiddenSize}), "Tensor reshape failed");
1281	    {
1282	        TIME_STAGE(metrics::StageNames::kTALKER_PREFILL, stream);
1283	        if (!executeTalkerPrefillStep(
1284	                mTalkerInputEmbeds, mTalkerLogits, mTalkerHiddenStatesBuffer, stream, perBatchSeqLens))
1285	        {
1286	            LOG_ERROR("Batched Talker prefill failed");
1287	            return false;
1288	        }
1289	    }
1290	
1291	    // Per-batch logit adjust on [BS, vocab] slices.
1292	    check::check(mTalkerLogits.reshape({activeBatchSize, mTalkerConfig.talkerVocabSize}), "Tensor reshape failed");
1293	    check::check(mTalkerSelectedIndices.reshape({activeBatchSize, 1}), "Tensor reshape failed");
1294	    for (int32_t b = 0; b < activeBatchSize; ++b)
1295	    {
1296	        rt::Tensor logitsSlice(static_cast<float*>(mTalkerLogits.rawPointer()) + b * mTalkerConfig.talkerVocabSize,
1297	            rt::Coords{1, mTalkerConfig.talkerVocabSize}, rt::DeviceType::kGPU, nvinfer1::DataType::kFLOAT);
1298	        rt::Tensor seenBufSlice(mSeenCodecTokensBuf.dataPointer<int32_t>() + b * mTalkerLLMConfig.maxKVCacheCapacity,
1299	            rt::Coords{mTalkerLLMConfig.maxKVCacheCapacity}, rt::DeviceType::kGPU, nvinfer1::DataType::kINT32);
1300	        kernel::invokeTalkerLogitAdjust(seenBufSlice, logitsSlice, mTalkerConfig.talkerVocabSize - 1024,
1301	            mTalkerConfig.talkerVocabSize, mTalkerConfig.codecEosId, 0, repetitionPenalty, stream);
1302	    }
1303	
1304	    // Batched sampling at bs=activeBatchSize.
1305	    trt_edgellm::topKtopPSamplingFromLogits(
1306	        mTalkerLogits, mTalkerSelectedIndices, talkerSamplingParams, mSamplingWorkspace, stream);
1307	    check::check(mHostSelectedTokenIds.reshape({activeBatchSize}), "Tensor reshape failed");
1308	    CUDA_CHECK(cudaMemcpyAsync(mHostSelectedTokenIds.rawPointer(), mTalkerSelectedIndices.rawPointer(),
1309	        activeBatchSize * sizeof(int32_t), cudaMemcpyDeviceToHost, stream));
1310	    CUDA_CHECK(cudaStreamSynchronize(stream));
1311	    int32_t* hostTokens = mHostSelectedTokenIds.dataPointer<int32_t>();
1312	    for (int32_t b = 0; b < activeBatchSize; ++b)
1313	    {
1314	        states[b].codecToken = hostTokens[b];
1315	        states[b].rvqCodes.reserve(requests[b].maxAudioLength);
1316	        LOG_INFO("Batch %d: first codec token: %d", b, states[b].codecToken);
1317	    }
1318	    (void) singleSamplingParams; // bs=1-only param kept for streaming path; unused here after batching.
1319	
1320	    // First codec token sampled — record TTFA-end so streaming CLIs can compute time-to-first-code.
1321	    // Same point as handleAudioGenerationFromThinker / handleStreamingGeneration; unconditional record
1322	    // is cheap (~µs) and lets non-profiling callers still consume the event for streaming latency.
1323	    if (mTtfaEnd)
1324	    {
1325	        CUDA_CHECK(cudaEventRecord(mTtfaEnd, stream));
1326	    }
1327	
1328	    int32_t const talkerKVCapacity = mTalkerLLMConfig.maxKVCacheCapacity;
1329	    int32_t effectiveMaxFrames = 0;
1330	    for (int32_t b = 0; b < activeBatchSize; ++b)
1331	    {
1332	        int32_t const safe = std::max(1, talkerKVCapacity - static_cast<int32_t>(perBatchSeqLens[b]));
1333	        effectiveMaxFrames = std::max(effectiveMaxFrames, std::min(requests[b].maxAudioLength, safe));
1334	    }
1335	
1336	    std::vector<rt::Tensor const*> trailingPtrs(activeBatchSize, nullptr);
1337	
1338	    // Wire optional per-request streaming callbacks. Empty vector when no request has streaming on
1339	    // (zero overhead for the non-streaming path).
1340	    std::vector<PerBatchStreamingHandler> streamingHandlers;
1341	    for (auto const& r : requests)
1342	    {
1343	        if (r.streamingChunkFrames > 0 && r.onChunkReady)
1344	        {
1345	            streamingHandlers.resize(activeBatchSize);
1346	            break;
1347	        }
1348	    }
1349	    if (!streamingHandlers.empty())
1350	    {
1351	        for (int32_t b = 0; b < activeBatchSize; ++b)
1352	        {
1353	            streamingHandlers[b].chunkFrames = requests[b].streamingChunkFrames;
1354	            streamingHandlers[b].onChunk = requests[b].onChunkReady;
1355	        }
1356	    }
1357	
1358	    if (!runTalkerGenerationLoop(states, activeBatchSize, effectiveMaxFrames, talkerSamplingParams,
1359	            predictorSamplingParams, repetitionPenalty, trailingPtrs, stream, perBatchSeqLens, streamingHandlers))
1360	    {
1361	        return false;
1362	    }
1363	
1364	    for (int32_t b = 0; b < activeBatchSize; ++b)
1365	    {
1366	        response.batchRvqCodes.push_back(std::move(states[b].rvqCodes));
1367	        response.numFramesPerSample.push_back(states[b].talkerFrames);
1368	    }
1369	
1370	    int32_t totalFrames = 0;
1371	    for (auto const& s : states)
1372	        totalFrames += s.talkerFrames;
1373	    mMultimodalMetrics.recordRun(0, 0, activeBatchSize, totalFrames);
1374	
1375	    response.success = true;
1376	    return true;
1377	}
1378	
1379	bool Qwen3OmniTTSRuntime::handleAudioGenerationFromThinker(
1380	    std::vector<OmniGenerationRequest> const& requests, TalkerGenerationResponse& response, cudaStream_t stream)
1381	{
1382	    NVTX_SCOPED_RANGE(nvtx_range, "TalkerRunner::handleAudioGenerationFromThinker", nvtx_colors::PURPLE);
1383	
1384	    int32_t const activeBatchSize = static_cast<int32_t>(requests.size());
1385	    LOG_INFO("Starting batched Omni audio generation for %d request(s)", activeBatchSize);
1386	
1387	    check::check(activeBatchSize > 0 && activeBatchSize <= mMaxBatchSize,
1388	        "Batch size " + std::to_string(activeBatchSize) + " exceeds max " + std::to_string(mMaxBatchSize));
1389	
1390	    response.batchRvqCodes.clear();
1391	    response.numFramesPerSample.clear();
1392	    response.success = false;
1393	
1394	    // Sampling params from requests[0], applied uniformly (matches LLMInferenceRuntime design)
1395	    auto const& req0 = requests[0];
1396	    float const talkerTemperature = (req0.talkerTemperature > 0) ? req0.talkerTemperature : 0.9f;
1397	    int32_t const talkerTopK = (req0.talkerTopK > 0) ? req0.talkerTopK : 50;
1398	    float const talkerTopP = (req0.talkerTopP > 0) ? req0.talkerTopP : 1.0f;
1399	    float const repetitionPenalty = req0.repetitionPenalty;
1400	
1401	    SamplingParams talkerSamplingParams(
1402	        activeBatchSize, mTalkerConfig.talkerVocabSize, talkerTemperature, talkerTopK, talkerTopP);
1403	    SamplingParams predictorSamplingParams(
1404	        1, mTalkerConfig.codebookSize, kCPSamplingTemperature, kCPSamplingTopK, kCPSamplingTopP);
1405	
1406	    int64_t const hiddenSize = mTalkerConfig.talkerHiddenSize;
1407	    int64_t const trailingStride = mTalkerConfig.maxSeqLen + 1;
1408	    std::vector<PerBatchTalkerState> states(activeBatchSize);
1409	    std::vector<rt::Tensor> perBatchTrailingViews(activeBatchSize);
1410	    std::vector<rt::Tensor const*> trailingPtrs(activeBatchSize, nullptr);
1411	
1412	    // Phase 1: Build per-batch Talker prefill embeddings.
1413	    // buildTalkerPrefillFromSegments writes to mTalkerInputEmbeds starting at row 0 (the "scratch"
1414	    // region). After building each batch we relocate the result to a safe per-batch slot at
1415	    // row ((b+1) * maxInputSeqLen) so that the next build's scratch write doesn't clobber it.
1416	    // Batch 0 is special: it's built last (after all others are safely stashed), so its data
1417	    // can stay in place at row 0.
1418	    int64_t const maxInputSeqLen = mTalkerLLMConfig.maxSupportedInputLength;
1419	    std::vector<int64_t> perBatchSeqLen(activeBatchSize);
1420	    int64_t maxOutSeqLen = 0;
1421	
1422	    // Process batches 1..N-1 first (stash each), then batch 0 last (stays in scratch = row 0)
1423	    auto buildOneBatch = [&](int32_t b) -> bool {
1424	        auto const& req = requests[b];
1425	        if (req.fullText.empty() && req.textTokenIds.empty())
1426	        {
1427	            LOG_ERROR("Omni request batch %d has empty fullText and no textTokenIds", b);
1428	            return false;
1429	        }
1430	
1431	        std::vector<int32_t> const textTokenIds
1432	            = req.textTokenIds.empty() ? mTokenizer->encode(req.fullText) : req.textTokenIds;
1433	
1434	        int32_t speakerId = mTalkerConfig.defaultSpeakerId;
1435	        if (req.speakerId >= 0)
1436	            speakerId = req.speakerId;
1437	        else if (!req.speakerName.empty())
1438	            speakerId = getSpeakerIdByName(req.speakerName);
1439	
1440	        __half* const batchTrailingPtr
1441	            = static_cast<__half*>(mStreamingTrailingHidden.rawPointer()) + b * trailingStride * hiddenSize;
1442	        rt::Tensor batchTrailingBuf(
1443	            batchTrailingPtr, rt::Coords{trailingStride, hiddenSize}, rt::DeviceType::kGPU, nvinfer1::DataType::kHALF);
1444	        CUDA_CHECK(cudaMemsetAsync(batchTrailingPtr, 0, trailingStride * hiddenSize * sizeof(__half), stream));
1445	
1446	        int32_t trailingCount = 0;
1447	        int64_t outSeqLen = 0;
1448	        if (!buildTalkerPrefillFromSegments(textTokenIds, req.thinkerPrefillEmbeds, req.thinkerHiddenStates,
1449	                req.prefillLength, mTextEmbeddingTable, speakerId, batchTrailingBuf, trailingCount, outSeqLen, stream))
1450	        {
1451	            return false;
1452	        }
1453	
1454	        finalizeTrailing(batchTrailingBuf, trailingCount, stream);
1455	        trailingCount++;
1456	
1457	        perBatchSeqLen[b] = outSeqLen;
1458	        maxOutSeqLen = std::max(maxOutSeqLen, outSeqLen);
1459	
1460	        perBatchTrailingViews[b]
1461	            = rt::Tensor(batchTrailingPtr, rt::Coords{static_cast<int64_t>(trailingCount), hiddenSize},
1462	                rt::DeviceType::kGPU, nvinfer1::DataType::kHALF);
1463	        trailingPtrs[b] = &perBatchTrailingViews[b];
1464	        states[b].rvqCodes.reserve(req.maxAudioLength);
1465	        return true;
1466	    };
1467	
1468	    // Build batches 1..N-1 first and stash each to slot (b * maxInputSeqLen)
1469	    for (int32_t b = activeBatchSize - 1; b >= 1; --b)
1470	    {
