1772	            check::check(
1773	                mTalkerLogits.reshape({activeBatchSize, mTalkerConfig.talkerVocabSize}), "Tensor reshape failed");
1774	            check::check(mTalkerSelectedIndices.reshape({activeBatchSize, 1}), "Tensor reshape failed");
1775	            trt_edgellm::topKtopPSamplingFromLogits(mTalkerLogits, mTalkerSelectedIndices, talkerSamplingParams,
1776	                mSamplingWorkspace, stream, 42, static_cast<uint64_t>(globalFrame + 1));
1777	            CUDA_CHECK(cudaMemcpyAsync(mHostSelectedTokenIds.rawPointer(), mTalkerSelectedIndices.rawPointer(),
1778	                activeBatchSize * sizeof(int32_t), cudaMemcpyDeviceToHost, stream));
1779	            CUDA_CHECK(cudaStreamSynchronize(stream));
1780	
1781	            // Per-batch: update state, check EOS
1782	            int32_t* hostTokens = mHostSelectedTokenIds.dataPointer<int32_t>();
1783	            for (int32_t b = 0; b < activeBatchSize; ++b)
1784	            {
1785	                if (states[b].finished)
1786	                    continue;
1787	
1788	                // Track seen token for repetition penalty
1789	                if (states[b].seenTokenSet.insert(states[b].codecToken).second)
1790	                {
1791	                    int32_t* seenBuf
1792	                        = mSeenCodecTokensBuf.dataPointer<int32_t>() + b * mTalkerLLMConfig.maxKVCacheCapacity;
1793	                    CUDA_CHECK(cudaMemcpyAsync(seenBuf + states[b].numSeenTokens,
1794	                        mTalkerSelectedIndices.dataPointer<int32_t>() + b, sizeof(int32_t), cudaMemcpyDeviceToDevice,
1795	                        stream));
1796	                    states[b].numSeenTokens++;
1797	                }
1798	
1799	                states[b].codecToken = hostTokens[b];
1800	                states[b].talkerFrames++;
1801	
1802	                if (states[b].codecToken == codecEosId || states[b].talkerFrames >= maxFrames)
1803	                {
1804	                    states[b].finished = true;
1805	                    unfinished--;
1806	                }
1807	            }
1808	            globalFrame++;
1809	        }
1810	    }
1811	
1812	    for (int32_t b = 0; b < activeBatchSize; ++b)
1813	    {
1814	        bool const hitEos = (states[b].codecToken == codecEosId);
1815	        LOG_INFO("Batch %d: %d audio frames (exit: %s)", b, states[b].talkerFrames, hitEos ? "EOS" : "maxFrames");
1816	    }
1817	
1818	    // Final per-batch flush: every active emitter gets exactly one isFinal=true callback (with
1819	    // remaining buffered codes, or empty buffer as an end-of-stream signal).
1820	    for (auto& emitter : emitters)
1821	    {
1822	        emitter.flushFinal();
1823	    }
1824	
1825	    return true;
1826	}
