1828	bool Qwen3OmniTTSRuntime::runSingleTalkerDecodeFrame(int32_t& codecToken, SamplingParams const& talkerSamplingParams,
1829	    SamplingParams const& predictorSamplingParams, rt::Tensor const* trailingPtr, int32_t frameIdx,
1830	    std::unordered_set<int32_t>& seenTokenSet, int32_t& numSeenTokens, float repetitionPenalty,
1831	    std::vector<std::vector<int32_t>>& rvqCodes, cudaStream_t stream)
1832	{
1833	    int32_t const codecEosId = mTalkerConfig.codecEosId;
1834	
1835	    // Streaming TTFA path: always bs=1. Reset CP KV is now done inside runCodePredictorGenerationForFrame.
1836	    if (!extractTalkerLastHidden(mTalkerHiddenStatesBuffer, mTalkerLastHidden, stream))
1837	    {
1838	        LOG_ERROR("extractTalkerLastHidden failed at frame %d", frameIdx);
1839	        return false;
1840	    }
1841	
1842	    // Wrap mTalkerLastHidden as a [1, talkerH] batched view for the unified CP call.
1843	    rt::Tensor talkerLastBatched(mTalkerLastHidden.rawPointer(), rt::Coords{1, mTalkerConfig.talkerHiddenSize},
1844	        rt::DeviceType::kGPU, nvinfer1::DataType::kHALF);
1845	    std::vector<std::vector<int32_t>> framesPerBatch;
1846	    if (!runCodePredictorGenerationForFrame(/*activeBatchSize=*/1, std::vector<int32_t>{codecToken}, talkerLastBatched,
1847	            predictorSamplingParams, framesPerBatch, stream))
1848	    {
1849	        LOG_ERROR("CodePredictor generation failed at frame %d", frameIdx);
1850	        return false;
1851	    }
1852	
1853	    rvqCodes.push_back(std::move(framesPerBatch[0]));
1854	
1855	    // Per-batch view (batch 0) into mCodecHiddensBuffer for residual.
1856	    rt::Tensor codecHiddensView(mCodecHiddensBuffer.rawPointer(),
1857	        rt::Coords{1, mNumCodesPerFrame, mTalkerConfig.talkerHiddenSize}, rt::DeviceType::kGPU,
1858	        nvinfer1::DataType::kHALF);
1859	    if (!computeResidualConnection(
1860	            codecHiddensView, rvqCodes.back(), trailingPtr, frameIdx, mResidualEmbedBuffer, stream))
1861	    {
1862	        LOG_ERROR("Residual connection failed at frame %d", frameIdx);
1863	        return false;
1864	    }
1865	
1866	    check::check(mResidualEmbedBuffer.reshape({1, 1, mTalkerConfig.talkerHiddenSize}), "Tensor reshape failed");
1867	    check::check(mTalkerHiddenStatesBuffer.reshape({1, 1, mTalkerConfig.talkerHiddenSize}), "Tensor reshape failed");
1868	
1869	    if (!executeTalkerDecodingStep(mResidualEmbedBuffer, mTalkerLogits, mTalkerHiddenStatesBuffer, stream))
1870	    {
1871	        LOG_ERROR("Talker decoding step failed at frame %d", frameIdx);
1872	        return false;
1873	    }
1874	
1875	    kernel::invokeTalkerLogitAdjust(mSeenCodecTokensBuf, mTalkerLogits, mTalkerConfig.talkerVocabSize - 1024,
1876	        mTalkerConfig.talkerVocabSize, codecEosId, numSeenTokens, repetitionPenalty, stream);
1877	    trt_edgellm::topKtopPSamplingFromLogits(mTalkerLogits, mTalkerSelectedIndices, talkerSamplingParams,
1878	        mSamplingWorkspace, stream, 42, static_cast<uint64_t>(frameIdx + 1));
1879	    CUDA_CHECK(cudaMemcpyAsync(mHostSelectedTokenIds.rawPointer(), mTalkerSelectedIndices.rawPointer(), sizeof(int32_t),
1880	        cudaMemcpyDeviceToHost, stream));
1881	    CUDA_CHECK(cudaStreamSynchronize(stream));
1882	
1883	    if (seenTokenSet.insert(codecToken).second)
1884	    {
1885	        CUDA_CHECK(cudaMemcpyAsync(mSeenCodecTokensBuf.dataPointer<int32_t>() + numSeenTokens,
1886	            mTalkerSelectedIndices.rawPointer(), sizeof(int32_t), cudaMemcpyDeviceToDevice, stream));
1887	        ++numSeenTokens;
1888	    }
1889	
1890	    codecToken = mHostSelectedTokenIds.dataPointer<int32_t>()[0];
1891	    return true;
1892	}
