1894	bool Qwen3OmniTTSRuntime::runCodePredictorGenerationForFrame(int32_t activeBatchSize,
1895	    std::vector<int32_t> const& codecTokensPerBatch, rt::Tensor const& talkerLastHiddenBatched,
1896	    SamplingParams const& samplingParams, std::vector<std::vector<int32_t>>& outputCodesPerBatch, cudaStream_t stream)
1897	{
1898	    NVTX_SCOPED_RANGE(nvtx_range, "TalkerRunner::runCodePredictorGenerationForFrame", nvtx_colors::ORANGE);
1899	
1900	    int64_t const talkerH = mTalkerConfig.talkerHiddenSize;
1901	    int64_t const cpH = mTalkerConfig.codePredictorHiddenSize;
1902	    int32_t const codebookSize = mTalkerConfig.codebookSize;
1903	
1904	    check::check(activeBatchSize >= 1 && activeBatchSize <= mMaxBatchSize,
1905	        "runCodePredictorGenerationForFrame: activeBatchSize out of range");
1906	    check::check(static_cast<int32_t>(codecTokensPerBatch.size()) == activeBatchSize,
1907	        "codecTokensPerBatch.size() must equal activeBatchSize");
1908	    if (!mUseSmallToMtpProjection)
1909	    {
1910	        check::check(talkerH == cpH, "no-projection CP path requires talkerH == cpH");
1911	    }
1912	
1913	    // Helper: returns a [activeBatchSize, cpH] tensor view containing srcTalkerSpace2D projected
1914	    // into CP hidden space. When mUseSmallToMtpProjection is false (talkerH == cpH), the source
1915	    // view IS already the cp view — returned directly. Otherwise, invokeLinearLayer writes the
1916	    // projected output into projectScratch (which must be sized [activeBatchSize, cpH]).
1917	    auto projectToCpView = [&](rt::Tensor const& srcTalkerSpace2D, rt::Tensor& projectScratch) -> rt::Tensor const* {
1918	        if (!mUseSmallToMtpProjection)
1919	        {
1920	            return &srcTalkerSpace2D;
1921	        }
1922	        check::check(projectScratch.reshape({activeBatchSize, cpH}), "Tensor reshape failed");
1923	        kernel::invokeLinearLayer(srcTalkerSpace2D, mSmallToMtpWeight, mSmallToMtpBias, projectScratch, stream);
1924	        return &projectScratch;
1925	    };
1926	
1927	    // Output containers: code_0 (from Talker) + 1..mNumRvqLayers (from CP).
1928	    outputCodesPerBatch.assign(activeBatchSize, std::vector<int32_t>{});
1929	    for (int32_t b = 0; b < activeBatchSize; ++b)
1930	    {
1931	        outputCodesPerBatch[b].reserve(mNumCodesPerFrame);
1932	        outputCodesPerBatch[b].push_back(codecTokensPerBatch[b]);
1933	    }
1934	
1935	    // ---- Step 1: Batched lookup of code_0 embeddings (Talker codec_embedding, talkerH-dim) ----
1936	    check::check(mCodePredictorCodecIds.reshape({activeBatchSize, 1}), "Tensor reshape failed");
1937	    CUDA_CHECK(cudaMemcpyAsync(mCodePredictorCodecIds.rawPointer(), codecTokensPerBatch.data(),
1938	        activeBatchSize * sizeof(int32_t), cudaMemcpyHostToDevice, stream));
1939	    check::check(mRawCodecEmbed.reshape({activeBatchSize, 1, talkerH}), "Tensor reshape failed");
1940	    kernel::embeddingLookup(mCodePredictorCodecIds, mTalkerEmbeddingTable, std::nullopt, mRawCodecEmbed, stream);
1941	
1942	    // ---- Step 2: Build [activeBS, 2, cpH] prefill input — slot 0 = proj(talker_h), slot 1 = proj(code_0_embed)
1943	    check::check(mCodePredictorPrefillInput.reshape({activeBatchSize, 2, cpH}), "Tensor reshape failed");
1944	    {
1945	        TIME_STAGE(metrics::StageNames::kCODEPREDICTOR_PREFILL, stream);
1946	
1947	        // 2D views into the [activeBS, 1, talkerH] sources to feed projectToCpView.
1948	        rt::Tensor talkerInput2D(const_cast<__half*>(static_cast<__half const*>(talkerLastHiddenBatched.rawPointer())),
1949	            rt::Coords{activeBatchSize, talkerH}, rt::DeviceType::kGPU, nvinfer1::DataType::kHALF);
1950	        rt::Tensor rawCodec2D(mRawCodecEmbed.rawPointer(), rt::Coords{activeBatchSize, talkerH}, rt::DeviceType::kGPU,
1951	            nvinfer1::DataType::kHALF);
1952	
1953	        rt::Tensor const* talkerCpView = projectToCpView(talkerInput2D, mSmallToMtpProjectedHidden);
1954	        rt::Tensor const* codecCpView = projectToCpView(rawCodec2D, mCodePredictorCodecEmbed);
1955	
1956	        // Interleave the two per-batch [bs, cpH] tensors into [bs, 2, cpH] prefill input.
1957	        for (int32_t b = 0; b < activeBatchSize; ++b)
1958	        {
1959	            __half* dst = static_cast<__half*>(mCodePredictorPrefillInput.rawPointer()) + b * 2 * cpH;
1960	            __half const* talkerSrc = static_cast<__half const*>(talkerCpView->rawPointer()) + b * cpH;
1961	            __half const* codecSrc = static_cast<__half const*>(codecCpView->rawPointer()) + b * cpH;
1962	            CUDA_CHECK(cudaMemcpyAsync(dst, talkerSrc, cpH * sizeof(__half), cudaMemcpyDeviceToDevice, stream));
1963	            CUDA_CHECK(cudaMemcpyAsync(dst + cpH, codecSrc, cpH * sizeof(__half), cudaMemcpyDeviceToDevice, stream));
1964	        }
1965	
1966	        // ---- Step 3: CP prefill engine call (produces logits for code_1) ----
1967	        check::check(mCodePredictorHiddenStatesBuffer.reshape({activeBatchSize, 2, cpH}), "Tensor reshape failed");
1968	        rt::Tensor& logitsHead0 = mCodePredictorLogitsPerHead[0];
1969	        if (!executeCodePredictorPrefillStep(
1970	                mCodePredictorPrefillInput, /*lmHeadIdx=*/0, logitsHead0, mCodePredictorHiddenStatesBuffer, stream))
1971	        {
1972	            return false;
1973	        }
1974	
1975	        // ---- Step 4: Sample code_1 (batched) ----
1976	        check::check(logitsHead0.reshape({activeBatchSize, codebookSize}), "Tensor reshape failed");
1977	        check::check(mCodePredictorSelectedIndices.reshape({activeBatchSize, 1}), "Tensor reshape failed");
1978	        SamplingParams const perCallParams(
1979	            activeBatchSize, codebookSize, samplingParams.temperature, samplingParams.topK, samplingParams.topP);
1980	        trt_edgellm::topKtopPSamplingFromLogits(
1981	            logitsHead0, mCodePredictorSelectedIndices, perCallParams, mSamplingWorkspace, stream);
1982	        check::check(mHostSelectedCodeIds.reshape({activeBatchSize}), "Tensor reshape failed");
1983	        CUDA_CHECK(cudaMemcpyAsync(mHostSelectedCodeIds.rawPointer(), mCodePredictorSelectedIndices.rawPointer(),
1984	            activeBatchSize * sizeof(int32_t), cudaMemcpyDeviceToHost, stream));
1985	        CUDA_CHECK(cudaStreamSynchronize(stream));
1986	
1987	        int32_t* hostCodes = mHostSelectedCodeIds.dataPointer<int32_t>();
1988	        for (int32_t b = 0; b < activeBatchSize; ++b)
1989	        {
1990	            outputCodesPerBatch[b].push_back(hostCodes[b]); // code_1
1991	        }
1992	    } // end kCODEPREDICTOR_PREFILL scope
1993	
1994	    // ---- Step 5: Mid-RVQ codec hiddens buffer for residual.
1995	    // Layout: mCodecHiddensBuffer[maxBS, mNumCodesPerFrame, talkerH].
1996	    // Positions 0 and mNumRvqLayers are filled by computeResidualConnection (Talker embed lookup).
1997	    // Positions 1..mNumRvqLayers-1 are filled here from the per-step raw codec embedding.
1998	    check::check(mCodecHiddensBuffer.reshape({activeBatchSize, mNumCodesPerFrame, talkerH}), "Tensor reshape failed");
1999	
2000	    // ---- Step 6: Decode loop for codes 2 .. mNumRvqLayers (batched) ----
2001	    //
2002	    // Tokens flow GPU-only across the loop: each step's embeddingLookup reads
2003	    // the PREVIOUS step's sample directly from ``mCodePredictorSelectedIndices``
2004	    // (device tensor) instead of round-tripping through host memory.  Per-step
2005	    // sample is async-D2H'd into row ``step - 2`` of ``mHostGenCodeBuf`` on
2006	    // pinned host memory; one ``cudaStreamSynchronize`` at the end of the loop
2007	    // drains all 14 steps × activeBatchSize codes.
2008	    //
2009	    // CP has no EOS / no per-token streaming callback, so the host doesn't need
2010	    // any sample value during the inner loop — making this loop a strictly
2011	    // safer place to defer sync than the Thinker/Talker loops.  AR ordering is
2012	    // preserved by stream order: step k's topK kernel happens-before step k+1's
2013	    // embeddingLookup on the same CUDA stream.
2014	    //
2015	    // Entry condition: ``mCodePredictorSelectedIndices`` already holds code_1
2016	    // from the prefill block above (its topK wrote there), so step 2 reads it
2017	    // correctly.  See the prefill block for the post-sample state.
2018	    int32_t* const hostGenBuf = mHostGenCodeBuf.dataPointer<int32_t>();
2019	    int64_t const hostGenBufStride = mMaxBatchSize; // row stride of mHostGenCodeBuf
2020	    int32_t const numGenSteps = mNumRvqLayers - 1;
2021	    {
2022	        TIME_STAGE(metrics::StageNames::kCODEPREDICTOR_GENERATION, stream);
2023	        for (int32_t step = 2; step <= mNumRvqLayers; ++step)
2024	        {
2025	            int32_t const embedIdx = step - 2;  // step=2 → codec_embedding[0]
2026	            int32_t const lmHeadIdx = step - 1; // step=2 → lm_head[1]
2027	
2028	            // Lookup code_(step-1) for each batch from the PREVIOUS step's
2029	            // sampled-token device tensor — skip the host round-trip via
2030	            // outputCodesPerBatch.back() + H2D copy that the original
2031	            // implementation did, since outputCodesPerBatch isn't drained
2032	            // until end-of-loop under the deferred-sync scheme.
2033	            check::check(mCodePredictorSelectedIndices.reshape({activeBatchSize, 1}), "Tensor reshape failed");
2034	            check::check(mRawCodecEmbed.reshape({activeBatchSize, 1, talkerH}), "Tensor reshape failed");
2035	            kernel::embeddingLookup(mCodePredictorSelectedIndices, mCodePredictorEmbeddingTables[embedIdx],
2036	                std::nullopt, mRawCodecEmbed, stream);
2037	
2038	            // Save raw embedding to mCodecHiddensBuffer[b][step-1] for residual (matches PyTorch position mapping).
2039	            int32_t const savePos = step - 1; // 1..mNumRvqLayers-1
2040	            for (int32_t b = 0; b < activeBatchSize; ++b)
2041	            {
2042	                __half* dst = static_cast<__half*>(mCodecHiddensBuffer.rawPointer())
2043	                    + (b * mNumCodesPerFrame + savePos) * talkerH;
2044	                __half const* src = static_cast<__half const*>(mRawCodecEmbed.rawPointer()) + b * talkerH;
2045	                CUDA_CHECK(cudaMemcpyAsync(dst, src, talkerH * sizeof(__half), cudaMemcpyDeviceToDevice, stream));
2046	            }
2047	
2048	            // Project raw codec embed → mCodePredictorCodecEmbed [activeBS, 1, cpH].
2049	            rt::Tensor rawCodec2D(mRawCodecEmbed.rawPointer(), rt::Coords{activeBatchSize, talkerH},
2050	                rt::DeviceType::kGPU, nvinfer1::DataType::kHALF);
2051	            rt::Tensor const* projectedView = projectToCpView(rawCodec2D, mSmallToMtpProjectedHidden);
2052	
2053	            check::check(mCodePredictorCodecEmbed.reshape({activeBatchSize, 1, cpH}), "Tensor reshape failed");
2054	            for (int32_t b = 0; b < activeBatchSize; ++b)
2055	            {
2056	                __half* dst = static_cast<__half*>(mCodePredictorCodecEmbed.rawPointer()) + b * cpH;
2057	                __half const* src = static_cast<__half const*>(projectedView->rawPointer()) + b * cpH;
2058	                CUDA_CHECK(cudaMemcpyAsync(dst, src, cpH * sizeof(__half), cudaMemcpyDeviceToDevice, stream));
2059	            }
2060	
2061	            // CP decode engine call.
2062	            rt::Tensor& logitsForHead = mCodePredictorLogitsPerHead[lmHeadIdx];
2063	            check::check(mCodePredictorHiddenStatesBuffer.reshape({activeBatchSize, 1, cpH}), "Tensor reshape failed");
2064	            if (!executeCodePredictorDecodingStep(
2065	                    mCodePredictorCodecEmbed, lmHeadIdx, logitsForHead, mCodePredictorHiddenStatesBuffer, stream))
2066	            {
2067	                return false;
2068	            }
2069	
2070	            // Sample code_step.
2071	            check::check(logitsForHead.reshape({activeBatchSize, codebookSize}), "Tensor reshape failed");
2072	            SamplingParams const perCallParams(
2073	                activeBatchSize, codebookSize, samplingParams.temperature, samplingParams.topK, samplingParams.topP);
2074	            trt_edgellm::topKtopPSamplingFromLogits(
2075	                logitsForHead, mCodePredictorSelectedIndices, perCallParams, mSamplingWorkspace, stream);
2076	
2077	            // Async D2H to row (step - 2) × maxBS of pinned host buffer;
2078	            // deliberately NO cudaStreamSynchronize here — the value will be
2079	            // drained after the loop.  Pinned (cudaMallocHost) backing makes
2080	            // this truly async.
2081	            int32_t const rowIdx = step - 2;
2082	            CUDA_CHECK(
2083	                cudaMemcpyAsync(hostGenBuf + rowIdx * hostGenBufStride, mCodePredictorSelectedIndices.rawPointer(),
2084	                    activeBatchSize * sizeof(int32_t), cudaMemcpyDeviceToHost, stream));
2085	        }
2086	
2087	        // Single sync per frame: blocks until all numGenSteps × activeBatchSize
2088	        // D2H copies (and the sampling kernels they depend on) have completed.
2089	        CUDA_CHECK(cudaStreamSynchronize(stream));
2090	
2091	        for (int32_t row = 0; row < numGenSteps; ++row)
2092	        {
2093	            for (int32_t b = 0; b < activeBatchSize; ++b)
2094	            {
2095	                outputCodesPerBatch[b].push_back(hostGenBuf[row * hostGenBufStride + b]); // code_(row+2)
2096	            }
2097	        }
2098	    }
2099	
2100	    return true;
2101	}
