2103	bool Qwen3OmniTTSRuntime::computeResidualConnection(rt::Tensor const& codecHiddensThisBatch,
2104	    std::vector<int32_t> const& codes, rt::Tensor const* trailingTextHidden, int32_t generationStep,
2105	    rt::Tensor& outputResidual, cudaStream_t stream)
2106	{
2107	    NVTX_SCOPED_RANGE(nvtx_range, "TalkerRunner::computeResidualConnection", nvtx_colors::BLUE);
2108	
2109	    // PyTorch (modeling_qwen3_omni.py:3429-3434):
2110	    //   if generation_step < trailing_text_hidden.shape[1]:
2111	    //       inputs_embeds += trailing_text_hidden[:, generation_step]
2112	    //   else:
2113	    //       inputs_embeds += tts_pad_embed
2114	    //
2115	    // codecHiddensThisBatch: [1, mNumCodesPerFrame, talkerH] view into per-batch slot of mCodecHiddensBuffer.
2116	    // The kernel reads middle positions [1..mNumRvqLayers-1] (filled by CP decode loop) and
2117	    // fills positions 0 and mNumRvqLayers via Talker/CP embedding lookup using codes[0] / codes[last].
2118	
2119	    check::check(static_cast<int32_t>(codes.size()) == mNumCodesPerFrame,
2120	        "Expected " + std::to_string(mNumCodesPerFrame) + " codes, got " + std::to_string(codes.size()));
2121	
2122	    int64_t const hiddenSize = mTalkerConfig.talkerHiddenSize;
2123	    if (!outputResidual.reshape({1, 1, hiddenSize}))
2124	    {
2125	        check::check(
2126	            outputResidual.getShape() == rt::Coords{1, 1, hiddenSize}, "Non-owning residual tensor has wrong shape");
2127	    }
2128	
2129	    __half const* addend = mTtsPadEmbed.dataPointer<__half>();
2130	    if (trailingTextHidden != nullptr)
2131	    {
2132	        int64_t const trailingLen = trailingTextHidden->getShape()[0];
2133	        if (generationStep < trailingLen)
2134	        {
2135	            addend = static_cast<__half const*>(trailingTextHidden->rawPointer()) + generationStep * hiddenSize;
2136	        }
2137	    }
2138	
2139	    kernel::invokeResidualConnection(codecHiddensThisBatch, mTalkerEmbeddingTable,
2140	        mCodePredictorEmbeddingTables[mNumRvqLayers - 1], codes[0], codes[mNumRvqLayers], addend, outputResidual,
2141	        stream);
2142	
2143	    return true;
2144	}
2145	
2146	bool Qwen3OmniTTSRuntime::extractTalkerLastHidden(
2147	    rt::Tensor const& talkerHiddenStates, rt::Tensor& outputLastHidden, cudaStream_t stream)
2148	{
2149	    auto const& shape = talkerHiddenStates.getShape();
2150	    int32_t const numDims = shape.getNumDims();
2151	
2152	    if (numDims != 3)
2153	    {
2154	        LOG_ERROR("extractTalkerLastHidden: Expected 3D tensor [batchSize, seqLen, hiddenSize], got %dD", numDims);
2155	        return false;
2156	    }
2157	
2158	    int64_t const batchSize = shape[0];
2159	    int64_t const seqLen = shape[1];
2160	    int64_t const hiddenSize = shape[2];
2161	
2162	    // Owning tensors get reshaped; non-owning views must already have the right shape.
2163	    if (!outputLastHidden.reshape({batchSize, hiddenSize}))
2164	    {
2165	        check::check(outputLastHidden.getShape() == rt::Coords{batchSize, hiddenSize},
2166	            "extractTalkerLastHidden: non-owning output has wrong shape");
2167	    }
2168	
2169	    // Extract last token for each batch: output[b] = input[b, seqLen-1, :]
2170	    size_t const copySize = hiddenSize * sizeof(__half);
2171	    for (int64_t b = 0; b < batchSize; ++b)
2172	    {
2173	        size_t const srcOffset = (b * seqLen + seqLen - 1) * hiddenSize * sizeof(__half);
2174	        size_t const dstOffset = b * hiddenSize * sizeof(__half);
2175	        CUDA_CHECK(cudaMemcpyAsync(static_cast<char*>(outputLastHidden.rawPointer()) + dstOffset,
2176	            static_cast<char const*>(talkerHiddenStates.rawPointer()) + srcOffset, copySize, cudaMemcpyDeviceToDevice,
2177	            stream));
2178	    }
2179	
2180	    return true;
2181	}
