2196	// ═══════════════════════════════════════════════════════════════════════════
2197	//        Shared Decode Frame + Prefill Construction
2198	// ═══════════════════════════════════════════════════════════════════════════
2199	
2200	bool Qwen3OmniTTSRuntime::buildTalkerPrefillFromSegments(std::vector<int32_t> const& textTokenIds,
2201	    rt::Tensor const* prefillEmbedPtr, rt::Tensor const* prefillHiddenPtr, int32_t prefillLen,
2202	    rt::Tensor const& thinkerEmbedTable, int32_t speakerId, rt::Tensor& trailingTextHidden, int32_t& trailingCount,
2203	    int64_t& outSeqLen, cudaStream_t stream)
2204	{
2205	    int64_t const seqLen = static_cast<int64_t>(textTokenIds.size());
2206	    int64_t const thinkerHiddenSize = mTextEmbeddingTable.getShape()[1];
2207	    int64_t const hiddenSize = mTalkerConfig.talkerHiddenSize;
2208	
2209	    // Step 1: Build layer-0 embeddings in mThinkerEmbedBuffer
2210	    check::check(mThinkerEmbedBuffer.reshape({seqLen, thinkerHiddenSize}), "Tensor reshape failed");
2211	
2212	    if (prefillEmbedPtr != nullptr)
2213	    {
2214	        int32_t const copyLen = std::min(prefillLen, static_cast<int32_t>(seqLen));
2215	        size_t const prefillBytes = copyLen * thinkerHiddenSize * sizeof(__half);
2216	        CUDA_CHECK(cudaMemcpyAsync(mThinkerEmbedBuffer.rawPointer(), prefillEmbedPtr->rawPointer(), prefillBytes,
2217	            cudaMemcpyDeviceToDevice, stream));
2218	
2219	        int32_t const genLen = static_cast<int32_t>(seqLen) - copyLen;
2220	        if (genLen > 0)
2221	        {
2222	            check::check(mGpuTokenIdsBuffer.reshape({1, genLen}), "Tensor reshape failed");
2223	            CUDA_CHECK(cudaMemcpyAsync(mGpuTokenIdsBuffer.rawPointer(), textTokenIds.data() + copyLen,
2224	                genLen * sizeof(int32_t), cudaMemcpyHostToDevice, stream));
2225	            __half* genDst = static_cast<__half*>(mThinkerEmbedBuffer.rawPointer()) + copyLen * thinkerHiddenSize;
2226	            rt::Tensor genEmbedView(genDst, rt::Coords{1, static_cast<int64_t>(genLen), thinkerHiddenSize},
2227	                rt::DeviceType::kGPU, nvinfer1::DataType::kHALF);
2228	            kernel::embeddingLookup(mGpuTokenIdsBuffer, thinkerEmbedTable, std::nullopt, genEmbedView, stream);
2229	        }
2230	    }
2231	    else
2232	    {
2233	        check::check(mGpuTokenIdsBuffer.reshape({1, seqLen}), "Tensor reshape failed");
2234	        CUDA_CHECK(cudaMemcpyAsync(mGpuTokenIdsBuffer.rawPointer(), textTokenIds.data(), seqLen * sizeof(int32_t),
2235	            cudaMemcpyHostToDevice, stream));
2236	        rt::Tensor embedView(mThinkerEmbedBuffer.rawPointer(), rt::Coords{1, seqLen, thinkerHiddenSize},
2237	            rt::DeviceType::kGPU, nvinfer1::DataType::kHALF);
2238	        kernel::embeddingLookup(mGpuTokenIdsBuffer, thinkerEmbedTable, std::nullopt, embedView, stream);
2239	    }
2240	
2241	    // Step 2: Project ALL tokens through text_projection MLP
2242	    check::check(mProjectedBuffer.reshape({seqLen, hiddenSize}), "Tensor reshape failed");
2243	    check::check(mMLPWorkspace.reshape({seqLen, thinkerHiddenSize}), "Tensor reshape failed");
2244	    kernel::invokeTalkerMLP(mThinkerEmbedBuffer, mTextFC1Weight, mTextFC1Bias, mTextFC2Weight, mTextFC2Bias,
2245	        mProjectedBuffer, mMLPWorkspace, stream);
2246	
2247	    // Step 3: Parse segments by <|im_start|> positions
2248	    std::vector<SegmentInfo> segments;
2249	    for (int64_t i = 0; i < seqLen; ++i)
2250	    {
2251	        if (textTokenIds[i] == kImStartTokenId)
2252	        {
2253	            int32_t const roleId = (i + 1 < seqLen) ? textTokenIds[i + 1] : -1;
2254	            segments.push_back({i, seqLen, roleId});
2255	        }
2256	    }
2257	    for (size_t s = 0; s + 1 < segments.size(); ++s)
2258	    {
2259	        segments[s].endPos = segments[s + 1].startPos;
2260	    }
2261	
2262	    std::vector<size_t> userSegmentIndices;
2263	    int64_t assistantSegIdx = -1;
2264	    for (size_t s = 0; s < segments.size(); ++s)
2265	    {
2266	        if (segments[s].roleId == kSystemRoleId)
2267	            continue;
2268	        else if (segments[s].roleId == kUserRoleId)
2269	            userSegmentIndices.push_back(s);
2270	        else if (segments[s].roleId == kAssistantRoleId)
2271	            assistantSegIdx = static_cast<int64_t>(s);
2272	    }
2273	
2274	    if (assistantSegIdx < 0)
2275	    {
2276	        LOG_ERROR("buildTalkerPrefillFromSegments: could not find assistant segment");
2277	        return false;
2278	    }
2279	
2280	    // Step 4: Project multimodal tokens via hidden_projection using gather/scatter kernels
2281	    bool const hasHiddenProjection = (mHiddenFC1Weight.getShape().volume() > 0);
2282	    if (hasHiddenProjection && prefillHiddenPtr != nullptr)
2283	    {
2284	        std::vector<int32_t> mmPositions;
2285	        for (size_t sIdx : userSegmentIndices)
2286	        {
2287	            auto const& seg = segments[sIdx];
2288	            for (int64_t i = seg.startPos; i < seg.endPos && i < prefillLen; ++i)
2289	            {
2290	                int32_t const tid = textTokenIds[i];
2291	                if (tid == kAudioTokenId || tid == kImageTokenId || tid == kVideoTokenId)
2292	                    mmPositions.push_back(static_cast<int32_t>(i));
2293	            }
2294	        }
2295	
2296	        if (!mmPositions.empty())
2297	        {
2298	            int64_t const numMM = static_cast<int64_t>(mmPositions.size());
2299	            // Safe to repurpose mThinkerEmbedBuffer here: step 1 filled it with full-sequence
2300	            // layer-0 embeddings, but those have already been projected into mTalkerInputEmbeds
2301	            // by step 2's invokeTalkerMLP call. The reshape below overwrites that data, which is
2302	            // intentional — we only need it as scratch for the gather/MLP/scatter chain.
2303	            check::check(mThinkerEmbedBuffer.reshape({numMM, thinkerHiddenSize}), "Tensor reshape failed");
2304	            check::check(mMLPWorkspace.reshape({numMM, thinkerHiddenSize}), "Tensor reshape failed");
2305	            check::check(mTalkerInputEmbeds.reshape({numMM, hiddenSize}), "Tensor reshape failed");
2306	
2307	            // Upload indices and use vectorized gather kernel instead of per-row cudaMemcpy
2308	            check::check(mGatherIndicesBuffer.reshape({numMM}), "Tensor reshape failed");
2309	            CUDA_CHECK(cudaMemcpyAsync(mGatherIndicesBuffer.rawPointer(), mmPositions.data(), numMM * sizeof(int32_t),
2310	                cudaMemcpyHostToDevice, stream));
2311	
2312	            rt::Tensor hiddenSource(const_cast<void*>(prefillHiddenPtr->rawPointer()),
2313	                rt::Coords{static_cast<int64_t>(prefillLen), thinkerHiddenSize}, rt::DeviceType::kGPU,
2314	                nvinfer1::DataType::kHALF);
2315	            kernel::invokeGather(hiddenSource, mGatherIndicesBuffer, mThinkerEmbedBuffer, stream);
2316	
2317	            kernel::invokeTalkerMLP(mThinkerEmbedBuffer, mHiddenFC1Weight, mHiddenFC1Bias, mHiddenFC2Weight,
2318	                mHiddenFC2Bias, mTalkerInputEmbeds, mMLPWorkspace, stream);
2319	
2320	            // Scatter projected multimodal embeddings back into mProjectedBuffer
2321	            kernel::invokeScatter(mTalkerInputEmbeds, mGatherIndicesBuffer, mProjectedBuffer, stream);
2322	        }
2323	    }
2324	    else if (!hasHiddenProjection || prefillHiddenPtr == nullptr)
2325	    {
2326	        // Zero out multimodal rows as fallback
2327	        for (size_t sIdx : userSegmentIndices)
2328	        {
2329	            auto const& seg = segments[sIdx];
2330	            for (int64_t i = seg.startPos; i < seg.endPos; ++i)
2331	            {
2332	                int32_t const tid = textTokenIds[i];
2333	                if (tid == kAudioTokenId || tid == kImageTokenId || tid == kVideoTokenId)
2334	                {
2335	                    __half* rowPtr = static_cast<__half*>(mProjectedBuffer.rawPointer()) + i * hiddenSize;
2336	                    CUDA_CHECK(cudaMemsetAsync(rowPtr, 0, hiddenSize * sizeof(__half), stream));
2337	                }
2338	            }
2339	        }
2340	    }
2341	
2342	    // Step 5: Build Talker prefill input — user segments + restructured assistant preamble
2343	    auto const& assistantSeg = segments[assistantSegIdx];
2344	    constexpr int32_t kAssistantRestructuredLen = kNonStreamingPrefixRows + 1;
2345	    constexpr int32_t kAssistantTrailingOffset = kAssistantPrefixLen + 1;
2346	
2347	    int64_t userTotalLen = 0;
2348	    for (size_t sIdx : userSegmentIndices)
2349	        userTotalLen += (segments[sIdx].endPos - segments[sIdx].startPos);
2350	
2351	    outSeqLen = userTotalLen + kAssistantRestructuredLen;
2352	    check::check(mTalkerInputEmbeds.reshape({outSeqLen, hiddenSize}), "Tensor reshape failed");
2353	    CUDA_CHECK(cudaMemsetAsync(mTalkerInputEmbeds.rawPointer(), 0, outSeqLen * hiddenSize * sizeof(__half), stream));
2354	
2355	    int64_t outOffset = 0;
2356	    for (size_t sIdx : userSegmentIndices)
2357	    {
2358	        auto const& seg = segments[sIdx];
2359	        int64_t const segLen = seg.endPos - seg.startPos;
2360	        __half const* src = static_cast<__half const*>(mProjectedBuffer.rawPointer()) + seg.startPos * hiddenSize;
2361	        __half* dst = static_cast<__half*>(mTalkerInputEmbeds.rawPointer()) + outOffset * hiddenSize;
2362	        CUDA_CHECK(cudaMemcpyAsync(dst, src, segLen * hiddenSize * sizeof(__half), cudaMemcpyDeviceToDevice, stream));
2363	        outOffset += segLen;
2364	    }
2365	
2366	    // Build restructured assistant preamble via invokeAssistantPreamble
2367	    {
2368	        __half const* const assistantProjPtr
2369	            = static_cast<__half const*>(mProjectedBuffer.rawPointer()) + assistantSeg.startPos * hiddenSize;
2370	        constexpr int64_t kPreambleFullLen = kNonStreamingPrefixRows + 1 + 2;
2371	        int64_t const requiredCapacity = (outSeqLen + kPreambleFullLen) * hiddenSize * sizeof(__half);
2372	        check::check(static_cast<int64_t>(mTalkerInputEmbeds.getMemoryCapacity()) >= requiredCapacity,
2373	            "mTalkerInputEmbeds too small for preamble scratch");
2374	        __half* const scratchPtr = static_cast<__half*>(mTalkerInputEmbeds.rawPointer()) + outSeqLen * hiddenSize;
2375	        rt::Tensor preambleScratch(
2376	            scratchPtr, rt::Coords{kPreambleFullLen, hiddenSize}, rt::DeviceType::kGPU, nvinfer1::DataType::kHALF);
2377	
2378	        int64_t const assistantInputLen = kAssistantPrefixLen + 1;
2379	        rt::Tensor assistantSlice(const_cast<__half*>(assistantProjPtr), rt::Coords{assistantInputLen, hiddenSize},
2380	            rt::DeviceType::kGPU, nvinfer1::DataType::kHALF);
2381	
2382	        kernel::invokeAssistantPreamble(assistantSlice, mTtsPadEmbed, mTtsBosEmbed, mTtsEosEmbed, mTalkerEmbeddingTable,
2383	            mTalkerConfig.codecNothinkId, mTalkerConfig.codecThinkBosId, mTalkerConfig.codecThinkEosId, speakerId,
2384	            mTalkerConfig.codecPadId, mTalkerConfig.codecBosId, 1, preambleScratch, stream);
2385	
2386	        __half* const aOut = static_cast<__half*>(mTalkerInputEmbeds.rawPointer()) + userTotalLen * hiddenSize;
2387	        CUDA_CHECK(cudaMemcpyAsync(aOut, scratchPtr, kAssistantRestructuredLen * hiddenSize * sizeof(__half),
2388	            cudaMemcpyDeviceToDevice, stream));
2389	    }
2390	
2391	    // Step 6: Fill trailing text hidden states
2392	    int64_t const assistantSegLen = assistantSeg.endPos - assistantSeg.startPos;
2393	    trailingCount = std::min(static_cast<int32_t>(assistantSegLen - kAssistantTrailingOffset),
2394	        static_cast<int32_t>(trailingTextHidden.getShape()[0]) - 1);
2395	    if (trailingCount > 0)
2396	    {
2397	        __half const* trailSrc = static_cast<__half const*>(mProjectedBuffer.rawPointer())
2398	            + (assistantSeg.startPos + kAssistantTrailingOffset) * hiddenSize;
2399	        CUDA_CHECK(cudaMemcpyAsync(trailingTextHidden.rawPointer(), trailSrc,
2400	            trailingCount * hiddenSize * sizeof(__half), cudaMemcpyDeviceToDevice, stream));
2401	    }
2402	
2403	    LOG_INFO("buildTalkerPrefillFromSegments: outSeqLen=%ld (user=%ld + assistant=%d), trailing=%d", outSeqLen,
2404	        userTotalLen, kAssistantRestructuredLen, trailingCount);
2405	    return true;
2406	}
