2409	//        Incremental Trailing Hidden Helpers (for streaming)
2410	// ═══════════════════════════════════════════════════════════════════════════
2411	
2412	void Qwen3OmniTTSRuntime::appendTrailingToken(int32_t tokenId, rt::Tensor const& thinkerEmbedTable,
2413	    rt::Tensor& trailingTextHidden, int32_t trailingIdx, cudaStream_t stream)
2414	{
2415	    int64_t const talkerHiddenSize = mTalkerConfig.talkerHiddenSize;
2416	
2417	    // Upload token ID (reuse pre-allocated GPU buffer)
2418	    CUDA_CHECK(
2419	        cudaMemcpyAsync(mStreamingTokenId.rawPointer(), &tokenId, sizeof(int32_t), cudaMemcpyHostToDevice, stream));
2420	
2421	    // embed_tokens(tokenId) → mStreamingTokenEmbed [1, thinkerH]
2422	    // embeddingLookup expects [1, 1, H] output; mStreamingTokenEmbed is [1, H] — same memory, just reshape for kernel
2423	    rt::Tensor embedView(mStreamingTokenEmbed.rawPointer(), rt::Coords{1, 1, mTalkerConfig.thinkerHiddenSize},
2424	        rt::DeviceType::kGPU, nvinfer1::DataType::kHALF);
2425	    kernel::embeddingLookup(mStreamingTokenId, thinkerEmbedTable, std::nullopt, embedView, stream);
2426	
2427	    // text_projection: mStreamingTokenEmbed [1, thinkerH] → mStreamingProjOut [1, talkerH]
2428	    kernel::invokeTalkerMLP(mStreamingTokenEmbed, mTextFC1Weight, mTextFC1Bias, mTextFC2Weight, mTextFC2Bias,
2429	        mStreamingProjOut, mStreamingMlpWork, stream);
2430	
2431	    // Write to trailingTextHidden[trailingIdx]
2432	    __half* dst = static_cast<__half*>(trailingTextHidden.rawPointer()) + trailingIdx * talkerHiddenSize;
2433	    CUDA_CHECK(cudaMemcpyAsync(
2434	        dst, mStreamingProjOut.rawPointer(), talkerHiddenSize * sizeof(__half), cudaMemcpyDeviceToDevice, stream));
2435	}
