2437	void Qwen3OmniTTSRuntime::finalizeTrailing(rt::Tensor& trailingTextHidden, int32_t trailingIdx, cudaStream_t stream)
2438	{
2439	    int64_t const talkerHiddenSize = mTalkerConfig.talkerHiddenSize;
2440	    __half* dst = static_cast<__half*>(trailingTextHidden.rawPointer()) + trailingIdx * talkerHiddenSize;
2441	    CUDA_CHECK(cudaMemcpyAsync(
2442	        dst, mTtsEosEmbed.rawPointer(), talkerHiddenSize * sizeof(__half), cudaMemcpyDeviceToDevice, stream));
2443	}
