2445	// ═══════════════════════════════════════════════════════════════════════════
2446	//        Thinker-Talker Streaming Pipeline (single CUDA stream)
2447	// ═══════════════════════════════════════════════════════════════════════════
2448	
2449	bool Qwen3OmniTTSRuntime::handleStreamingGeneration(LLMInferenceRuntime& thinkerRuntime,
2450	    LLMGenerationRequest& thinkerRequest, LLMGenerationResponse& thinkerResponse,
2451	    ThinkerTalkerStreamingConfig const& streamingConfig, OmniGenerationRequest const& omniBaseRequest,
2452	    TalkerGenerationResponse& talkerResponse, cudaStream_t stream)
2453	{
2454	    NVTX_SCOPED_RANGE(nvtx_range, "TTSRuntime::handleStreamingGeneration", nvtx_colors::PURPLE);
2455	
2456	    LOG_INFO(
2457	        "Starting Thinker-Talker streaming pipeline (prefillThreshold=%d)", streamingConfig.talkerPrefillThreshold);
2458	
2459	    talkerResponse.batchRvqCodes.clear();
2460	    talkerResponse.numFramesPerSample.clear();
2461	    talkerResponse.success = false;
2462	
2463	    float const talkerTemperature = (omniBaseRequest.talkerTemperature > 0) ? omniBaseRequest.talkerTemperature : 0.9f;
2464	    int32_t const talkerTopK = (omniBaseRequest.talkerTopK > 0) ? omniBaseRequest.talkerTopK : 50;
2465	    float const talkerTopP = (omniBaseRequest.talkerTopP > 0) ? omniBaseRequest.talkerTopP : 1.0f;
2466	    float const repetitionPenalty = omniBaseRequest.repetitionPenalty;
2467	
2468	    SamplingParams talkerSamplingParams(1, mTalkerConfig.talkerVocabSize, talkerTemperature, talkerTopK, talkerTopP);
2469	    SamplingParams predictorSamplingParams(
2470	        1, mTalkerConfig.codebookSize, kCPSamplingTemperature, kCPSamplingTopK, kCPSamplingTopP);
2471	
2472	    int32_t const codecEosId = mTalkerConfig.codecEosId;
2473	    int32_t numSeenTokens = 0;
2474	    std::unordered_set<int32_t> seenTokenSet;
2475	
2476	    struct StreamingState
2477	    {
2478	        std::vector<int32_t> assistantTokens;
2479	        bool thinkerFinished{false};
2480	        bool talkerPrefillDone{false};
2481	        bool talkerError{false};
2482	        int32_t talkerFrames{0};
2483	        int32_t codecToken{-1};
2484	        int32_t trailingIdx{0};
2485	        std::vector<std::vector<int32_t>> rvqCodes;
2486	        std::vector<int32_t> inputIds;
2487	    };
2488	    StreamingState state;
2489	    state.rvqCodes.reserve(omniBaseRequest.maxAudioLength);
2490	
2491	    // Shared chunk emitter — same accumulator used by runTalkerGenerationLoop's TTS streaming path.
2492	    ChunkEmitter emitter{streamingConfig.codecChunkFrames, streamingConfig.onAudioChunkReady, {}};
2493	
2494	    int64_t const hiddenSize = mTalkerConfig.talkerHiddenSize;
2495	    int64_t const trailingStride = mTalkerConfig.maxSeqLen + 1;
2496	    int32_t const maxTrailingLen = static_cast<int32_t>(trailingStride);
2497	
2498	    // Streaming uses batch slot 0 of the trailing buffer
2499	    size_t const slot0Bytes = trailingStride * hiddenSize * sizeof(__half);
2500	    CUDA_CHECK(cudaMemsetAsync(mStreamingTrailingHidden.rawPointer(), 0, slot0Bytes, stream));
2501	
2502	    rt::Tensor const& thinkerEmbedTable = thinkerRuntime.getEmbeddingTable();
2503	
2504	    int32_t speakerId = mTalkerConfig.defaultSpeakerId;
2505	    if (omniBaseRequest.speakerId >= 0)
2506	    {
2507	        speakerId = omniBaseRequest.speakerId;
2508	    }
2509	    else if (!omniBaseRequest.speakerName.empty())
2510	    {
2511	        speakerId = getSpeakerIdByName(omniBaseRequest.speakerName);
2512	    }
2513	
2514	    int32_t const prefillThreshold = streamingConfig.talkerPrefillThreshold;
2515	    int32_t const maxAudioLength = omniBaseRequest.maxAudioLength;
2516	
2517	    // Reset reuse lengths to batch=1 for streaming (per-batch independent Talker)
2518	    check::check(mHostReuseKVCacheLengths.reshape({1}), "Tensor reshape failed");
2519	    int32_t* reuseData = mHostReuseKVCacheLengths.dataPointer<int32_t>();
2520	    reuseData[0] = 0;
2521	
2522	    auto makeTrailingView = [&]() -> rt::Tensor {
2523	        return rt::Tensor(mStreamingTrailingHidden.rawPointer(),
2524	            rt::Coords{static_cast<int64_t>(state.trailingIdx), hiddenSize}, rt::DeviceType::kGPU,
2525	            nvinfer1::DataType::kHALF);
2526	    };
2527	
2528	    // ===== Per-token callback for the Thinker decode loop =====
2529	    // SAFETY: This lambda captures stack-local state by reference. It is ONLY safe because
2530	    // thinkerRuntime.handleRequest() invokes the callback synchronously on the same thread
2531	    // (inside cudaStreamSynchronize in the decode loop). Never call this callback asynchronously.
2532	    auto userCallback = thinkerRequest.onTokenGenerated;
2533	
2534	    thinkerRequest.onTokenGenerated = [&, userCallback](TokenCallbackInfo const& info) {
2535	        if (userCallback.has_value())
2536	        {
2537	            userCallback.value()(info);
2538	        }
2539	        if (info.batchIdx != 0 || state.talkerError)
2540	        {
2541	            return;
2542	        }
2543	
2544	        state.assistantTokens.push_back(info.tokenId);
2545	        state.thinkerFinished = info.isFinished;
2546	
2547	        int32_t const numAssistantTokens = static_cast<int32_t>(state.assistantTokens.size());
2548	
2549	        if (!state.talkerPrefillDone && numAssistantTokens >= prefillThreshold)
2550	        {
2551	            LOG_INFO("Thinker produced %d assistant tokens, triggering Talker prefill", numAssistantTokens);
2552	
2553	            // Reset KV caches
2554	            auto& talkerCacheManager = *mTalkerSharedRes->cacheManagers[0];
2555	            auto& cpCacheManager = *mCodePredictorSharedRes->cacheManagers[0];
2556	            talkerCacheManager.resetForNewSequences(mHostReuseKVCacheLengths, stream);
2557	            cpCacheManager.resetForNewSequences(mHostReuseKVCacheLengths, stream);
2558	            {
2559	                auto& talkerKVManager = talkerCacheManager.getKVCacheManager();
2560	                for (int32_t i = 0; i < talkerKVManager.numLayers(); ++i)
2561	                {
2562	                    rt::Tensor& layerKV = talkerKVManager.getCombinedKVCache(i);
2563	                    CUDA_CHECK(cudaMemsetAsync(layerKV.rawPointer(), 0, layerKV.getMemoryCapacity(), stream));
2564	                }
2565	                auto& cpKVManager = cpCacheManager.getKVCacheManager();
2566	                for (int32_t i = 0; i < cpKVManager.numLayers(); ++i)
2567	                {
2568	                    rt::Tensor& layerKV = cpKVManager.getCombinedKVCache(i);
2569	                    CUDA_CHECK(cudaMemsetAsync(layerKV.rawPointer(), 0, layerKV.getMemoryCapacity(), stream));
2570	                }
2571	            }
2572	
2573	            // Build combined token IDs — fetch Thinker input IDs from the runtime portal.
2574	            auto const& thinkerInputs = thinkerRuntime.getBaseModelInputTokenIds();
2575	            auto& textTokenIds = state.inputIds;
2576	            if (textTokenIds.empty() && !thinkerInputs.empty())
2577	            {
2578	                textTokenIds = thinkerInputs[0];
2579	            }
2580	            textTokenIds.insert(textTokenIds.end(), state.assistantTokens.begin(), state.assistantTokens.end());
2581	
2582	            // Use buildTalkerPrefillFromSegments for segment parsing, MLP projection, and prefill assembly
2583	            auto prefillEmbedPtr = thinkerRuntime.getBaseModelHiddenStates(0);
2584	            auto prefillHiddenPtr = thinkerRuntime.getBaseModelHiddenStates(thinkerRequest.acceptHiddenLayer);
2585	            int32_t const prefillLen = thinkerRuntime.getBaseModelPrefillLength();
2586	
2587	            int64_t outSeqLen = 0;
2588	            if (!buildTalkerPrefillFromSegments(textTokenIds, prefillEmbedPtr, prefillHiddenPtr, prefillLen,
2589	                    thinkerEmbedTable, speakerId, mStreamingTrailingHidden, state.trailingIdx, outSeqLen, stream))
2590	            {
2591	                state.talkerError = true;
2592	                return;
2593	            }
2594	
2595	            // Talker prefill
2596	            check::check(mTalkerInputEmbeds.reshape({1, outSeqLen, hiddenSize}), "Tensor reshape failed");
2597	            check::check(mTalkerHiddenStatesBuffer.reshape({1, outSeqLen, mTalkerConfig.talkerHiddenSize}),
2598	                "Tensor reshape failed");
2599	
2600	            {
2601	                TIME_STAGE(metrics::StageNames::kTALKER_PREFILL, stream);
