45	struct ParsedInput
46	{
47	    // One entry per request; each entry is the list of messages for that request.
48	    std::vector<std::vector<Message>> requests;
49	    // Per-request speaker name (parallel to requests). Falls back to top-level "speaker" default.
50	    std::vector<std::string> requestSpeakers;
