63	ParsedInput parseInputFile(std::filesystem::path const& inputFilePath, int32_t batchSizeOverride = -1)
64	{
65	    ParsedInput result;
66	
67	    Json inputData;
68	    std::ifstream inputFileStream(inputFilePath);
69	    check::check(inputFileStream.is_open(), "Failed to open input file: " + inputFilePath.string());
70	    try
71	    {
72	        inputData = Json::parse(inputFileStream);
73	    }
74	    catch (Json::parse_error const& e)
75	    {
76	        throw std::runtime_error(
77	            format::fmtstr("Failed to parse input file %s: %s", inputFilePath.string().c_str(), e.what()));
78	    }
79	
80	    int batchSize = (batchSizeOverride != -1) ? batchSizeOverride : inputData.value("batch_size", 1);
81	    check::check(batchSize > 0, format::fmtstr("Invalid batch_size: %d", batchSize));
82	    check::check(batchSize <= limits::security::kReasonableMaxBatchSize,
83	        format::fmtstr("batch_size %d exceeds limit %d", batchSize, limits::security::kReasonableMaxBatchSize));
84	    result.batchSize = batchSize;
85	
86	    result.applyChatTemplate = inputData.value("apply_chat_template", true);
87	    result.addGenerationPrompt = inputData.value("add_generation_prompt", true);
88	    result.enableThinking = inputData.value("enable_thinking", false);
89	    result.talkerTemperature = inputData.value("talker_temperature", 0.9f);
90	    result.talkerTopK = inputData.value("talker_top_k", 50);
91	    result.talkerTopP = inputData.value("talker_top_p", 1.0f);
92	    result.repetitionPenalty = inputData.value("repetition_penalty", 1.05f);
93	    result.speakerName = inputData.value("speaker", "");
94	    result.maxAudioLength = inputData.value("max_audio_length", 4096);
95	
96	    check::check(
97	        inputData.contains("requests") && inputData["requests"].is_array(), "'requests' array not found in input file");
98	
99	    auto const& requestsArray = inputData["requests"];
100	    size_t const numRequests = requestsArray.size();
101	
102	    for (size_t i = 0; i < numRequests; ++i)
103	    {
104	        auto const& requestItem = requestsArray[i];
105	        check::check(requestItem.contains("messages") && requestItem["messages"].is_array(),
106	            "Each request must contain a 'messages' array");
107	
108	        std::string requestSpeaker = requestItem.value("speaker", result.speakerName);
109	
110	        auto const& messagesArray = requestItem["messages"];
111	        check::check(messagesArray.size() <= limits::security::kMaxMessagesPerRequest,
112	            format::fmtstr("Too many messages in request %zu", i));
113	
114	        std::vector<Message> messages;
115	        for (auto const& messageJson : messagesArray)
116	        {
117	            check::check(messageJson.contains("role") && messageJson.contains("content"),
118	                "Each message must have 'role' and 'content' fields");
119	
120	            Message msg;
121	            msg.role = messageJson["role"].get<std::string>();
122	
123	            auto const& contentJson = messageJson["content"];
124	            Message::MessageContent mc;
125	            mc.type = "text";
126	            if (contentJson.is_string())
127	            {
128	                mc.content = contentJson.get<std::string>();
129	            }
130	            else if (contentJson.is_array())
131	            {
132	                for (auto const& item : contentJson)
133	                {
134	                    check::check(item.contains("type") && item["type"] == "text", "Only 'text' content is supported");
135	                    mc.content += item["text"].get<std::string>();
136	                }
137	            }
138	            else
139	            {
140	                throw std::runtime_error("Message content must be a string or array");
141	            }
142	            check::check(mc.content.size() <= limits::security::kMaxMessageContentSizeBytes,
143	                format::fmtstr("Message content too large: %zu bytes", mc.content.size()));
144	
145	            msg.contents.push_back(std::move(mc));
146	            messages.push_back(std::move(msg));
147	        }
148	        result.requests.push_back(std::move(messages));
149	        result.requestSpeakers.push_back(std::move(requestSpeaker));
150	    }
151	
152	    return result;
153	}
