215	bool parseArgs(Qwen3TTSInferenceArgs& args, int argc, char* argv[])
216	{
217	    static struct option inferenceOptions[] = {{"help", no_argument, 0, Qwen3TTSOptionId::HELP},
218	        {"inputFile", required_argument, 0, Qwen3TTSOptionId::INPUT_FILE},
219	        {"talkerEngineDir", required_argument, 0, Qwen3TTSOptionId::TALKER_ENGINE_DIR},
220	        {"code2wavEngineDir", required_argument, 0, Qwen3TTSOptionId::CODE2WAV_ENGINE_DIR},
221	        {"tokenizerDir", required_argument, 0, Qwen3TTSOptionId::TOKENIZER_DIR},
222	        {"outputFile", required_argument, 0, Qwen3TTSOptionId::OUTPUT_FILE},
223	        {"outputAudioDir", required_argument, 0, Qwen3TTSOptionId::OUTPUT_AUDIO_DIR},
224	        {"debug", no_argument, 0, Qwen3TTSOptionId::DEBUG},
225	        {"dumpProfile", no_argument, 0, Qwen3TTSOptionId::DUMP_PROFILE},
226	        {"profileOutputFile", required_argument, 0, Qwen3TTSOptionId::PROFILE_OUTPUT_FILE},
227	        {"dumpOutput", no_argument, 0, Qwen3TTSOptionId::DUMP_OUTPUT},
228	        {"batchSize", required_argument, 0, Qwen3TTSOptionId::BATCH_SIZE},
229	        {"streaming", no_argument, 0, Qwen3TTSOptionId::STREAMING},
230	        {"chunkFrames", required_argument, 0, Qwen3TTSOptionId::CHUNK_FRAMES}, {0, 0, 0, 0}};
231	
232	    int opt;
233	    while ((opt = getopt_long(argc, argv, "", inferenceOptions, nullptr)) != -1)
234	    {
235	        switch (opt)
236	        {
237	        case Qwen3TTSOptionId::HELP: args.help = true; return true;
238	        case Qwen3TTSOptionId::INPUT_FILE: args.inputFile = optarg; break;
239	        case Qwen3TTSOptionId::TALKER_ENGINE_DIR: args.talkerEngineDir = optarg; break;
240	        case Qwen3TTSOptionId::CODE2WAV_ENGINE_DIR: args.code2wavEngineDir = optarg; break;
241	        case Qwen3TTSOptionId::TOKENIZER_DIR: args.tokenizerDir = optarg; break;
242	        case Qwen3TTSOptionId::OUTPUT_FILE: args.outputFile = optarg; break;
243	        case Qwen3TTSOptionId::OUTPUT_AUDIO_DIR: args.outputAudioDir = optarg; break;
244	        case Qwen3TTSOptionId::DEBUG: args.debug = true; break;
245	        case Qwen3TTSOptionId::DUMP_PROFILE: args.dumpProfile = true; break;
246	        case Qwen3TTSOptionId::PROFILE_OUTPUT_FILE: args.profileOutputFile = optarg; break;
247	        case Qwen3TTSOptionId::DUMP_OUTPUT: args.dumpOutput = true; break;
248	        case Qwen3TTSOptionId::BATCH_SIZE:
249	            try
250	            {
251	                args.batchSize = std::stoi(optarg);
252	                if (args.batchSize <= 0)
253	                {
254	                    LOG_ERROR("batchSize must be positive, got: %s", optarg);
255	                    return false;
256	                }
257	            }
258	            catch (std::exception const&)
259	            {
260	                LOG_ERROR("Invalid batchSize value: %s", optarg);
261	                return false;
262	            }
263	            break;
264	        case Qwen3TTSOptionId::STREAMING: args.streaming = true; break;
265	        case Qwen3TTSOptionId::CHUNK_FRAMES:
266	            try
267	            {
268	                args.chunkFrames = std::stoi(optarg);
269	                if (args.chunkFrames <= 0)
270	                {
271	                    LOG_ERROR("chunkFrames must be positive, got: %s", optarg);
272	                    return false;
273	                }
274	            }
275	            catch (std::exception const&)
276	            {
277	                LOG_ERROR("Invalid chunkFrames value: %s", optarg);
278	                return false;
279	            }
280	            break;
281	        default: LOG_ERROR("Unknown option: %c", opt); return false;
282	        }
283	    }
284	
285	    if (!args.help)
286	    {
287	        if (args.inputFile.empty())
288	        {
289	            LOG_ERROR("--inputFile is required");
290	            return false;
291	        }
292	        if (args.talkerEngineDir.empty())
293	        {
294	            LOG_ERROR("--talkerEngineDir is required");
295	            return false;
296	        }
297	        if (args.streaming && args.chunkFrames <= 0)
298	        {
299	            LOG_ERROR("--chunkFrames=<N> is required when --streaming is set");
300	            return false;
301	        }
302	    }
303	
304	    return true;
305	}
