307	int main(int argc, char** argv)
308	{
309	    Qwen3TTSInferenceArgs args;
310	    if (!parseArgs(args, argc, argv))
311	    {
312	        printUsage(argv[0]);
313	        return EXIT_FAILURE;
314	    }
315	    if (args.help)
316	    {
317	        printUsage(argv[0]);
318	        return EXIT_SUCCESS;
319	    }
320	
321	    gLogger.setLevel(args.debug ? nvinfer1::ILogger::Severity::kVERBOSE : nvinfer1::ILogger::Severity::kINFO);
322	    LOG_INFO("=== Qwen3-TTS Inference ===");
323	
324	    auto pluginHandles = loadEdgellmPluginLib();
325	
326	    LOG_INFO("Talker Engine:  %s", args.talkerEngineDir.c_str());
327	    if (!args.code2wavEngineDir.empty())
328	    {
329	        LOG_INFO("Code2Wav Engine: %s", args.code2wavEngineDir.c_str());
330	    }
331	    LOG_INFO("Input File:     %s", args.inputFile.c_str());
332	
333	    cudaStream_t stream;
334	    CUDA_CHECK(cudaStreamCreateWithFlags(&stream, cudaStreamNonBlocking));
335	
336	    // Initialize TTS Runtime (loads tokenizer, engines, and weights internally)
337	    std::unique_ptr<rt::Qwen3OmniTTSRuntime> ttsRuntime;
338	    try
339	    {
340	        std::filesystem::path const codePredictorDir
341	            = std::filesystem::path(args.talkerEngineDir).parent_path() / "code_predictor";
342	        ttsRuntime = std::make_unique<rt::Qwen3OmniTTSRuntime>(
343	            args.talkerEngineDir, codePredictorDir.string(), args.tokenizerDir, stream);
344	        LOG_INFO("TTS runtime initialized");
345	    }
346	    catch (std::exception const& e)
347	    {
348	        LOG_ERROR("Failed to initialize TTS Runtime: %s", e.what());
349	        return EXIT_FAILURE;
350	    }
351	
352	    // Initialize Code2Wav Runner (scoped block limits lifetime of code2wavDir)
353	    std::unique_ptr<Code2WavRunner> code2wavRunner;
354	    std::filesystem::path const code2wavDir = args.code2wavEngineDir.empty()
355	        ? std::filesystem::path(args.talkerEngineDir).parent_path() / "code2wav"
356	        : std::filesystem::path(args.code2wavEngineDir);
357	
358	    if (std::filesystem::exists(code2wavDir))
359	    {
360	        LOG_INFO("Initializing Code2Wav Runner from %s...", code2wavDir.string().c_str());
361	        try
362	        {
363	            code2wavRunner = std::make_unique<Code2WavRunner>(code2wavDir.string(), stream);
364	            LOG_INFO("Code2Wav Runner initialized");
365	        }
366	        catch (std::exception const& e)
367	        {
368	            LOG_WARNING("Failed to initialize Code2Wav: %s. Will output RVQ codes only.", e.what());
369	        }
370	    }
371	    else
372	    {
373	        LOG_INFO("Code2Wav engine not found at %s. Will output RVQ codes only.", code2wavDir.string().c_str());
374	    }
375	
376	    if (!args.outputAudioDir.empty())
377	    {
378	        std::filesystem::create_directories(args.outputAudioDir);
379	    }
380	
381	    if (!ttsRuntime->captureDecodingCUDAGraph(stream))
382	    {
383	        LOG_WARNING("CUDA graph capture failed for TTS decoding, proceeding without.");
384	    }
385	
386	    bool const profilerEnabled = args.dumpProfile || !args.profileOutputFile.empty();
387	    MemoryMonitor memoryMonitor;
388	    if (profilerEnabled)
389	    {
390	        setProfilingEnabled(true);
391	        memoryMonitor.start();
392	    }
393	
394	    LOG_INFO("Parsing input file...");
395	    auto input = parseInputFile(args.inputFile, args.batchSize);
396	
397	    nlohmann::json outputData;
398	    outputData["input_file"] = args.inputFile;
399	    outputData["responses"] = nlohmann::json::array();
400	
401	    bool hasFailedRequest = false;
402	    size_t failedCount = 0;
403	
404	    // Determine how many requests to bundle into each Talker call.
405	    // input.batchSize comes from `--batchSize` (or `batch_size` in input JSON, default 1).
406	    size_t const ttsBatchSize = std::max<size_t>(1, static_cast<size_t>(input.batchSize));
407	    LOG_INFO("Processing %zu request(s) with ttsBatchSize=%zu...", input.requests.size(), ttsBatchSize);
408	
409	    if (args.streaming)
410	    {
411	        check::check(
412	            code2wavRunner != nullptr, "--streaming requires a usable Code2Wav engine (chunks must be vocoded inline)");
413	        LOG_INFO("Streaming mode: chunkFrames=%d", args.chunkFrames);
414	    }
415	
416	    // Per-batch streaming context for a single TTS group. Lives only during one
417	    // handleAudioGeneration call; cleared between groups.
418	    struct StreamingBatchCtx
419	    {
420	        std::vector<__half> pcmBuffer; //!< Accumulated FP16 PCM samples (chunk-by-chunk concat)
421	        int32_t numFramesEmitted{0};   //!< Codec frames vocoded so far
422	        int32_t numChunkCalls{0};      //!< Total callback invocations (including final flush)
423	        bool finalSeen{false};
424	        bool vocoderFailed{false};
425	        cudaEvent_t ttfpaEvent{nullptr}; //!< Recorded on first vocoded chunk emit (time-to-first-playable-audio)
426	        bool ttfpaRecorded{false};
427	    };
428	
429	    for (size_t startIdx = 0; startIdx < input.requests.size(); startIdx += ttsBatchSize)
430	    {
431	        size_t const endIdx = std::min(startIdx + ttsBatchSize, input.requests.size());
432	        size_t const groupSize = endIdx - startIdx;
433	
434	        // Allocate per-batch streaming state up front so callbacks capture stable references.
435	        std::vector<StreamingBatchCtx> streamCtxs(args.streaming ? groupSize : 0);
436	        cudaEvent_t e2eStart{nullptr};
437	        if (args.streaming)
438	        {
439	            CUDA_CHECK(cudaEventCreateWithFlags(&e2eStart, cudaEventDefault));
440	            CUDA_CHECK(cudaEventRecord(e2eStart, stream));
441	            for (auto& ctx : streamCtxs)
442	            {
443	                CUDA_CHECK(cudaEventCreateWithFlags(&ctx.ttfpaEvent, cudaEventDefault));
444	            }
445	        }
446	
447	        std::vector<rt::Qwen3OmniTTSRuntime::TalkerGenerationRequest> groupReqs(groupSize);
448	        for (size_t k = 0; k < groupSize; ++k)
449	        {
450	            size_t const requestIdx = startIdx + k;
451	            auto& talkerReq = groupReqs[k];
452	            talkerReq.talkerTemperature = input.talkerTemperature;
453	            talkerReq.talkerTopK = input.talkerTopK;
454	            talkerReq.talkerTopP = input.talkerTopP;
455	            talkerReq.repetitionPenalty = input.repetitionPenalty;
456	            talkerReq.applyChatTemplate = input.applyChatTemplate;
457	            talkerReq.addGenerationPrompt = input.addGenerationPrompt;
458	            talkerReq.enableThinking = input.enableThinking;
459	            talkerReq.speakerName = input.requestSpeakers[requestIdx];
460	            talkerReq.maxAudioLength = input.maxAudioLength;
461	            talkerReq.messages = input.requests[requestIdx];
462	
463	            if (args.streaming)
464	            {
465	                talkerReq.streamingChunkFrames = args.chunkFrames;
466	                // Capture k (batch slot in group) + requestIdx (global request id) by value.
467	                talkerReq.onChunkReady = [&streamCtxs, &code2wavRunner, stream, k, requestIdx](
468	                                             std::vector<std::vector<int32_t>> const& chunkRvqCodes, bool isFinal) {
469	                    auto& ctx = streamCtxs[k];
470	                    ++ctx.numChunkCalls;
471	
472	                    if (!chunkRvqCodes.empty())
473	                    {
474	                        // Vocode this chunk independently. Code2Wav engine resets its KV per call so
475	                        // chunk boundaries lose a small amount of context; acceptable for streaming
476	                        // (RVQ codes still bit-exact vs. non-streaming).
477	                        size_t const numFrames = chunkRvqCodes.size();
478	                        size_t const numLayers = chunkRvqCodes[0].size();
479	                        std::vector<std::vector<int32_t>> transposed(numLayers, std::vector<int32_t>(numFrames));
480	                        for (size_t f = 0; f < numFrames; ++f)
481	                        {
482	                            for (size_t l = 0; l < numLayers; ++l)
483	                            {
484	                                transposed[l][f] = chunkRvqCodes[f][l];
485	                            }
486	                        }
487	                        rt::audioUtils::AudioData chunkAudio;
488	                        if (!code2wavRunner->generateWaveform(transposed, chunkAudio, stream))
489	                        {
490	                            LOG_WARNING(
491	                                "Streaming vocode failed for request %zu chunk %d", requestIdx, ctx.numChunkCalls);
492	                            ctx.vocoderFailed = true;
493	                        }
494	                        else if (chunkAudio.waveform && !chunkAudio.waveform->isEmpty())
495	                        {
496	                            __half const* src = static_cast<__half const*>(chunkAudio.waveform->rawPointer());
497	                            int64_t const samples = chunkAudio.waveform->getShape()[1];
498	                            ctx.pcmBuffer.insert(ctx.pcmBuffer.end(), src, src + samples);
499	                            if (!ctx.ttfpaRecorded && ctx.ttfpaEvent)
500	                            {
501	                                CUDA_CHECK(cudaEventRecord(ctx.ttfpaEvent, stream));
502	                                ctx.ttfpaRecorded = true;
503	                            }
504	                        }
505	                        ctx.numFramesEmitted += static_cast<int32_t>(numFrames);
506	                    }
507	                    if (isFinal)
508	                    {
509	                        ctx.finalSeen = true;
510	                    }
511	                };
512	            }
513	        }
514	
515	        rt::Qwen3OmniTTSRuntime::TalkerGenerationResponse talkerResp;
516	        bool const groupStatus = ttsRuntime->handleAudioGeneration(groupReqs, talkerResp, stream);
517	
518	        if (!groupStatus)
519	        {
520	            LOG_WARNING("TTS generation failed for batch group [%zu, %zu)", startIdx, endIdx);
521	            hasFailedRequest = true;
522	            failedCount += groupSize;
523	        }
524	
525	        for (size_t k = 0; k < groupSize; ++k)
526	        {
527	            size_t const requestIdx = startIdx + k;
528	            bool const requestStatus
529	                = groupStatus && k < talkerResp.batchRvqCodes.size() && !talkerResp.batchRvqCodes[k].empty();
530	
531	            // Build audio output: from streaming pcmBuffer if --streaming, else vocode-once-at-end.
532	            rt::audioUtils::AudioData audioOutput;
533	            bool hasAudio = false;
534	            std::vector<std::vector<int32_t>> const& framesCodes = (k < talkerResp.batchRvqCodes.size())
535	                ? talkerResp.batchRvqCodes[k]
536	                : std::vector<std::vector<int32_t>>{};
537	
538	            if (args.streaming && requestStatus)
539	            {
540	                auto const& ctx = streamCtxs[k];
541	                if (!ctx.finalSeen)
542	                {
543	                    LOG_WARNING("Streaming final flush missing for request %zu", requestIdx);
544	                }
545	                if (!ctx.vocoderFailed && !ctx.pcmBuffer.empty())
546	                {
547	                    int64_t const totalSamples = static_cast<int64_t>(ctx.pcmBuffer.size());
548	                    auto waveformTensor = std::make_shared<rt::Tensor>(
549	                        rt::Coords{1, totalSamples}, rt::DeviceType::kCPU, nvinfer1::DataType::kHALF, "streaming_pcm");
550	                    std::memcpy(waveformTensor->rawPointer(), ctx.pcmBuffer.data(), totalSamples * sizeof(__half));
551	                    audioOutput.waveform = waveformTensor;
552	                    audioOutput.sampleRate = code2wavRunner->getConfig().sampleRate;
553	                    audioOutput.hasWaveform = true;
554	                    hasAudio = true;
555	                    if (!args.outputAudioDir.empty())
556	                    {
557	                        std::string filename = format::fmtstr("audio_req%zu.wav", requestIdx);
558	                        std::filesystem::path audioPath = std::filesystem::path(args.outputAudioDir) / filename;
559	                        if (!saveAudioToWav(audioPath.string(), audioOutput))
560	                        {
561	                            LOG_WARNING("Failed to save audio: %s", audioPath.string().c_str());
562	                        }
563	                    }
564	
565	                    // Latency via CUDA events (same pattern as llm_inference.cpp Omni path).
566	                    // TTFC (time-to-first-codec) is shared across batches in a group — recorded by
567	                    // the runtime via mTtfaEnd at the joint first-sampling point of the bs=N prefill.
568	                    // TTFPA (time-to-first-playable-audio) is per-batch — recorded in the callback.
569	                    float ttfcMs = -1.0f;
570	                    float ttfpaMs = -1.0f;
571	                    auto const ttfaEnd = ttsRuntime->getTtfaEndEvent();
572	                    // e2eStart was queued before generation but never explicitly synced; in the
573	                    // current single-stream layout the later sync of ttfaEnd / ttfpaEvent implicitly
574	                    // serializes after e2eStart, so cudaEventElapsedTime is well-defined. Sync e2eStart
575	                    // explicitly anyway — defensive against future multi-stream layouts.
576	                    if (e2eStart)
577	                    {
578	                        CUDA_CHECK(cudaEventSynchronize(e2eStart));
579	                    }
580	                    if (e2eStart && ttfaEnd)
581	                    {
582	                        CUDA_CHECK(cudaEventSynchronize(ttfaEnd));
583	                        CUDA_CHECK(cudaEventElapsedTime(&ttfcMs, e2eStart, ttfaEnd));
584	                    }
585	                    if (e2eStart && ctx.ttfpaRecorded && ctx.ttfpaEvent)
586	                    {
587	                        CUDA_CHECK(cudaEventSynchronize(ctx.ttfpaEvent));
588	                        CUDA_CHECK(cudaEventElapsedTime(&ttfpaMs, e2eStart, ctx.ttfpaEvent));
589	                    }
590	                    LOG_INFO("[stream req %zu] chunks=%d frames=%d samples=%ld TTFC=%.1fms TTFPA=%.1fms", requestIdx,
591	                        ctx.numChunkCalls, ctx.numFramesEmitted, totalSamples, ttfcMs, ttfpaMs);
592	
593	                    // For bs=1 groups, populate mOmniLatencyMetrics so downstream profilers see it
594	                    // (matches the contract llm_inference.cpp uses for Omni streaming).
595	                    if (groupSize == 1)
596	                    {
597	                        auto& latency = ttsRuntime->getMutableOmniLatencyMetrics();
598	                        if (ttfcMs >= 0.0f)
599	                            latency.timeToFirstAudioCodeMs = ttfcMs;
600	                        if (ttfpaMs >= 0.0f)
601	                            latency.timeToFirstPlayableAudioMs = ttfpaMs;
602	                    }
603	                }
604	            }
605	            else if (requestStatus && code2wavRunner && !framesCodes.empty())
606	            {
607	                size_t const numFrames = framesCodes.size();
608	                size_t const numLayers = framesCodes[0].size();
609	                std::vector<std::vector<int32_t>> transposed(numLayers, std::vector<int32_t>(numFrames));
610	                for (size_t f = 0; f < numFrames; ++f)
611	                {
612	                    for (size_t l = 0; l < numLayers; ++l)
613	                    {
614	                        transposed[l][f] = framesCodes[f][l];
615	                    }
616	                }
617	
618	                if (code2wavRunner->generateWaveform(transposed, audioOutput, stream))
619	                {
620	                    hasAudio = true;
621	                    if (!args.outputAudioDir.empty())
622	                    {
623	                        std::string filename = format::fmtstr("audio_req%zu.wav", requestIdx);
624	                        std::filesystem::path audioPath = std::filesystem::path(args.outputAudioDir) / filename;
625	                        if (!saveAudioToWav(audioPath.string(), audioOutput))
626	                        {
627	                            LOG_WARNING("Failed to save audio: %s", audioPath.string().c_str());
628	                        }
629	                    }
630	                }
631	                else
632	                {
633	                    LOG_WARNING("Code2Wav failed for request %zu", requestIdx);
634	                }
635	            }
636	
637	            if (args.dumpOutput && requestStatus && hasAudio)
638	            {
639	                int64_t samples = (!audioOutput.waveform || audioOutput.waveform->isEmpty())
640	                    ? 0
641	                    : audioOutput.waveform->getShape()[1];
642	                LOG_INFO("[%zu] Audio: %ld samples (%.2fs)", requestIdx, samples,
643	                    static_cast<float>(samples) / audioOutput.sampleRate);
644	            }
645	
646	            // Build per-request JSON
647	            nlohmann::json responseJson;
648	            responseJson["request_idx"] = requestIdx;
649	            responseJson["output_text"] = requestStatus ? "" : "FAILED";
650	
651	            nlohmann::json messagesJson = nlohmann::json::array();
652	            for (auto const& msg : input.requests[requestIdx])
653	            {
654	                nlohmann::json m;
655	                m["role"] = msg.role;
656	                m["content"] = msg.contents.empty() ? "" : msg.contents[0].content;
657	                messagesJson.push_back(std::move(m));
658	            }
659	            responseJson["messages"] = std::move(messagesJson);
660	
661	            if (requestStatus && hasAudio && !args.outputAudioDir.empty())
662	            {
663	                std::string filename = format::fmtstr("audio_req%zu.wav", requestIdx);
664	                std::filesystem::path audioPath = std::filesystem::path(args.outputAudioDir) / filename;
665	                int64_t samples = (audioOutput.waveform && !audioOutput.waveform->isEmpty())
666	                    ? audioOutput.waveform->getShape()[1]
667	                    : 0;
668	                responseJson["audio_file"] = audioPath.string();
669	                responseJson["audio_samples"] = samples;
670	                responseJson["audio_sample_rate"] = audioOutput.sampleRate;
671	                responseJson["audio_duration_ms"] = static_cast<int64_t>(1000.0 * samples / audioOutput.sampleRate);
672	            }
673	
674	            if (requestStatus && !framesCodes.empty() && !args.outputAudioDir.empty())
675	            {
676	                int64_t const numFrames = static_cast<int64_t>(framesCodes.size());
677	                int64_t const numCodes = framesCodes.empty() ? 0 : static_cast<int64_t>(framesCodes[0].size());
678	                std::vector<int32_t> flat;
679	                flat.reserve(numFrames * numCodes);
680	                for (auto const& frame : framesCodes)
681	                {
682	                    flat.insert(flat.end(), frame.begin(), frame.end());
683	                }
684	                std::vector<rt::Tensor> tensors;
685	                tensors.emplace_back(flat.data(), rt::Coords{numFrames, numCodes}, rt::DeviceType::kCPU,
686	                    nvinfer1::DataType::kINT32, "rvq_codes");
687	                std::string filename = format::fmtstr("rvq_req%zu.safetensors", requestIdx);
688	                std::filesystem::path stPath = std::filesystem::path(args.outputAudioDir) / filename;
689	                safetensors::saveSafetensors(stPath, tensors, stream);
690	                responseJson["rvq_file"] = stPath.string();
691	            }
692	
693	            outputData["responses"].push_back(responseJson);
694	        }
695	
696	        if (args.streaming)
697	        {
698	            for (auto& ctx : streamCtxs)
699	            {
700	                if (ctx.ttfpaEvent)
701	                    cudaEventDestroy(ctx.ttfpaEvent);
702	            }
703	            if (e2eStart)
704	                cudaEventDestroy(e2eStart);
705	        }
706	    }
707	
708	    LOG_INFO("Done: %zu/%zu requests succeeded", input.requests.size() - failedCount, input.requests.size());
709	    if (failedCount > 0)
710	    {
711	        LOG_ERROR("%zu request(s) failed", failedCount);
712	    }
713	
714	    if (profilerEnabled)
715	    {
716	        setProfilingEnabled(false);
717	        memoryMonitor.stop();
718	    }
719	
720	    if (args.dumpProfile)
721	    {
722	        std::ostringstream ss;
723	        ss << "\n=== Performance Summary ===\n";
724	        outputTalkerProfile(ss, ttsRuntime->getMetrics());
725	        outputMemoryProfile(ss, memoryMonitor);
726	        ss << "===========================\n";
727	        LOG_INFO("%s", ss.str().c_str());
728	    }
729	
730	    if (!args.profileOutputFile.empty())
731	    {
732	        try
733	        {
734	            nlohmann::json profileJson;
735	            addJsonTalkerSummary(profileJson, ttsRuntime->getMetrics());
736	            addJsonTimingStages(profileJson);
737	            addJsonMemorySummary(profileJson, memoryMonitor);
738	
739	            std::ofstream profileFile(args.profileOutputFile);
740	            if (profileFile.is_open())
741	            {
742	                profileFile << profileJson.dump(2);
743	                LOG_INFO("Profile saved to: %s", args.profileOutputFile.c_str());
744	            }
745	            else
746	            {
747	                LOG_ERROR("Failed to open profile output file: %s", args.profileOutputFile.c_str());
748	            }
749	        }
750	        catch (std::exception const& e)
751	        {
752	            LOG_ERROR("Failed to write profile: %s", e.what());
753	        }
754	    }
755	
756	    if (!args.outputFile.empty())
757	    {
758	        try
759	        {
760	            std::ofstream out(args.outputFile);
761	            if (out.is_open())
762	            {
763	                out << outputData.dump(2);
764	                LOG_INFO("Output saved to: %s", args.outputFile.c_str());
765	            }
766	            else
767	            {
768	                LOG_ERROR("Failed to open output file: %s", args.outputFile.c_str());
769	            }
770	        }
771	        catch (std::exception const& e)
772	        {
773	            LOG_ERROR("Failed to write output file: %s", e.what());
774	        }
775	    }
776	
777	    cudaStreamDestroy(stream);
778	    LOG_INFO("=== Done ===");
779	    return hasFailedRequest ? EXIT_FAILURE : EXIT_SUCCESS;
780	}
